window.__LEX={"G2000":"<h1>episphales</h1>\n<p>Strong n° 2000 <i>Prononciation [ep-ee-sfal-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prompt à la chute, peu sûr, dangereux, périlleux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπισφαλής, ής, ές</b> <span>[ᾰ]</span><br><b>      1</b> sujet à glisser, chancelant, instable, PLAT. <i>Rsp. 497</i> d ; DÉM. <i>22, 14 ;</i> ARSTT. <i>Nic. 8, 1, 1 ;</i> POL. <i>2, 5, 25 ;</i><br><b>      2</b> qui porte à glisser, où l’on glisse, glissant, <i>en parl. d’un lieu,</i> POL. <i>1, 54, 3 ;</i> HDN <i>7, 2, 11 ;</i> ἐπ. εἴς <i>ou</i> πρός τι, PLUT. <i>M. 653</i> c, vers qqe ch. ; <i>d’où</i> hasardeux, dangereux, HPC. <i>V. med. 11 ;</i> POL. <i>1, 66, 12, etc</i>.<br><span>•<i> Cp</i>. -έστερος, DÉM. <i>22, 14 ;</i> ARSTT. <i>Nic. 8, 1</i>. <i>• Sup</i>. -έστατος, POL. <i>2, 29, 2</i>.<br><span><b>Étym</b>. ἐπισφάλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επισφαλης - ἐπισφαλής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2001":"<h1>epischo</h1>\n<p>Strong n° 2001 <i>Prononciation [ep-is-khoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner une force complémentaire, rendre fort, insister, énergique</li>\n<li>recevoir une plus grande force</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπ·ισχύω :<br>   I <i>tr.</i></b> rendre fort <i>ou</i> puissant, XÉN. <i>Œc. 11, 13 ;</i><br><b>   II <i>intr</i>.<br>      1</b> avoir <i>ou</i> prendre de la force, TH. <i>C.P. 2, 1, 4 ;</i> DS. <i>5, 59 ;</i><br><b>      2</b> insister avec force, NT. <i>Luc. 28, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επ-ισχυω - ἐπισχύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2002":"<h1>episoreuo</h1>\n<p>Strong n° 2002 <i>Prononciation [ep-ee-so-ryoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>entasser, accumuler en piles, amasser encore, s'entourer d'un grand nombre de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·σωρεύω</b>, ajouter à un tas, entasser encore, PLUT. <i>M. 830</i> a ; ARR. <i>Epict. 1, 10, 5 ;</i> ATH. <i>123</i> e.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επισωρευω - ἐπισωρεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2003":"<h1>epitage</h1>\n<p>Strong n° 2003 <i>Prononciation [ep-ee-tag-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une injonction, un mandat, un ordre, commandement, prescription</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιταγή, ῆς (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> ordre, commandement, SPT. <i>1Esdr. 1, 16 ;</i> POL. <i>13, 4, 3 ;</i> DS. <i>1, 70 ;</i><br><b>      2</b> tribut imposé, POL. <i>21, 4, 1</i>.<br><span><b>Étym</b>. ἐπιτάσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιταγη - ἐπιταγή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G2004":"<h1>epitasso</h1>\n<p>Strong n° 2004 <i>Prononciation [ep-ee-tas'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enjoindre, ordonner, commander, charger de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τάσσω</b>, <i>att</i>. <b>-τάττω</b> <span>(<i>f</i>. ἐπιτάξω, <i>ao</i>. ἐπέταξα, <i>pf</i>. ἐπιτέταχα)</span><br><b>   I</b> (τάσσω, ranger) :<br><b>      1</b> ranger à côté : τινά τινι, XÉN. <i>Hell. 1, 6, 29, ou</i> τινὰ ἔς τινα, HDT. <i>7, 85,</i> une personne (une troupe, <i>etc</i>.) auprès d’une autre ;<br><b>      2</b> ranger par derrière : ὄπισθεν τοῦ πεζοῦ τὴν ἵππον, HDT. <i>1, 80,</i> la cavalerie derrière l’infanterie ; <i>p. suite,</i> placer en réserve, comme corps de réserve, PLUT. <i>Luc. 31 ; au pass</i>. HDT. <i>7, 41 ; particul</i>. placer en arrière pour la garde des fourgons <i>ou</i> des bagages, THC. <i>5, 72 ;</i><br><b>      3</b> <i>t. de gr</i>. placer en outre, employer comme mot explétif, <i>en parl. du pron</i>. αὐτός, DYSC. <i>Pron. 301, 314, 391 ; Synt. 138, 23, 114 ;</i><br><b>      4</b> ranger en face de <i>ou</i> contre, ARR. <i>An. 1, 24 ;</i><br><b>   II</b> (τάσσω, ordonner) :<br><b>      1</b> ordonner, prescrire : τι, HDT. <i>5, 111 ;</i> SOPH. <i>O.C. 839, etc. ;</i> qq. ch. : τί τινι, HDT. <i>4, 45,</i> qqe ch. à qqn ; τινὶ ποιεῖν τι, HDT. <i>4, 83 ;</i> AR. <i>Vesp. 69,</i> à qqn de faire qqe ch. ; <i>d’où au pass</i>. ἐπιτάττεσθαί τι, THC. <i>1, 140,</i> recevoir qqe ordre ; <i>avec l’inf</i>. ἐπιτάττεσθαι ποιεῖν τι, PLAT. <i>Leg. 925</i> e, recevoir l’ordre de faire qqe ch. ; τὰ ἐπιτασσόμενα, HDT. <i>1, 115,</i> les ordres donnés ;<br><b>      2</b> employer le mode impératif, ARSTT. <i>Poet. 19, 8 ;</i><br><b><i>Moy.</i></b> :<br><b>   I. 1</b> ranger à côté, THC. <i>6, 67 ;</i><br><b>      2</b> ranger par derrière, en réserve, XÉN. <i>An. 6, 5, 9 ;</i><br><b>      3</b> ordonner, prescrire, PLAT. <i>Leg. 658</i> b ;<br><b>   II</b> se laisser donner des ordres, se soumettre à des ordres, EUR. <i>Suppl. 521</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτασσω - ἐπιτάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (4)</li>\n<li>Luc (4)</li>\n<li>Actes (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G2005":"<h1>epiteleo</h1>\n<p>Strong n° 2005 <i>Prononciation [ep-ee-tel-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener à une fin, accomplir, parfaire, exécuter, compléter\n<ol type=\"a\">\n<li>prendre sur soi</li>\n<li>terminer pour soi-même\n<ol>\n<li>cesser de</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>désigner, nommer, imposer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τελέω-ῶ</b> <span>(<i>f</i>. έσω, <i>ao</i>. ἐπετέλεσα, <i>pf</i>. ἐπιτετέλεκα)</span><br><b>      1</b> exécuter, accomplir : τι, THC. <i>1, 70, etc.,</i> qqe ch. ; τὰ ἐπιτασσόμενα, HDT. <i>1, 115,</i> les ordres ; φήμην, χρηστήριον, HDT. <i>1, 13, etc</i>. accomplir un oracle ; <i>au pass</i>. s’effectuer, s’accomplir, <i>en parl. de mouvements,</i> HÉRON <i>Aut. 262 ;</i><br><b>      2</b> <i>particul</i>. acquitter (une dette, <i>etc</i>.) : ἐπ. ἀποφορήν, HDT. <i>2, 109 ; 8, 41, etc</i>. acquitter une contribution ; θυσίαν, PLUT. <i>M. 119</i> a ; θυσίας, HDT. <i>2, 63,</i> accomplir un sacrifice, des sacrifices ; ἑορτάς, HDT. <i>4, 186,</i> célébrer des fêtes ; <i>d’où abs</i>. faire un sacrifice : ἐπ. τινι, EL. <i>V.H. 12, 61,</i> offrir un sacrifice à un dieu ; γάμους, ATH. <i>576</i> a, <i>609</i> f, célébrer un mariage ; <i>en parl. de vœux, de promesses,</i> HDT. <i>1, 86 ;</i> THC. <i>1, 138 ;</i><br><b>      3</b> imposer ; δίκην τινί, PLAT. <i>Leg. 10 fin,</i> une peine à qqn ;<br><b><i>Moy.</i></b> mettre à exécution, accomplir, réaliser ; τὸν θάνατον, XÉN. <i>Ap. 33,</i> subir la mort ; τὰ τοῦ γήρως, XÉN. <i>Mem. 4, 8, 8,</i> subir les inconvénients de la vieillesse ; <i>cf</i>. PLAT. <i>Phil. 27</i> c ; POL. <i>1, 40, 16 ;</i> DH. <i>10, 42</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Formes ion. : act. prés. 3 pl</i>. ἐπιτελεῦσι, HDT. <i>5, 49 ; inf</i>. ἐπιτελέειν, HDT. <i>1, 90 ; impf</i>. ἐπετέλεον, HDT. <i>1, 115 ; pass. prés. part</i>. ἐπιτελεύμενον, HDT. <i>2, 152 ; impf. 3 sg</i>. ἐπετελέετο, HDT. <i>9, 64</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτελεω - ἐπιτελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 10 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2006":"<h1>epitedeios</h1>\n<p>Strong n° 2006 <i>Prononciation [ep-ee-tay'-di-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>propre à, convenable, commode, avantageux</li>\n<li>nécessaire, en particulier les nécessités de la vie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιτήδειος, α, ον</b> <span>[ῐ]</span><br><b>   I</b> <i>adj. :</i><br><b>      1</b> convenable, approprié : τοῖς Λακεδαιμονίοις, THC. <i>5, 81,</i> aux Lacédémoniens, <i>en parl. du régime oligarchique ; cf</i>. LYS. <i>134, 23 ;</i> ἐπ. ἔς τι, HDT. <i>1, 115 ;</i> THC. <i>7, 20, 74 ;</i> πρός τι, PLAT. <i>Rsp. 390</i> b, qui convient pour faire qqe ch. ; <i>avec l’inf</i>. χωρίον ἐπ. ἐνιππεῦσαι, HDT. <i>6, 102,</i> terrain où la cavalerie peut manœuvrer ; στρατοπεδεύεσθαι ἐν ἐπιτηδείῳ, THC. <i>2, 81,</i> camper dans une position favorable ; <i>abs</i>. τὸ ἐπιτήδειον, XÉN. <i>Vect. 4, 38 ; d’ord. au plur</i>. τὰ ἐπιτήδεια, HDT. <i>2, 174 ;</i> THC. <i>2, 23 ;</i> XÉN. <i>Cyr. 4, 2, 46 ; 53, 34 ; Hell. 2, 2, 1 ; 6, 5, 50, etc</i>. les choses nécessaires à la vie ; <i>en parl. de pers</i>. ἐπιτήδειος ὀστρακισθῆναι, AND. <i>34, 2 ;</i> ἐπ. παθεῖν τι, DÉM. <i>610, 20,</i> qui méritait d’être frappé d’ostracisme, qui mérite de souffrir qqe ch. ; ἐπιτήδειόν ἐστι <i>avec l’inf</i>. HDT. <i>4, 158 ;</i> XÉN. <i>An. 7, 1, 39,</i> il est utile <i>ou</i> convenable de ;<br><b>      2</b> <i>en parl. de pers</i>. serviable, obligeant, HDT. <i>4, 72 ;</i> THC. <i>3, 40 ;</i> ἐπ. τινι, THC. <i>4, 78,</i> serviable pour qqn ; <i>d’où</i> qui se conforme à : τῷ πατρί, HDT. <i>3, 52,</i> à la volonté de son père ; ἐπ. τοῖς πρασσομένοις, THC. <i>8, 54,</i> favorable à ce qui se fait ; <i>abs</i>. serviable, obligeant, HDT. <i>4, 72 ;</i> THC. <i>3, 40 ;</i><br><b>      3</b> <i>p. suite,</i> favorable, avantageux, <i>en parl. de présages, de traités, etc</i>. HDT. <i>6, 97 ; 9, 37 ; abs</i>. οὐδὲν ηὕροντο ἐπιτήδειον, THC. <i>1, 58,</i> ils n’y trouvèrent aucun avantage ; καταστῆσαι ἐς τὸ ἐπιτήδειον, THC. <i>4, 76,</i> régler qqe ch. selon ses intérêts ;<br><b>   II</b> <i>subst</i>. qui a des relations avec qqn, <i>d’où</i> ὁ ἐπ. ami (<i>cf. lat</i>. necessarius) : τινι, THC. <i>4, 78 ;</i> τινος, THC. <i>5, 64, etc</i>. lié avec qqn, familier de qqn.<br><span>•<i> Cp</i>. -ότερος, THC. <i>4, 54 ; ou</i> -έστερος, DÉMOCR. (EUST. <i>1441, 16</i>). <i>• Sup</i>. -ότατος, XÉN. <i>Cyr. 6, 1, 22 ;</i> PLAT. <i>Leg. 817</i> d, <i>Rsp. 433</i> a ; <i>Phædr. 231</i> d ; ARSTT. <i>Rhet. 1, 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἐπιτήδεος, HDT. <i>ll. cc., d’où cp</i>. -εώτερος, HDT. <i>9, 25 ;</i> <i>• Sup</i>. -εώτατος, HDT. <i>1, 115 ; 3, 70 ; 6, 102</i>.<br><span><b>Étym</b>. ἐπιτηδές.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτηδειος - ἐπιτήδειος</font>\n<br><br>vient de 'epitedes' (assez)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2007":"<h1>epitithemi</h1>\n<p>Strong n° 2007 <i>Prononciation [ep-ee-tith'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>Voix active\n<ol type=\"a\">\n<li>poser ou étendre sur (les mains)</li>\n<li>ajouter, additionner à</li>\n</ol>\n</li>\n<li>Voix médiane\n<ol type=\"a\">\n<li>ce qui est imposé</li>\n<li>se poser ou se jeter sur, infliger (des coups)</li>\n<li>attaquer, faire l'assaut de quelqu'un, maltraiter</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τίθημι</b> <span>(<i>f</i>. ἐπιθήσω, <i>etc</i>.)</span><br><b>A</b> poser sur :<br><b>   I</b> <i>au propre :</i> κεφαλῇ ἐπ. καλύπτρην, OD. <i>5, 232,</i> poser un voile sur sa tête ; τῷ ἰσχυροτέρῳ πλεῖον βάρος ἐπ. XÉN. <i>Œc. 17, 9,</i> charger le plus fort d’un plus lourd fardeau ; <i>cf</i>. THC. <i>7, 36 ;</i> EUR. <i>I.T. 702 ; avec le gén</i>. ἐπ. λεχέων, IL. <i>24, 589,</i> placer (qqn) sur un lit ; <i>avec une prép</i>. ἀσκοὺς ἐπ. ἐπὶ τῶν ὄνων, HDT. <i>2, 121,</i> placer des outres sur les ânes ; ἐπὶ πυρᾶς ἐπ. νεκρόν, THC. <i>2, 52,</i> placer un mort sur un bûcher ; <i>avec un seul rég</i>. ἐπ. εἴδατα, OD. <i>1, 140,</i> placer des mets sur une table ; λιϐανωτόν, AR. <i>Nub. 425 (cf</i>. ANT. <i>1, 18 Baiter-Sauppe</i>) placer de l’encens sur l’autel ; φάρμακα, IL. <i>4, 190,</i> appliquer des onguents ; στήλην, HDT. <i>7, 183,</i> poser une stèle ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> appliquer : φρένα τινί, IL. <i>10, 46,</i> son esprit à qqe ch. ;<br><b>      2</b> attribuer : ὄνομα, HDT. <i>5, 68 ;</i> PLAT. <i>Conv. 205</i> b, donner un nom (à qqn) ; πίστιν, DÉM. <i>165, 2,</i> accorder sa confiance, ajouter foi ;<br><b>      3</b> procurer, <i>en b. part :</i> μισθόν τινι, POL. <i>5, 18, 8,</i> accorder une récompense <i>ou</i> donner un salaire à qqn ; κράτος τινί, IL. <i>1, 509 ;</i> κῦδός τινι, IL. <i>23, 400,</i> procurer de la puissance, de la gloire à qqn ;<br><b>      4</b> imposer, infliger : ἐπ. πληγάς, NT. <i>Luc. 10, 30,</i> donner des coups (à qqn) ; <i>p. anal</i>. ἐπ. ἄλγεά τινι, IL. <i>2, 39,</i> infliger des douleurs à qqn ; <i>fig</i>. τινὶ δίκην ἐπ. HDT. <i>1, 120 ;</i> EUR. <i>Or. 576 ;</i> PLAT. <i>Ap. 28</i> e ; PLUT. <i>Fab. 9,</i> infliger un châtiment à qqn ; τιμωρίαν ὑπέρ τινος ἐπ. DÉM. <i>1392, 9,</i> tirer vengeance de qqe ch. ; ζημίαν τινὶ ἐπ. HDT. <i>4, 43 ;</i> XÉN. <i>Cyr. 1, 2, 2,</i> infliger une amende à qqn ; τίμημα ἐπ. ESCHN. <i>30, 4,</i> imposer une amende ; θάνατον δίκην ἐπ. τινί, PLAT. <i>Leg. 838</i> c, infliger comme peine à qqn la mort ; ἀνάγκην ἐπ. <i>avec l’inf</i>. imposer l’obligation de, XÉN. <i>Lac. 10, 7 ; avec</i> μή <i>et l’inf</i>. ἐπ. μὴ τυγχάνειν, XÉN. <i>Lac. 3, 3,</i> imposer comme peine de ne pas, <i>etc. ;</i><br><b>      5</b> faire reposer sur, mettre à la charge de : ἐπιστολήν τινι, DÉM. <i>915, 17,</i> confier une lettre à qqn ; ἐπ. τι ἐς Αἴγυπτον, HDT. <i>3, 42,</i> confier à qqn un message pour l’Égypte ; ἐς Μυτιλήνην, HDT. <i>5, 95,</i> pour Mytilène ;<br><b>      6</b> poser par-dessus <i>ou</i> en sus, ajouter : ἄλλα, IL. <i>7, 364, etc. ;</i> OD. <i>22, 62,</i> d’autres choses ; ἐτέων μάλα πολλά, HÉS. <i>O. 694,</i> beaucoup d’années encore ; <i>abs</i>. ajouter à une chose ce qui l’achève : τέλος μύθῳ <i>ou</i> μύθοις, IL. <i>19, 107 ; 20, 369, etc</i>. mettre fin à des paroles ; κολοφῶνα τῇ σοφίᾳ, PLAT. <i>Euthyd. 301</i> e, mettre le comble à la sagesse ;<br><b>B</b> poser par devant : λίθον θύρῃσιν, OD. <i>13, 370,</i> placer une pierre devant la porte ; νέφος ἐπιθεῖναι, IL. <i>5, 751 ; 8, 395,</i> voiler le ciel d’un nuage ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr</i>.<br>      1</b> placer sur soi <i>ou</i> pour soi sur (qqe ch.) : ἐπ. σῖτον ἐπὶ τὴν τράπεζαν, XÉN. <i>Cyr. 8, 2, 3,</i> servir des mets sur la table ; <i>fig</i>. imposer : θανάτου ζημίαν, THC. <i>2, 24,</i> la peine de mort ; φόϐον τινί, XÉN. <i>Cyr. 4, 5, 41,</i> inspirer de la crainte à qqn ;<br><b>      2</b> faire reposer sur, mettre à la charge de : τί τινι, HDT. <i>1, 111,</i> confier qqe ch. à qqn, charger qqn de qqe ch. ; τινι ποιεῖν τι, ATH. <i>465</i> d, confier à qqn le soin de faire qqe ch. ;<br><b>      3</b> placer devant : πύλας τοῖς ὠσί, PLAT. <i>Conv. 218</i> b, <i>litt</i>. mettre des portes devant ses oreilles, se boucher les oreilles ;<br><b>      4</b> placer au delà, d’où remettre, différer, HPC. <i>7, 18 ;</i><br><b>   II <i>intr.</i></b> s’attacher à, <i>d’où :</i><br><b>      1</b> s’appliquer à : ναυτιλίῃσι, HDT. <i>1, 1,</i> s’adonner la navigation ; τοῖς πολιτικοῖς, PLAT. <i>Gorg. 527</i> d, aux affaires de l’État ; <i>avec l’inf</i>. γράφειν τι, ISOCR. <i>82</i> a, s’appliquer à écrire qqe ch. ;<br><b>      2</b> <i>p. suite,</i> s’efforcer de, tâcher de, essayer de, <i>inf</i>. PLAT. <i>Soph. 242</i> b ; ISOCR. <i>82</i> a ;<br><b>      3</b> <i>avec idée de tendance :</i> ἐπ. τῇ ἀρχῇ, PLUT. <i>M. 772</i> d ; HDN <i>6, 2, 17 ;</i> τῇ τυραννίδι, LYCURG. <i>165, 27,</i> aspirer à l’empire, à la tyrannie ;<br><b>      4</b> <i>avec idée d’hostilité,</i> s’attaquer à, <i>dat</i>. HDT. <i>1, 26, 178 ; 3, 145 ; 5, 31, etc. ;</i> THC. <i>3, 39, 72 ; 6, 61 ;</i> XÉN. <i>Cyr. 7, 1, 22 ; Ath. 3, 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτιθημι - ἐπιτίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 41 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (9)</li>\n<li>Luc (6)</li>\n<li>Jean (2)</li>\n<li>Actes (14)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2008":"<h1>epitimao</h1>\n<p>Strong n° 2008 <i>Prononciation [ep-ee-tee-mah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>montrer du respect, honorer</li>\n<li>élever le prix de</li>\n<li>adjuger, décerner, dans le sens de pénalité méritée</li>\n<li>taxer selon la faute, estimer, réprimander, réprouver, censurer sévèrement, adresser des reproches, reprendre\n<ol type=\"a\">\n<li>réprimander d'une manière tranchante, menacer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τιμάω-ῶ</b> <span>[τῑ]</span><br><b>      1</b> accorder des honneurs à, <i>particul</i>. rendre des honneurs funèbres : τινα, HDT. <i>6, 39,</i> à qqn ;<br><b>      2</b> élever le prix de, faire renchérir, DIPH. (ATH. <i>228</i> b) ; EL. <i>N.A. 10, 50 ; au pass</i>. renchérir, DÉM. <i>918, 20, etc. ;</i><br><b>      3</b> infliger : δίκην, HDT. <i>4, 43,</i> une peine ; <i>p. ext</i>. infliger un blâme, faire un reproche : τινι, ISOCR. <i>170</i> a ; DÉM. <i>246, 9 ; postér</i>. ἔν τινι, SPT. <i>Zach. 3, 2,</i> à qqn ; τινί τι, PLAT. <i>Phædr. 237</i> c ; τινι περί τι, POL. <i>8, 11, 1 ; ou</i> ἐπί τινι, POL. <i>7, 11, 9,</i> reprocher qqe ch. à qqn ; τινι ὅτι (<i>ou</i> ὡς) PLAT. <i>Theæt. 169</i> d ; DÉM. <i>160, 15,</i> reprocher à qqn que ; τινι ἵνα μή, NT. <i>Matth. 12, 16 ;</i> τινι ἵνα, NT. <i>Matth. 20, 31,</i> reprocher à qqn de ne pas, de, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἐπιτιμέω, HDT. <i>4, 43, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτιμαοω - ἐπιτιμάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 29 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (9)</li>\n<li>Luc (12)</li>\n<li>2 Timothée (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2009":"<h1>epitimia</h1>\n<p>Strong n° 2009 <i>Prononciation [ep-ee-tee-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>punition, châtiment, peine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιτιμία, ας (ἡ)</b> <span>[τῑ]</span><br><b>      1</b> peine, châtiment, SPT. <i>Sap. 3, 10 ;</i> NT. <i>2Cor. 2, 6 ;</i><br><b>      2</b> jouissance des droits civils, <i>t. de droit att</i>. DÉM. <i>549, 10 ;</i> ESCHN. <i>39, 42 ;</i><br><b>      3</b> <i>par euphém. p</i>. αἰδοῖον, ARTÉM. <i>1, 45</i>.<br><span><b>Étym</b>. ἐπιτίμιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτιμια - ἐπιτιμία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2010":"<h1>epitrepo</h1>\n<p>Strong n° 2010 <i>Prononciation [ep-ee-trep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envoyer vers, transférer, commettre, instruire</li>\n<li>permettre, accorder, donner la permission</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τρέπω</b> <span>(<i>f</i>. -τρέψω, <i>ao.1</i> ἐπέτρεψα, <i>ao.2</i> ἐπέτραπον ; <i>pass. ao.1</i> ἐπετρέφθην, <i>ao.2</i> ἐπετράπην, <i>pf</i>. ἐπιτέτραμμαι)</span><br><b>   I <i>tr.</i></b> tourner vers <i>ou</i> sur, <i>d’où :</i><br><b>      1</b> transmettre, léguer : τί τινι, OD. <i>7, 149,</i> qqe ch. à qqn ;<br><b>      2</b> remettre, confier : τινί τι, OD. <i>2, 226 ; 15, 24 ;</i> HDT. <i>1, 64 ; 4, 202 ; 6, 26 ;</i> THC. <i>2, 65 ; 5, 99 ;</i> XÉN. <i>An. 5, 9, 31,</i> qqe ch. à qqn ; τινὰ ἰατρῷ, ANT. <i>127, 38,</i> remettre qqn aux mains d’un médecin ; <i>particul</i>. confier à qqn l’éducation d’un enfant, PLAT. <i>Lach. 200</i> d ; αὑτὸν ἐλπίσιν, EUR. <i>fr. 913,</i> s’abandonner à des espérances ; <i>avec l’inf. :</i> ἐπ. τινὶ πονέεσθαι, IL. <i>10, 116,</i> remettre à qqn le soin d’accomplir une tâche pénible ; τινὶ κρῖναι περί τινος, PLAT. <i>Ap. 35</i> d, remettre à qqn le soin de décider sur le sort d’un autre ; <i>d’où au pass</i>. ἐπιτραφθεὶς τὴν ἀρχήν, HDT. <i>1, 7,</i> à qui l’on a remis le pouvoir ; ἐπιτετραμμένος τὴν φυλακήν, THC. <i>1, 126,</i> chargé de la garde ; <i>abs</i>. abandonner : νίκην τινί, IL. <i>21, 473,</i> la victoire à qqn ; τινὶ ποιεῖν τι. AR. <i>Pl. 1078 ; ou</i> τινὰ ποιεῖν τι, XÉN. <i>An. 7, 7, 8,</i> confier à qqn le soin de faire qqe ch. ; οὐδενὶ ἐπ. κακῷ εἶναι, XÉN. <i>An. 3, 2, 31,</i> ne permettre à personne d’être méchant ; <i>avec un part</i>. μὴ ἐπ. τινὶ ἀδικοῦντι, PLAT. <i>Euthyphr. 5</i> e, ne pas permettre à qqn d’être injuste ; <i>cf</i>. HDT. <i>2, 120 ; abs</i>. donner toute liberté, PD. <i>O. 6, 36 ;</i> THC. <i>1, 71 ;</i> AR. <i>Pl. 915 ;</i><br><b>      3</b> ordonner : τι, PLAT. <i>Leg. 78</i> h, qqe ch. ; τινὰ ποιεῖν τι, XÉN. <i>An. 6, 3, 11,</i> à qqn de faire qqe ch. ;<br><b>   II</b> <i>intr. en appar. (s.-e</i>. ἑαυτόν) :<br><b>      1</b> s’en remettre à, se confier à : θεοῖσιν, OD. <i>21, 279 ;</i> τῷ μαντείῳ, THC. <i>1, 28,</i> aux dieux, à l’oracle ; τοῖς δικασταῖς, DÉM. <i>78, 18,</i> à qqn, aux juges ; τινὶ περί τινος, PLAT. <i>Gorg. 512</i> e ; DÉM. <i>813, 2,</i> remettre à qqn le soin de décider de qqn <i>ou</i> de qqe ch. ;<br><b>      2</b> s’abandonner à : γήραϊ, IL. <i>10, 79,</i> se laisser abattre par la vieillesse ; ταῖς ἐπιθυμίαις, PLAT. <i>Leg. 802</i> b ; τῇ ὀργῇ, DH. <i>7, 45,</i> se laisser aller à ses désirs, à la colère ;<br><b><i>Moy</i>. ἐπιτρέπομαι</b> <span>(<i>f</i>. ἐπιτρέψομαι, <i>ao.2</i> ἐπετραπόμην)</span><br><b>   I <i>intr</i>.<br>      1</b> se tourner vers : ἐπ. εἴρεσθαι, OD. <i>9, 12,</i> être porté <i>ou</i> incliner à demander ;<br><b>      2</b> se confier à, s’en remettre à, <i>dat</i>. HDT. <i>1, 96 ; 5, 95, etc. ;</i> XÉN. <i>An. 1, 9, 8 ;</i><br><b>   II <i>tr.</i></b> confier : τί τινι, HDT. <i>3, 155, 157,</i> qqe ch. à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. éol</i>. ἐπιτρέπην, ALC. <i>35. Formes ion</i>. ἐπιτράπω, <i>etc., d’où ao</i>. ἐπέτραψα, HDT. <i>4, 202 ; pass. ao. part</i>. ἐπιτραφθείς, HDT. <i>l. c. ; pf. 3 pl. épq. et ion</i>. ἐπιτετράφαται, IL. <i>2, 25, 62 ; moy. fut</i>. ἐπιτράψομαι, HDT. <i>3, 155</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτρεπω - ἐπιτρέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 18 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Actes (5)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2011":"<h1>epitrope</h1>\n<p>Strong n° 2011 <i>Prononciation [ep-ee-trop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>permission, pouvoir, mission, tutelle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιτροπή, ῆς (ἡ) :<br>      1</b> action d’en référer <i>ou</i> d’en appeler à : εἴς τινα, THC. <i>5, 41 ;</i> πρός τινα, DÉM. <i>900, 1,</i> à un arbitre ; εἰς ἐπιτροπὴν ἔρχεσθαι, DÉM. <i>897, 1,</i> recourir à un arbitrage ;<br><b>      2</b> droit de décider, pouvoir d’un arbitre : τινὶ ἐπ. διδόναι, HPC. <i>25, 27 ;</i> POL. <i>18, 22, 5,</i> donner à qqn un droit d’arbitrage ; ἐπ. λαϐεῖν, POL. <i>3, 15, 7,</i> recevoir de pleins pouvoirs pour traiter ; <i>d’où</i> décision d’un arbitrage ; εἰς ἐπ. ἑαυτὸν διδόναι, POL. <i>2, 11, 8, etc</i>. s’en remettre à l’arbitrage de qqn ;<br><b>      3</b> tutelle, administration d’un tuteur, PLAT. <i>Leg. 924</i> b ; LYS. (HARP. SUID. <i>v°</i> καρποῦ δίκη) ;<br><b>      4</b> action intentée par un pupille à son tuteur dans le délai de cinq ans après la majorité, LYS. <i>fr. 15 ;</i> DÉM. <i>861 fin ;</i> PLUT. <i>M. 844</i> c, <i>etc</i>.<br><span><b>Étym</b>. ἐπιτρέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτροπη - ἐπιτροπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2012":"<h1>epitropos</h1>\n<p>Strong n° 2012 <i>Prononciation [ep-it'-rop-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui à qui la responsabilité en toute chose a été donnée\n<ol type=\"a\">\n<li>un conservateur, un gardien, un tuteur</li>\n<li>l'intendant ou gestionnaire de la maisonnée, ou des terres\n<ol>\n<li>surveillant</li>\n</ol>\n</li>\n<li>celui qui a soin et qui est le tuteur des enfants, que le père soit mort (tuteur des mineurs) ou qu'il soit encore vivant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπίτροπος, ος, ον</b>, celui à qui est confiée la gestion de qqe ch., <i>particul. :</i><br><b>      1</b> administrateur (d’une maison, d’une fortune, <i>etc</i>.) intendant, HDT. <i>1, 108 ; 2, 62 ;</i> DÉM. <i>539, 23 ;</i><br><b>      2</b> gouverneur d’une ville, d’un pays, HDT. <i>3, 27, etc. ; à Rome,</i> = procurator, STR. <i>3, 4, 20 ; 13, 2, 3 Kram. ;</i> PHIL. <i>2, 517 ;</i> ARR. <i>Epict. 3, 4, 1 ;</i> PLUT. <i>M. 813</i> e ;<br><b>      3</b> tuteur, gouverneur, HDT. <i>4, 76 ;</i> THC. <i>2, 80 ;</i> PLAT. <i>Theæt. 165</i> a, <i>etc. ;</i><br><b>      4</b> <i>en gén</i>. gardien, protecteur, <i>en parl. d’un dieu,</i> PD. <i>O. 1, 171</i>.<br><span><b>Étym</b>. ἐπιτρέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτροπος - ἐπίτροπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2013":"<h1>epitugchano</h1>\n<p>Strong n° 2013 <i>Prononciation [ep-ee-toong-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>éclairer ou heurter, atteindre une personne ou une chose</li>\n<li>atteindre, obtenir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·τυγχάνω</b> <span>(<i>f</i>. -τεύξομαι, <i>ao.2</i> ἐπέτυχον)</span> se trouver par hasard sur <i>ou</i> auprès de, <i>d’où :</i><br><b>      1</b> rencontrer : τινί, qqn, THC. <i>3, 75 ; 8, 34 ;</i> PLAT. <i>Leg. 738</i> d ; <i>ou</i> qqe ch. : ἐπ. ταῖς θύραις ἀνεῳγμέναις, PLAT. <i>Conv. 223</i> b, trouver les portes ouvertes ; <i>rar</i>. τινός, qqn, AR. <i>Pl. 245 (cf</i>. PLUT. <i>Artax. 12) ; ou</i> qqe ch. THC. <i>3, 3 ;</i> ARSTT. <i>Œc. 2, 33 ;</i> ὁ ἐπιτυχών, HDT. <i>2, 2 ;</i> ANT. <i>115, 1 ; ou sans art</i>. EUR. <i>H.f. 1248 ;</i> AR. <i>Ran. 1375,</i> le premier venu ; <i>au plur</i>. οὐ φαύλων οὐδὲ τῶν ἐπιτυχόντων, PLAT. <i>Crat. 390</i> d, des gens qui ne sont ni méprisables ni les premiers venus ;<br><b>      2</b> <i>p. suite, c</i>. ἐντυγχάνω, converser, s’entretenir : τινί, PLAT. <i>Leg. 758</i> c, avec qqn ; βιϐλίῳ, LUC. <i>Dem. enc. 27,</i> lire un livre ;<br><b>      3</b> <i>particul</i>. rencontrer ce qu’on cherche, atteindre le but ; τινός, XÉN. <i>Mem. 4, 2, 28 ;</i> DÉM. <i>1168, 1,</i> obtenir qqe ch. ; τοῦ ἀγῶνος, DÉM. <i>1175, 16,</i> gagner son procès ; τινί, ESCHN. <i>77, 16 ;</i> περί τινος, POL. <i>21, 3, 8,</i> être heureux, réussir, avoir du succès en qqe ch. ; <i>avec l’inf</i>. ἐπέτυχον παρ' αὐτοῦ καθηγήσασθαί μοι τῆς ὁδοῦ, LUC. <i>Nec. 6,</i> j’obtins de lui qu’il me guiderait dans la route ; <i>abs</i>. réussir, XÉN. <i>Hell. 4, 5, 19 ;</i> ὁ μὴ ἐπιτυχών, THC. <i>3, 42,</i> celui qui n’a pas réussi ; <i>au pass</i>. ἐπιτετευγμέναι πράξεις, POL. <i>6, 33, 2,</i> affaires qui ont réussi ; τὰ ἐπιτετευγμένα, DS. <i>1, 1,</i> les succès ; <i>avec un suj. de chose,</i> arriver heureusement : αὐτῷ οὐδὲν ἐπέτυχε, A. LIB. <i>41,</i> rien ne lui réussit.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιτυγχανω - ἐπιτυγχάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2014":"<h1>epiphaino</h1>\n<p>Strong n° 2014 <i>Prononciation [ep-ee-fah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>montrer à ou sur\n<ol type=\"a\">\n<li>amener à la lumière</li>\n</ol>\n</li>\n<li>apparaître, devenir visible\n<ol type=\"a\">\n<li>des étoiles</li>\n</ol>\n</li>\n<li>devenir clairement connu, se montrer soi-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·φαίνω</b> <span>(<i>f</i>. -φανῶ)</span><br><b>   I <i>tr</i>.<br>      1</b> faire paraître sur, <i>d’où au pass</i>. se montrer à la surface, T. LOCR. <i>101</i> d ; <i>avec le dat</i>. se montrer sur, PLUT. <i>Arat. 3, etc. ;</i><br><b>      2</b> faire paraître au devant, <i>d’où</i> faire voir, montrer : τι, THGN. <i>359 ;</i> POL. <i>10, 18, 8 ;</i> DH. <i>Amm. 1, 10 ;</i> LUC. <i>Alex. 12,</i> qqe ch. ; <i>d’où au pass</i>. se montrer, paraître, apparaître : τὰ ἐπιφαινόμενα, HPC. <i>Aph. 1243,</i> les symptômes qui surviennent ; <i>en parl. de songes,</i> de visions, HDT. <i>2, 91 ; 3, 27, etc. ; particul</i>. se montrer tout à coup, apparaître soudainement, XÉN. <i>Œc. 21, 10 ;</i> HDN <i>1, 12, 12 ; 3, 7, 9 ; en parl. de l’ennemi,</i> HDT. <i>2, 152 ; 4, 122 ;</i> THC. <i>8, 42, etc. ;</i> ἐπ. ἐς τὴν Νάξον, HDT. <i>5, 30 (cf</i>. XÉN. <i>An. 3, 4, 13</i>) ; ἐπὶ τὰ Δρέπανα, POL. <i>1, 49, 7,</i> se montrer tout à coup près de Naxos, de Drépane ;<br><b>   II</b> <i>intr. en appar. (s.-e</i>. ἑαυτόν) se montrer, POL. <i>5, 6, 6 ;</i> NT. <i>Luc. 1, 79</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. réc</i>. ἐπέφανα <span>[φᾱ]</span> = ἐπέφηνα, SPT. <i>Ps. 30, 17 ; 66, 2 ; 127, 27 ; inf</i>. ἐπιφᾶναι, NT. <i>Luc. 1, 79. Pass. sbj. ao.2, 3 pl. ion</i>. ἐπιφανέωσι, HDT. <i>5, 30</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφαινω - ἐπιφαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G2015":"<h1>epiphaneia</h1>\n<p>Strong n° 2015 <i>Prononciation [ep-if-an'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une apparition, une comparution, une apparence</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιφάνεια, ας (ἡ)</b> <span>[φᾰ]</span><br><b>   I</b> action de se montrer, <i>d’où :</i><br><b>      1</b> apparition, <i>en parl. du jour,</i> POL. <i>3, 94, 3 ; particul</i>. apparition soudaine (d’un ennemi) POL. <i>1, 54, 2 ;</i> (d’un dieu) DH. <i>2, 68 ;</i> PLUT. <i>Them. 30 ; d’où</i> manifestation de la puissance divine, DS. <i>1, 25 ; dans les Livres saints,</i> apparition de Dieu, de J.C. <i>ou</i> des démons, SPT. <i>2Reg. 7, 23 ; 2 Macc. 3, 24 ; 5, 4 ; 15, 27 ;</i> NT. <i>2Tim. 1, 10 ;</i><br><b>      2</b> <i>postér</i>. l’Épiphanie (<i>cf</i>. τὰ Ἐπιφάνια) CHRYS. <i>2, 369 Migne ;</i><br><b>   II</b> tout ce qui apparaît à la surface :<br><b>      1</b> surface, <i>t. de math</i>. EUCL. <i>Elem. 1, def. 5, etc. ;</i> ARSTT. <i>Categ. 6, 1 ; Metaph. 2, 5, 3 ; 6, 2, 2 ;</i><br><b>      2</b> surface de la chair, peau, ARSTT. <i>Sens. 3, 5 ;</i> DS. <i>3, 29 ;</i><br><b>      3</b> côté d’une chose : αἱ τρεῖς ἐπ. τῆς πόλεως, POL. <i>4, 70, 9,</i> les trois côtés visibles de la ville ; <i>d’où</i> front d’une troupe, POL. <i>1, 22, 10 ;</i><br><b>      4</b> <i>fig</i>. ce qui apparaît, surface, apparence (<i>p. opp. à réalité,</i> ἀλήθεια) ANON. (SUID.) ;<br><b>      5</b> ce qui brille soudainement, <i>d’où</i> renom, illustration, <i>p. suite d’un événement inattendu,</i> PLAT. <i>1 Alc. 124</i> c ; IS. <i>64, 34 ; au pl</i>. ISOCR. <i>137</i> c ; DS. <i>19, 1</i>.<br><span><b>Étym</b>. ἐπιφανής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφανεια - ἐπιφάνεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2016":"<h1>epiphanes</h1>\n<p>Strong n° 2016 <i>Prononciation [ep-if-an-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>en évidence, manifeste, éclatant, visible, illustre, notable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιφανής, ής, ές</b> <span>[ᾰ]</span> qui se montre, <i>d’où :</i><br><b>      1</b> qui est en vue, visible, ARSTT. <i>H.A. 2, 13 ; 3 ; p. opp. à</i> ἄδηλος, XÉN. <i>Mem. 3, 1, 10 ; joint à</i> μετέωρος, TH. <i>C.P. 5, 9, 8 ; particul. en parl. de lieux élevés, de villes, etc</i>. THC. <i>5, 10 ; cf. 6, 96 ; 7, 19 ;</i> ἐπ. τινι, THC. <i>7, 3,</i> qui est en vue pour qqn, que qqn peut voir ;<br><b>      2</b> qui apparaît tout à coup, <i>en parl. de divinités,</i> HDT. <i>3, 27 ; d’où</i> secourable (<i>cf. lat</i>. præsens) DS. <i>1, 17 ;</i><br><b>      3</b> manifeste, évident, THC. <i>1, 21 ;</i> ARSTT. <i>Nic. 4, 5, 10 ;</i><br><b>      4</b> <i>fig</i>. illustre, éclatant, <i>en parl. de pers. distinguées par le rang ou la naissance,</i> HDT. <i>2, 89, etc. ; par le courage, l’intelligence, etc</i>. THC. <i>6, 72 ;</i> PLAT. <i>Leg. 629</i> e ; <i>en b. et en mauv. part,</i> XÉN. <i>Mem. 3, 1, 10 ;</i> LYS. <i>140, 36 ; particul. titre des rois asiatiques, p. ex. d’Antiochus</i> (Épiphane) <i>de Syrie,</i> POL. <i>26, 10, 1 ; en parl. de choses,</i> HDT. <i>5, 6 ;</i> POL. <i>1, 78, 11</i>.<br><span>•<i> Cp</i>. -έστερος, PLAT. <i>Lach. 184</i> b, <i>Menex. 246</i> e ; ARSTT. <i>Physiogn. 2</i>. <i>• Sup</i>. -έστατος, HDT. <i>5, 26 ; 9, 32 ;</i> THC. <i>1, 21 ;</i> POL. <i>1, 78, 11, etc</i>.<br><span><b>Étym</b>. ἐπιφαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφανης - ἐπιφανής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2017":"<h1>epiphausko</h1>\n<p>Strong n° 2017 <i>Prononciation [ep-ee-fows'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briller sur\n<ol type=\"a\">\n<li>Christ qui donne la vérité divine comme brille le soleil, et qui réveille les hommes de leur sommeil</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·φαύσκω</b> (<i>seul. prés</i>.) commencer à luire, se lever, <i>en parl. des astres,</i> ORPH. <i>H. 49, 9 ;</i> ARSTT. <i>Probl. 8, 17 ;</i> SPT. <i>Job 25, 5 ; 31, 26 ; au pass</i>. SPT. <i>Job 41, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφαυσκω - ἐπιφαύσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2018":"<h1>epiphero</h1>\n<p>Strong n° 2018 <i>Prononciation [ep-ee-fer'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter, imputer\n<ol type=\"a\">\n<li>utilisé pour les accusateurs</li>\n</ol>\n</li>\n<li>poser sur, infliger</li>\n<li>amener sur, c.à.d en addition, ajouter, augmenter</li>\n<li>appliquer, susciter, imposer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·φέρω</b> <span>(<i>f</i>. ἐποίσω, <i>ao.1</i> ἐπήνεγκα, <i>etc</i>.)</span><br><b>      1</b> porter sur : νεκρῷ στέφανον, PLUT. <i>Per. 36,</i> porter <i>ou</i> déposer une couronne sur un mort ; ἀπαρχάς, THC. <i>3, 58,</i> offrir des prémices (sur l’autel) ; <i>abs</i>. τὰ ἐπιφερόμενα, ISOCR. <i>189</i> a, les offrandes qu’on dépose sur un autel <i>ou</i> sur une tombe en l’honneur d’un mort ; οἱ ἐποίσοντες, ISOCR. <i>14, 61, Baiter-Sauppe,</i> ceux qui viendront déposer des offrandes ; <i>fig</i>. τιμάν τινι, PD. <i>O. 1, 31,</i> décerner un honneur à qqn ; ὄνομά τινι, PLAT. <i>Pol. 307</i> b, donner un nom a qqn ; ψῆφόν τινι, DH. <i>2, 14,</i> donner son suffrage à qqn <i>ou</i> à qqe ch. ;<br><b>      2</b> <i>avec idée d’hostilité,</i> porter contre : τινὶ χεῖρας, IL. <i>1, 89 ;</i> OD. <i>16, 438,</i> mettre la main sur qqn, le saisir <i>ou</i> l’attaquer ; ὅπλα ἐπιφέρειν, XÉN. <i>Hell. 6, 3, 6 ;</i> τὰ ὅπλα ἐπ. πόλει, DÉM. <i>216, 5,</i> porter les armes contre (qqn), contre une ville ; <i>fig</i>. πόλεμόν τινι, HDT. <i>5, 81 ;</i> THC. <i>1, 140 ;</i> XÉN. <i>Vect. 4, 41,</i> porter la guerre chez qqn ; δίκην τινί, PLAT. <i>Leg. 343,</i> intenter un procès à qqn ; αἰτίαν τινί, HDT. <i>1, 26, 68, etc. ;</i> PLAT. <i>Phæd. 98</i> a, <i>ou</i> ἔγκλημα, EUR. <i>Or. 766,</i> intenter une accusation à qqn ; ψόγον, THC. <i>1, 70 ;</i> μέμψιν, AR. <i>Ran. 1253,</i> infliger un blâme, un reproche ; μωρίην, μανίην τινί, HDT. <i>1, 131 ; 6, 112,</i> reprocher à qqn sa folie, son extravagance ;<br><b>      3</b> porter en sus, ajouter, DYSC. <i>Synt. p. 92, 28 ; particul</i>. ajouter un qualificatif <i>ou</i> une épithète à un mot, ARSTT. <i>Rhet. 3, 6 ;</i><br><b><i>Pass.-moy</i>. ἐπιφέρομαι</b> <span>(<i>f. pass</i>. ἐπενεχθήσομαι, <i>f. moy</i>. ἐποίσομαι)</span><br><b>   I <i>intr</i>.<br>      1</b> se porter sur <i>ou</i> contre, se jeter sur, assaillir ; <i>abs. en parl. d’animaux,</i> XÉN. <i>Cyr. 2, 4, 19 ; Cyn. 5, 32 ; 6, 16 ; en parl. de pers</i>. ἐπ. τινι, THC. <i>3, 23,</i> s’élancer sur qqn ; <i>fig</i>. s’emporter en reproches, en invectives contre qqn, HDT. <i>8, 61 ;</i><br><b>      2</b> se porter à la suite, <i>d’où</i> se produire à la suite, suivre, <i>dat</i>. D. THR. <i>632, 2 ;</i> HÉPH. <i>1, 18 ; abs</i>. τὰ ἐπιφερόμενα, les événements futurs, l’avenir, HDT. <i>1, 209 ; 3, 16 ; ou simpl</i>. la suite (d’un récit <i>ou</i> d’un ouvrage) POL. <i>3, 6, 8 ;</i> τὰ ἐπιφερόμενα κακά, ANT. <i>115, 29,</i> les malheurs à venir ; ἡ ἐπιφερομένη θερεία, POL. <i>1, 25, 7,</i> l’été suivant ;<br><b>   II <i>tr</i>.<br>      1</b> apporter avec soi : σιτία, PLUT. <i>Sert. 13 ;</i> ὕδωρ, STR. <i>138,</i> des provisions, de l’eau ; <i>particul</i>. apporter en dot, LYS. <i>153, 12 ;</i><br><b>      2</b> prendre (pour soi) de la nourriture, HPC. <i>85</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. 3 sg</i>. ἐποίσει, IL. <i>1, 89 ;</i> OD. <i>16, 438 ; ao.1 inf. ion</i>. ἐπενεῖκαι, IL. <i>19, 261</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφερω - ἐπιφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Philippiens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2019":"<h1>epiphoneo</h1>\n<p>Strong n° 2019 <i>Prononciation [ep-ee-fo-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>appeler, crier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·φωνέω-ῶ</b> (<i>pf</i>. ἐπιπεφώνηκα) :<br><b>      1</b> dédier, consacrer à, <i>dat</i>. PLUT. <i>Pomp. 4 ;</i><br><b>      2</b> s’approcher, en parlant, de, invoquer, <i>acc</i>. SOPH. <i>O.C. 1762 ;</i><br><b>      3</b> parler sur <i>ou</i> de : τινι, PLUT. <i>Alex. 3 ;</i> εἴς τι, PLUT. <i>Luc. 39,</i> de qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφωνεω - ἐπιφωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2020":"<h1>epiphosko</h1>\n<p>Strong n° 2020 <i>Prononciation [ep-ee-foce'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lumière croissante, aube, briller</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·φώσκω</b> (<i>seul. prés</i>.) :<br><b>      1 <i>intr.</i></b> commencer à luire, NT. <i>Matth. 28, 1 ; Luc. 23, 54 ;</i><br><b>      2 <i>tr.</i></b> faire briller, POÈT. <i>de vir. herb. 25</i>.<br><span><b>Étym</b>. ἐπί, φώς, <i>cf</i>. ἐπιφαύσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιφωσκω - ἐπιφώσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2021":"<h1>epicheireo</h1>\n<p>Strong n° 2021 <i>Prononciation [ep-ee-khi-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre la main à</li>\n<li>prendre en main, entreprendre, tenter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·χειρέω-ῶ :<br>      1</b> mettre la main à <i>ou</i> sur : δείπνῳ, σίτῳ, OD. <i>24, 386, 395,</i> au souper, à la nourriture, <i>càd</i>. se mettre à souper, à manger ; <i>avec idée d’hostilité :</i> τινι, HDT. <i>1, 11, etc. ;</i> THC. <i>3, 94 ;</i> πρός τινα, THC. <i>7, 51 ;</i> ἐπί τινα, PLAT. <i>Menex. 241</i> d, attaquer, assaillir qqn ; εἴς τι, DS. <i>14, 80,</i> se jeter sur qqe ch. ;<br><b>      2</b> <i>fig</i>. mettre la main à, <i>càd</i>. entreprendre : τινι, HDT. <i>2, 158 ; 7, 43, etc. ;</i> ἔργῳ, HDT. <i>9, 27,</i> qqe ch., une œuvre ; ὁδῷ, EUR. <i>Bacch. 819 ;</i> HDT. <i>7, 43,</i> un voyage, se mettre en route ; τυραννίδι, HDT. <i>5, 46,</i> tenter de s’emparer de la royauté ; τοῖς ἀδυνάτοις, XÉN. <i>Mem. 2, 3, 5,</i> tenter l’impossible ; <i>qqf. avec l’acc</i>. ἔργον, THGN. <i>75 ;</i> τι, ISOCR. <i>90</i> c ; πρᾶγμα, PLAT. <i>Crit. 45</i> c, <i>Phil. 57</i> b, entreprendre une œuvre, qqe ch., une affaire ; <i>avec l’inf</i>. entreprendre de, HDT. <i>3, 38, 65, etc. ;</i> THC. <i>2, 40 ; particul. t. de log</i>. entreprendre de démontrer, argumenter, disserter, PLAT. <i>Theæt. 205</i> a ; ἔκ τινος, ARSTT. <i>Top. 2, 11, 1,</i> tirer d’un principe certaines conséquences ; πρός τι, ARSTT. <i>Top. 3, 6, 13,</i> tenter d’amener une conclusion ; ἐπ. ὅτι, ARSTT. <i>Top. 5, 1, 3,</i> tenter de démontrer que, <i>etc. ; abs</i>. conclure, ARSTT. <i>An. pr. 2, 19, 2 ; Cæl. 1, 7, 15</i>.<br><span><b>Étym</b>. ἐπί, χείρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιχειρεω - ἐπιχειρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2022":"<h1>epicheo</h1>\n<p>Strong n° 2022 <i>Prononciation [ep-ee-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>verser sur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·χέω</b> <span>(<i>f</i>. -χεύσω, <i>ao</i>. ἐπέχευα, <i>pf. inus</i>.)</span><br><b>      1</b> verser sur, répandre sur : χερσὶν ὕδωρ, IL. <i>24, 303,</i> verser de l’eau sur les mains ; οἴνῳ ὕδωρ, XÉN. <i>Œc. 17, 9,</i> de l’eau sur du vin ; ἐπ. τι, OD. <i>1, 136 ;</i> AR. <i>Pax 169, etc</i>. verser qqe ch. sur ; <i>abs</i>. remplir <i>ou</i> vider une coupe en l’honneur de : τινός, ANTH. <i>12, 168,</i> de qqn ; θρῆνον, PD. <i>I. 8, 129,</i> répandre des gémissements ; ὀδμήν, A. RH. <i>2, 191,</i> exhaler une odeur ;<br><b>      2</b> verser par-dessus, <i>d’où au pass</i>. ἰχθῦς νάπυϊ ἐπικεχυμένους, LUC. <i>As. 47,</i> poissons inondés de moutarde<br><i>Pass.-moy. (ao. pass</i>. ἐπεχύθην, <i>ao. moy</i>. ἐπεχευάμην) ;<br><b>   I <i>intr</i>.<br>      1</b> se répandre sur, XÉN. <i>Œc. 17, 12 ; abs</i>. se répandre, Q. SM. <i>14, 607 ; p. suite, fig</i>. se mêler à, <i>dat</i>. PLUT. <i>Rom. 15 ;</i><br><b>      2</b> se répandre contre, se précipiter comme un torrent sur, <i>en parl. de pers., d’animaux,</i> IL. <i>15, 654 ; 16, 295 ;</i> τινι, HDT. <i>2, 149,</i> sur qqn ;<br><b>      3</b> se répandre jusqu’à, se développer, <i>en parl. d’une discussion,</i> PLAT. <i>Pol. 302</i> c, <i>Leg. 793</i> b ;<br><b>   II <i>tr</i>.<br>      1</b> répandre pour soi <i>ou</i> par soi-même : ὕλην, OD. <i>5, 257 ;</i> χύσιν φύλλων, OD. <i>5, 487,</i> répandre du lest, une couche de feuilles ; πήχεε παιδί, A. RH. <i>1, 268,</i> jeter ses bras autour du corps d’un enfant ;<br><b>      2</b> se faire verser à boire ; ἄκρατόν τινος, THCR. <i>Idyl. 14, 18, ou simpl</i>. τινος, PHYLARQ. (ATH. <i>261</i> b) une libation de vin en l’honneur de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. 2 sg</i>. ἐπιχεῖς, AR. <i>Pax 169 ; ao. 3 sg</i>. ἐπέχευε, OD. <i>15, 135 ; inf</i>. ἐπιχεῦαι, IL. <i>24, 303 ; ao. réc. part. fém</i>. ἐπιχύσασαν, <i>p</i>. ἐπιχέασαν, CORN. <i>22. Pass. prés. part. ion</i>. ἐπιχεομένους, PHYLARQ. <i>l. c. ; pl.q.pf. 3 pl</i>. ἐπέχυντο, IL. <i>16, 295. Moy. ao. 3 sg</i>. ἐπεχεύατο, OD. <i>5, 257, 487 ;</i> A. RH. <i>1, 268, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιχεω - ἐπιχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2023":"<h1>epichoregeo</h1>\n<p>Strong n° 2023 <i>Prononciation [ep-ee-khor-ayg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fournir, approvisionner, apporter en outre, présenter</li>\n<li>être fourni, administré, assisté, être bien pourvu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·χορηγέω-ῶ :<br>      1</b> ajouter comme chorège à ce qui a déjà été fourni, DH. <i>10, 54 ;</i><br><b>      2</b> <i>p. ext</i>. fournir en outre, accorder en outre : τινί τι, GAL. <i>3, 5 ;</i> SPT. <i>Sir. 25, 22 ;</i> NT. <i>2Cor. 9, 10,</i> qqe ch. à qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιχορηγεω - ἐπιχορηγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2024":"<h1>epichoregia</h1>\n<p>Strong n° 2024 <i>Prononciation [ep-ee-khor-ayg-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une assistance, une aide, un approvisionnement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπιχορηγία, ας (ἡ)</b> action de fournir en outre, en sus, NT. <i>Eph. 4, 16 ;</i> PHIL. <i>1, 19</i>.<br><span><b>Étym</b>. ἐπιχορηγέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιχορηγια - ἐπιχορηγία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2025":"<h1>epichrio</h1>\n<p>Strong n° 2025 <i>Prononciation [ep-ee-khree'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>étendre sur, oindre quelque chose sur une autre chose</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·χρίω</b> <span>[ρῑ]</span><br><b>      1</b> étendre par friction : τινί τι, DIOSC. <i>3, 25 ;</i> τι ἐπί τι, NT. <i>Joh. 9, 6,</i> un liniment sur qqe ch. ;<br><b>      2</b> <i>p. suite,</i> oindre, enduire ; τόξον ἀλοιφῇ, OD. <i>21, 179,</i> un arc de graisse ; παρειάς, OD. <i>18, 172,</i> graisser ses joues : τιτάνῳ τι, LUC. <i>H. conscr. 62,</i> mettre une couche de plâtre sur qqe ch. ;<br><b><i>Moy.</i></b> enduire sur soi : χρῶτ' ἐπιχρίεσθαι ἀλοιφῇ, OD. <i>18, 179,</i> se frotter la peau de graisse.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. part. ao</i>. ἐπιχρισθέντα, DIOSC. <i>2, 217</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επιχριω - ἐπιχρίω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2026":"<h1>epoikodomeo</h1>\n<p>Strong n° 2026 <i>Prononciation [ep-oy-kod-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>édifier, bâtir dessus</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nἐπ·οικοδομέω-ῶ :<br>      1</b> bâtir sur, par-dessus : τεῖχος ὑψηλότερον, THC. <i>7, 4,</i> un mur plus élevé ; ἐπὶ κρηπῖδος, PLAT. <i>Leg. 736</i> e ; ἐπὶ κρηπῖδι, XÉN. <i>An. 3, 4, 11,</i> sur des fondations ; <i>fig</i>. τοῖς ἀληθέσιν ἐψευσμένα, PAUS. <i>8, 2, 6,</i> échafauder des mensonges sur la vérité ; <i>abs</i>. accumuler les circonstances, <i>d’où</i> aller par gradation, ARSTT. <i>Rhet. 1, 7, 31, etc. ;</i><br><b>      2</b> bâtir ensuite <i>ou</i> de nouveau, rebâtir, XÉN. <i>Hell. 6, 5, 12 ;</i> PLAT. <i>Leg. 793</i> c ; DÉM. <i>1278, 27 ;</i><br><b>      3</b> bâtir contre qqn, POL. <i>2, 46, 5</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εποικοδομεω - ἐποικοδομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2027":"<h1>epokello</h1>\n<p>Strong n° 2027 <i>Prononciation [ep-ok-el'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>conduire sur, frapper contre\n<ol type=\"a\">\n<li>faire échouer un navire sur la terre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπι·κέλλω</b> <span>(<i>f</i>. -κέλσω, <i>ao</i>. ἐπέκελσα)</span><br><b>      1</b> faire aborder : νῆας, OD. <i>9, 148,</i> des navires ; <i>d’où</i> amener à terre (un poisson) NUMÉN. (ATH. <i>321</i> b) ;<br><b>      2</b> <i>intr. en appar. (s.-e</i>. νῆα) aborder : χέρσῳ, A. RH. <i>3, 575 ;</i> γῆν, A. RH. <i>2, 352,</i> sur la terre ferme, à terre, <i>en parl. d’un navire ;</i> ἠπείρῳ, OD. <i>13, 114,</i> toucher la terre.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εποκελλω - ἐπικέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2028":"<h1>eponomazo</h1>\n<p>Strong n° 2028 <i>Prononciation [ep-on-om-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre un nom sur, désigner d'un nom, nommer</li>\n<li>être nommé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπ·ονομάζω :<br>      1</b> appliquer un nom à : τινὶ ὄνομα, PLAT. <i>Pol. 263</i> c, <i>ou avec double acc</i>. τινὰ ὄνομα, PLAT. <i>Crat. 406</i> a, désigner qqn <i>ou</i> qqe ch. par un nom, donner un nom à qqn <i>ou</i> à qqe ch. d’après une circonstance, par suite de qqe ch. ; <i>pléon. avec</i> εἶναι : εἶναι ἕκαστα ἐπονομαζόμεθα, PLAT. <i>Parm. 133</i> d, nous sommes appelés chacun d’un nom particulier ; <i>au pass</i>. ἐπονομάζεσθαι ἀπό τινος, THC. <i>6, 2 ;</i> PLAT. <i>Crat. 404</i> b, <i>419</i> c, <i>ou</i> τινος, EUR. <i>H.f. 1329 ;</i> PLAT. <i>Leg. 738</i> b, être appelé d’un nom par suite de qqe particularité ;<br><b>      2</b> appeler par son nom : τὸ ὄνομά τινος, HDT. <i>4, 35,</i> prononcer le nom de qqn ; τινὰ πατρόθεν, PLAT. <i>Lys. 204</i> e ; THC. <i>7, 69,</i> appeler qqn par le nom de son père ;<br><b>      3</b> donner un nom en outre, surnommer, THC. <i>2, 29 ;</i> τῆς ἐπωνυμίας ἐπονομάζεσθαι, PLAT. <i>Leg. 626</i> d, être appelé par surnom.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἐπουν. HDT. <i>l. c. etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επονομαζω - ἐπονομάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2029":"<h1>epopteuo</h1>\n<p>Strong n° 2029 <i>Prononciation [ep-opt-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un surveillant</li>\n<li>regarder à, regarder attentivement, épier, être à l'affût</li>\n<li>veiller, contempler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐποπτεύω<br>      1</b> observer, surveiller, présider à, <i>acc</i>. OD. <i>16, 140 ;</i> HÉS. <i>O. 765 ;</i> ESCHL. <i>Ch. 489 ;</i><br><b>      2</b> <i>p. suite,</i> veiller à <i>ou</i> sur, PLAT. <i>Leg. 951</i> d, <i>etc. ;</i><br><b>      3</b> devenir ἐπόπτης, <i>càd</i>. initié du plus haut degré aux mystères d’Éleusis, PLAT. <i>Ep. 333</i> e ; PLUT. <i>Demetr. 26 ; d’où</i> parvenir au comble du bonheur, AR. <i>Ran. 745</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. itér. 3 sg</i>. ἐποπτεύεσκε, OD. <i>l. c</i>.<br><span><b>Étym</b>. ἐπόπτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εποπτευω - ἐποπτεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2030":"<h1>epoptes</h1>\n<p>Strong n° 2030 <i>Prononciation [ep-op'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un surveillant, un inspecteur</li>\n<li>spectateur, témoin oculaire de quelque chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπόπτης, ου (ὁ) :<br>      1</b> qui observe, qui veille à <i>ou</i> sur, qui préside à, PD. <i>N. 9, 5 ;</i> ESCHL. <i>Pr. 299 ;</i> T. LOCR. <i>105</i> a ; PAUS. <i>8, 30, 1 ; en gén</i>. DÉM. <i>47, 5 ;</i><br><b>      2</b> <i>particul</i>. qui contemple (les mystères) <i>càd</i>. initié du plus haut degré aux mystères d’Éleusis, PLUT. <i>Alc. 22</i>.<br><span><b>Étym</b>. ἐπόψομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εποπτης - ἐπόπτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2031":"<h1>epos</h1>\n<p>Strong n° 2031 <i>Prononciation [ep'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un mot, la parole</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔπος</b>, <i>gén</i>. <b>ἔπεος-ους (τὸ)</b> ce qu’on exprime par la parole, <i>d’où :</i><br><b>A</b> parole, <i>càd. :</i><br><b>   I</b> ce qu’on dit, ce dont on parle, <i>plutôt que la parole même,</i> SOPH. <i>O.C. 721 ; p. ext</i>. parole, mot, <i>en gén</i>. IL. <i>3, 83, etc. ;</i> λόγοι ἔπεσι κοσμηθέντες, THC. <i>3, 67,</i> discours arrangés avec de beaux mots ; πρὸς ἔπος, LUC. <i>Ep. sat. 37,</i> au premier mot ; ἔπος πρὸς ἔπος, ESCHL. <i>Eum. 586 ; cf</i>. AR. <i>Nub. 1375 ;</i> PLAT. <i>Soph. 217</i> d, mot pour mot ; κατ' ἔπος, AR. <i>Ran. 802,</i> mot à mot, exactement ; ἐνὶ ἔπεϊ, HDT. <i>3, 82,</i> en un mot ; ὡς ἔπος εἰπεῖν, pour ainsi dire, PLAT. <i>Rsp. 341</i> b ; ὡς εἰπεῖν ἔπος, EUR. <i>Her. 167 ;</i> EL. <i>N.A. 4, 36 ; ou</i> pour le dire en un mot, ESCHL. <i>Pers. 714 ; particul</i>. parole, <i>p. opp. à</i> ἔργον (action) IL. <i>1, 503 ; 15, 234 ;</i> OD. <i>11, 346 ;</i> HDT. <i>3, 135 ;</i> ESCHL. <i>Pers. 174 ;</i> XÉN. <i>Conv. 8, 15 ;</i> ἔργῳ τε καὶ ἔπει, PLAT. <i>Leg. 879</i> c, en action et en parole ; ἔπε' ἀκράαντα, OD. <i>19, 565,</i> paroles sans effet ; <i>p. opp. à</i> βίη <i>ou à</i> χείρ (violence, <i>etc</i>.) IL. <i>15, 106 ; 1, 77 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> discours, <i>joint à</i> μῦθος, OD. <i>4, 597 ; 11, 561 ;</i><br><b>      2</b> paroles d’un chant, récitatif, OD. <i>8, 91 ; 17, 519 ;</i><br><b>      3</b> parole donnée, promesse, IL. <i>8, 8 ; 14, 44 ;</i> ESCHL. <i>Pr. 1037 ;</i><br><b>      4</b> conseil, avis, IL. <i>1, 108 ;</i><br><b>      5</b> manière de dire, proverbe, sentence, HDT. <i>7, 51 ;</i> AR. <i>Av. 507 ;</i><br><b>      6</b> parole d’un dieu, oracle, OD. <i>12, 266 ;</i> HDT. <i>1, 13 ; 1, 143 ;</i> SOPH. <i>O.R. 89, Tr. 819 ;</i><br><b>      7</b> nouvelle, SOPH. <i>Ant. 277 ;</i><br><b>B</b> sens d’un discours, sujet d’un développement (<i>à peu près c</i>. πρᾶγμα) IL. <i>11, 652 ; 17, 701, etc. ;</i> πρὸς ἔπος, PLAT. <i>Phil. 18</i> d, relativement au sujet ; οὐδὲν πρὸς ἔπος, AR. <i>Eccl. 751,</i> hors de propos, hors du sujet ;<br><b>C</b> vers, <i>en gén. :</i><br><b>      1</b> <i>d’ord. au plur</i>. AR. <i>Nub. 638 ; en parl. du langage de la tragédie,</i> AR. <i>Ran. 862 ; de la comédie,</i> AR. <i>Nub. 541, 544 ; Eq. 39 ; particul</i>. τὰ ἔπη, la poésie épique (<i>p. opp. à</i> μέλη, poésie lyrique) PD. <i>N. 2, 2 ;</i> HDT. <i>2, 117 ;</i> THC. <i>1, 3 ;</i> XÉN. <i>Mem. 1, 4, 3 ; p. ext</i>. poésie élégiaque, lyrique, <i>etc. ;</i> ALCM. <i>29 ;</i> PD. <i>O. 3, 8 ;</i><br><b>      2</b> <i>au sg</i>. vers, HDT. <i>4, 29 ; p. ext</i>. ligne d’écriture, ISOCR. <i>261</i> a ; LUC. <i>H. conscr. 28</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. sg. poét</i>. ἔπεϊ, IL. <i>5, 879 ;</i> HH. <i>Cer. 199 ; dat. pl. épq</i>. ἔπεσσι, IL. <i>1, 223, etc. ;</i> OD. <i>17, 545, etc. ; ou</i> ἐπέεσσι, IL. <i>1, 519, 582, etc. ;</i> OD. <i>2, 240, etc. ; crase éol</i>. τὤπος, THCR. <i>Idyl. 28, 24</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *uek<sup>w</sup>-, parler ; <i>cf. sscr</i>. vácas-, mot, <i>v</i>. ὄψ¹, ὄσσα, εἶπον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επος - ἔπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2032":"<h1>epouranios</h1>\n<p>Strong n° 2032 <i>Prononciation [ep-oo-ran'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>existant dans les cieux\n<ol type=\"a\">\n<li>choses qui ont place aux cieux</li>\n<li>les régions célestes\n<ol>\n<li>le ciel lui-même, la demeure de Dieu et des anges</li>\n<li>les cieux plus bas, ceux des étoiles</li>\n<li>les cieux des nuages</li>\n</ol>\n</li>\n<li>le ciel, temple ou sanctuaire</li>\n</ol>\n</li>\n<li>origine ou nature céleste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐπ·ουράνιος, ος, ον</b> <span>[ᾰ]</span> qui est dans le ciel, céleste, <i>en parl. des dieux,</i> IL. <i>6, 129, etc. ;</i> OD. <i>17, 484 ; des âmes pieuses,</i> PD. <i>fr. 97, 4 ;</i> οἱ ἐπουράνιοι, THCR. <i>Idyl. 25, 5 ;</i> MOSCH. <i>2, 21,</i> les dieux du ciel ; <i>au sg</i>. LUC. <i>D. deor. 4, 3 ;</i> τὰ ἐπουράνια, PLAT. <i>Ap. 19</i> b, les phénomènes célestes.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. ion</i>. -ίη, Q. SM. <i>2, 429</i>.<br><span><b>Étym</b>. ἐπί, οὐρανός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επουρανιος - ἐπουράνιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n20 fois dans 18 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (5)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (6)</li>\n</ul>\n</td></tr>\n</table>","G2033":"<h1>hepta</h1>\n<p>Strong n° 2033 <i>Prononciation [hep-tah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sept</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑπτά (οἱ, αἱ, τὰ)</b> <i>indécl</i>. sept, IL. <i>6, 421, etc. ;</i> OD. <i>9, 202 ; etc. ;</i> THC. <i>1, 46 ; 2, 83, etc. ;</i> PLAT. <i>Phæd. 58</i> a, <i>etc. ;</i> ἑπτὰ ἑπτά, SPT. <i>Gen. 7, 3,</i> sept par sept ; τὰ ἑπτὰ ἐπιφανέστατα ἔργα, DS. <i>1, 63 ;</i> τὰ ἑπτὰ κατονομαζόμενα ἔργα, DS. <i>2, 11 ;</i> τὰ ἑπτὰ μέγιστα ἔργα, DS. <i>18, 4,</i> les sept merveilles (du monde) ; οἱ ἑπτὰ σοφοί, TAT. <i>Or. ad Græc. 41, c. 888 a Migne ;</i> ἑπτὰ οἱ σοφοί, DL. <i>1, 1 ;</i> APP. <i>Mithr. 28 ;</i> D. CHR. <i>Or. 72, p. 631 ; ou</i> ἑπτὰ οἱ σοφισταί, ANDROT. (ARSTD. <i>46, 311</i>) les sept sages ; οἱ ἑπτὰ ἐπὶ Θήϐας, EL. <i>V.H. 4, 5, etc</i>. les Sept (chefs) contre Thèbes, <i>titre d’une pièce d’Eschyle ; à Rome,</i> οἱ ἑπτὰ ἄνδρες, D. C. <i>31, 51 ; 48, 32</i> = <i>lat</i>. septemviri.<br><span><b>Étym</b>. <i>indo-europ</i>. *septm, sept ; <i>cf. lat</i>. septem, <i>scr</i>. saptá.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επτα - ἑπτά</font>\n<br><br>nombre primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n88 fois dans 63 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (9)</li>\n<li>Luc (6)</li>\n<li>Actes (8)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (55)</li>\n</ul>\n</td></tr>\n</table>","G2034":"<h1>heptakis</h1>\n<p>Strong n° 2034 <i>Prononciation [hep-tak-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sept fois</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑπτάκις</b> <span>[ᾰ]</span> <i>adv</i>., sept fois, PD. <i>O. 13, 39 ;</i> AR. <i>Lys. 698 ;</i> LUC. <i>Pisc. 2</i>.<br><span><b>Étym</b>. ἑπτά, -κις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επτακις - ἑπτάκις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2035":"<h1>heptakischilioi</h1>\n<p>Strong n° 2035 <i>Prononciation [hep-tak-is-khil'-ee-oy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sept mille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑπτακισ·χίλιοι, αι, α</b> <span>[ᾰχῑ]</span> sept mille, HDT. <i>2, 43 ; 4, 160</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επτακισχιλιοι - ἑπτακισχίλιοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif numéral</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2036":"<h1>epo</h1>\n<p>Strong n° 2036 <i>Prononciation [ep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parler, dire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἶπον</b>, <i>v</i>. *ἔπω.<br><br>\n➀ <b>ἔπω</b> (<i>réc. et épq. au prés. ; d’ord. seul. à l’ao.2</i> εἶπον <i>et à l’ao.1</i> εἶπα ; <i>pour le prés. et l’impf. on emploie, sel. le cas,</i> φημί, λέγω <i>ou</i> ἀγορεύω ; <i>pour le fut</i>. ἐρῶ ; <i>pour le pf</i>. εἴρηκα ; <i>pour le pass. au prés. et à l’impf. les temps correspond. de</i> φημί, λέγω <i>ou</i> ἀγορεύω ; <i>au fut</i>. ῥηθήσομαι, <i>à l’ao</i>. εἰρήθην, <i>au pf</i>. εἴρημαι) parler, dire :<br><b>A</b> <i>en gén. :</i><br><b>   I</b> <i>abs</i>. IL. <i>9, 26, etc. ;</i><br><b>   II</b> <i>avec un seul. rég. :</i><br><b>      1</b> <i>avec un acc. de chose :</i> εἰπεῖν ἔπος, μῦθον, <i>etc. (v. ces mots</i>) : <i>avec un adj. neutre</i> (τόδε, ταῦτα, τι, <i>etc</i>.) : ὅττι κεν εἴπω, OD. <i>19, 406,</i> (le nom) que j’aurai dit ;<br><b>      2</b> <i>avec un dat. de pers</i>. εἰπεῖν τινι, IL. <i>5, 600 ; 6, 75 ; ou avec un acc</i>. εἰπ. τινα, IL. <i>12, 60, 210,</i> parler à qqn, <i>etc. ;</i><br><b>      3</b> <i>avec un gén</i>. εἰπ. πατρός τε καὶ υἱέος, OD. <i>11, 174,</i> parler du père et du fils ;<br><b>      4</b> <i>avec une prép</i>. εἰπ. εἴς τινα, EUR. <i>Hec. 303,</i> parler à qqn ; εἰπ. πρὸς ἑαυτόν, XÉN. <i>Cyr. 2, 2, 1,</i> se parler à soi-même ; εἰπ. μῦθον ἐν Ἀργείοισιν, IL. <i>23, 271,</i> prononcer une parole parmi les Argiens ; εἰπ. μετά τισιν, OD. <i>8, 433 ; 16, 366,</i> parler au milieu de qqes-uns ; εἰπ. περί τινος, OD. <i>15, 347 ; ou</i> ἀμφί τινι, OD. <i>14, 364,</i> parler sur qqn <i>ou</i> qqe ch. ;<br><b>      5</b> <i>avec une conj</i>. εἰπ. ὅτι, PLAT. <i>Leg. 709</i> d, <i>801</i> d, <i>etc</i>. dire que, <i>etc. ;</i><br><b>      6</b> <i>avec un rel</i>. εἰπ' ἄγε μοι καὶ τόνδε ὅς τις ὅδ' ἐστί, IL. <i>3, 192,</i> mais voyons, dis-moi quel est celui-là aussi ;<br><b>   III</b> <i>avec double rég. :</i><br><b>      1</b> <i>acc. de chose et dat. de pers</i>. εἰπέ μοι γένος, OD. <i>19, 162,</i> dis-moi ta famille ; εἰπέ μοι γαῖάν τε τεὴν δῆμόν τε πόλιν τε, OD. <i>8, 555,</i> dis-moi ton pays et ton peuple et ta ville ;<br><b>      2</b> <i>acc. de chose et prép. suivie d’un n. de pers</i>. εἰπεῖν τι ἔς τινα, SOPH. <i>Tr. 457 ; ou</i> τι πρός τινα, OD. <i>20, 128 ;</i> SOPH. <i>Aj. 292,</i> dire qqe ch. à qqn ;<br><b>      3</b> <i>double acc</i>. ἀτάσθαλόν τι εἰπεῖν τινα, OD. <i>22, 314,</i> dire qqe ch. d’injurieux à qqn ; κακὰ εἰπ. τινα, AR. <i>Ach. 649,</i> tenir à qqn de mauvais propos ; <i>au même sens, avec un adv. et un acc</i>. εὖ εἰπ. τινα, OD. <i>1, 302,</i> dire du bien de qqn, parler de qqn avec respect <i>ou</i> avec éloge ; <i>particul. avec deux acc. dont l’un sert d’attrib. à l’autre :</i> πολλοί τέ μιν ἐσθλὸν ἔειπον, OD. <i>19, 334,</i> et beaucoup ont dit qu’il était brave ; τεθνεῶτ' Ὀρέστην εἰπ. ESCHL. <i>Ch. 682,</i> parler d’Oreste comme mort ;<br><b>      4</b> <i>avec un dat. de pers. et un inf</i>. dire <i>ou</i> ordonner à qqn de, <i>etc</i>. OD. <i>15, 76 ; 22, 262, etc. de même, avec une prép. suivie d’un acc. de pers. et un inf. :</i> εἰπεῖν πρός τινα, <i>inf</i>. OD. <i>16, 151,</i> dire à qqn de, <i>etc. ; ou avec une prop. inf</i>. εἶπον τὰς παῖδας δεῦρ' ἄγειν τινά, SOPH. <i>O.C. 923,</i> je l’ai dit : qu’on (me) ramène ici ces jeunes filles ; <i>cf</i>. PLAT. <i>Phædr. 59</i> e ;<br><b>   IV</b> <i>en divers usages :</i><br><b>      1</b> <i>dans les locut. qui répondent au franç</i>. « pour ainsi parler », « pour ainsi dire » <i>etc. ;</i> ὡς ἔπος εἰπεῖν = <i>lat</i>. ut ita dicam, ESCHL. <i>Pers. 714 ;</i> PLAT. <i>Rsp. 341</i> b, <i>etc. ; p. opp. à</i> ὄντως « en réalité », PLAT. <i>Leg. 656</i> e, <i>Rsp. 541</i> b, pour ainsi parler ; <i>de même,</i> ὡς εἰπεῖν, PLAT. <i>Phædr. 258</i> e, <i>etc. ;</i> ὡς ἁπλῶς εἰπεῖν, ARSTT. <i>An. post. 1, 8, 1,</i> pour le dire en un mot ; λόγῳ εἰπεῖν (<i>v</i>. λόγος) ; οὐ πολλῷ λόγῳ εἰπεῖν, HDT. <i>1, 61,</i> pour le dire brièvement ; ἐς τὸ ἀκριϐὲς εἰπεῖν, THC. <i>6, 82,</i> pour parler exactement, <i>etc. ; — de même dans les loc. qui répondent au franç. :</i> « comme qui dirait », « par exemple », « comme on dit » : καθάπερ εἴποι τις Ἀγαθοκλεῖ καὶ Διονυσίῳ, POL. <i>15, 35, 1,</i> comme qui dirait Agathoklès et Dionysios (Agathocle et Denys) ; <i>de même,</i> ὥσπερ εἴποι τις, AR. <i>Av. 180 ; ou</i> ὡς εἴποι τις, D. CHR. <i>2, p. 329,</i> comme on dit ;<br><b>      2</b> <i>à l’impérat</i>. εἰπέ μοι, AR. <i>Ach. 318,</i> mais voyons, dis-moi ; <i>même avec un verbe au plur</i>. ἢ βούλεσθε, εἰπέ μοι ; DÉM. <i>43, 7,</i> est-ce que vous voulez, dites-moi, etc. ? <i>joint à</i> ἄγε : εἰπ' ἄγε (<i>v. ci-dessus</i> II, 6) ;<br><b>B</b> <i>particul. en des emplois divers, avec des nuances de signif. se rattachant à l’idée de</i> « dire, parler » :<br><b>      1</b> <i>en parl. de poètes,</i> chanter : τὰν Αἴαντος ναύμαχον εἶπε βίαν, ANTH. <i>7, 2, 6,</i> il a chanté (<i>litt</i>. il a dit) la valeur d’Ajax combattant pour les vaisseaux (des Grecs) ;<br><b>      2</b> <i>en parl. d’orateurs qui proposent une mesure ou un projet de décret dans l’</i>ἐκκλησία : εἶπε ψήφισμα, DÉM. <i>703, 11,</i> il proposa un décret ; εἰπ. τὰ βέλτιστα, DÉM. <i>31, 22,</i> proposer le meilleur parti ;<br><b>      3</b> <i>en parl. de plaideurs :</i> εἰπ. δίκην, IL. <i>18, 508 ;</i> δικίδιον, AR. <i>Eq. 347,</i> plaider une cause, une méchante petite cause ;<br><b>      4</b> lire, réciter : ἔπη, PLAT. <i>Ion 535</i> b, des vers ;<br><b>      5</b> nommer, appeler : Εὐμενίδας, SOPH. <i>O.C. 43,</i> nommer (les Furies) Euménides ;<br><b>      6</b> mentionner : Ἀγαμέμνονα, IL. <i>1, 90,</i> Agamemnon ; <i>cf</i>. SOPH. <i>Ph. 442 ;</i> EUR. <i>Hec. 881 ;</i><br><b>      7</b> promettre : χρυσὸν εἶφ' ὃς ἂν κτάνῃ, EUR. <i>El. 33,</i> il a promis de l’or à qui (le) tuerait ;<br><b>      8</b> ordonner, prescrire (<i>v. ci-dessus</i> III, 4).<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 ind. poét</i>. ἔειπον, IL. <i>1, 552, etc. ;</i> OD. <i>17, 406 ;</i> PD. <i>O. 4, 25. Impér. 2 pl. épq</i>. ἔσπετε, IL. <i>11, 218 ; 16, 112 ; Com. fr. 2, 407. Sbj. 1 sg. épq</i>. εἴπωμι, OD. <i>22, 392 ; 2 sg</i>. εἴπῃς (<i>3 ex. homér.), épq</i>. εἴπῃσθα, IL. <i>20, 250 ;</i> OD. <i>11, 224 ; 22, 273 ; 3 sg. épq</i>. εἴπῃσι, IL. <i>7, 87. Inf</i>. εἰπεῖν (<i>17 ex. homér.), épq</i>. εἰπέμεναι, IL. <i>7, 375 ; 14, 501 ;</i> OD. <i>4, 682 ; 23, 77 ;</i> SOL. <i>22 ; ou</i> εἰπέμεν (<i>7 ex. homér</i>.) IL. <i>9, 688, etc. ; éol</i>. εἴπην <i>ou</i> ϝείπην, ALC. <i>55 ;</i> SAPPH. <i>28. Part. neutre</i> εἰπόν, OD. <i>4, 838 ; duel masc</i>. εἰπόντε, IL. <i>10, 254 ; 21, 298. — Ao.1 poét. ind</i>. ἔειπα, EMPÉD. <i>75 Stein ;</i> PD. <i>N. 9, 33 ;</i> THCR. <i>Idyl. 22, 153 ; 2 sg</i>. εἶπας, IL. <i>1, 106, 108 ; 3 pl</i>. εἶπαν, HDT. <i>1, 120, etc. ; épq</i>. ἔειπαν (<i>sel. d’autres</i> ἔειπον) HÉS. <i>Th. 24 ; réc</i>. εἴποσαν, SPT. <i>Ruth 4, 11. Impér</i>. εἶπον, <i>ou sel. d’autres,</i> εἰπόν, SIM. <i>fr. 154 Bgk ;</i> PD. <i>O. 6, 92 ;</i> THCR. <i>Idyl. 14, 11 ;</i> XÉN. <i>Mem. 3, 6, 3 ;</i> PLAT. <i>Men. 71 ; 2 pl</i>. εἴπατε, OD. <i>3, 427 ; 21, 198. Part</i>. εἴπας, HDT. <i>1, 41, etc. ; de même dans une inscr. att</i>. CIA. <i>2, 601, 8 (vers 300 av. J.C. ; v. Meisterh. p. 147, 7). — Ao. itér</i>. εἴπεσκον, IL. <i>3, 297, etc. — Moy. réc</i>. ἔσπομαι, SIB. <i>2, 4</i>.<br><span><b>Étym</b>. εἶπον <i>p</i>. ἔ(ϝ)ειπον, <i>de proto-grec</i> *eweik<sup>w</sup>om, <i>indo-europ</i>. *h₁e-ue-uk<sup>w</sup>-om, j’ai dit ; <i>v</i>. ἔπος.</span>\n<br><br>\n➁ <b>ἕπω</b> <span>(<i>impf</i>. εἷπον)</span> s’attacher à, s’occuper de, soigner : τεύχεα, IL. <i>6, 321,</i> s’occuper de ses armes, préparer ses armes ; <i>avec un suj. de ch. :</i> οὐ τόδε μεῖζον ἕπει (<i>vulg</i>. ἔπι) κακόν, OD. <i>12, 209,</i> le danger qui fond sur nous (<i>litt</i>. qui s’attache à nous) en ce moment n’est pas plus grave que, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. seul. prés. ind. 3 sg</i>. ἕπει, OD. <i>12, 209 ; part. acc. sg</i>. ἕποντα, IL. <i>6, 321 ; et impf. 3 pl. épq</i>. ἕπον, IL. <i>11, 483</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *sep-, s’occuper de, prendre soin de ; <i>cf</i>. ὅπλον, <i>sscr</i>. sápati « soigner, honorer », <i>lat</i>. sepeliō « vénérer d’une tombe » ; <i>v</i>. ἀμφέπω, διέπω, ἐφέπω, μεθέπω, περιέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">επω - εἶπον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n968 fois dans 894 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (185)</li>\n<li>Marc (96)</li>\n<li>Luc (305)</li>\n<li>Jean (213)</li>\n<li>Actes (132)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (9)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Colossiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (5)</li>\n<li>1 Jean (4)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2037":"<h1>Erastos</h1>\n<p>Strong n° 2037 <i>Prononciation [er'-as-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eraste (Angl. Erastus) = « bien-aimé »\n<ol>\n<li>un compagnon de l'apôtre Paul</li>\n<li>le chambellan ou trésorier public de Corinthe</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἔραστος, ου (ὁ)</b> Érastos, <i>h</i>. PLAT. <i>Ep. 362</i> b ; STR. <i>608</i>.<br><span><b>Étym</b>. <i>v</i>. ἐραστός.</span><br><br>\n<b>ἐραστός, ή, όν :<br>   I</b> aimable, PLAT. <i>Conv. 204</i> c, <i>Phædr. 250</i> d ;<br><b>   II</b> amoureux :<br><b>      1</b> qui éprouve de l’amour, ANTH. <i>5, 159 ;</i> LUC. <i>Philops. 15 ;</i><br><b>      2</b> qui marque l’amour : ἐραστὸν βλέπειν, HLD. <i>7, 10,</i> avoir un regard amoureux.<br><span>•<i> Cp</i>. -ότερος, ANTH. <i>12, 197</i>.<br><span><b>Étym</b>. <i>vb. de</i> ἐράω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εραστος - Ἔραστος</font>\n<br><br>vient de 'erao' (aimer)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2038":"<h1>ergazomai</h1>\n<p>Strong n° 2038 <i>Prononciation [er-gad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>travailler, faire un travail</li>\n<li>commercer, faire des gains par le commerce</li>\n<li>faire, œuvrer\n<ol type=\"a\">\n<li>exercer, accomplir, commettre</li>\n<li>exploiter, produire</li>\n</ol>\n</li>\n<li>travailler pour, gagner par le travail, acquérir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐργάζομαι</b>, <i>dép. et pass. :</i><br><b>   I</b> <i>dép. (aux temps suiv. : prés</i>. ἐργάζομαι, <i>f</i>. ἐργάσομαι, <i>ao</i>. ἠργασάμην, <i>pf</i>. εἴργασμαι) :<br><b>      1</b> travailler, <i>abs</i>. HDT. <i>8, 71 ;</i> PLAT. <i>Rsp. 372</i> a ; <i>p. opp. à</i> ἀργεῖν « être oisif » HÉS. <i>O. 297, 307 ; en parl. d’un travail forcé,</i> OD. <i>14, 272 ;</i> ἐργ. ἐν τοῖς ἔργοις, DÉM. <i>1048 fin,</i> travailler dans les mines ; <i>en parl. d’animaux (bœufs, abeilles, etc</i>.) SOPH. <i>fr. 149 ;</i> ARSTT. <i>H.A. 9, 18, 1 ; 9, 40, 43 ; en parl. des forces de la nature (air, etc</i>.) TH. <i>C.P. 5, 12, 7 ;</i><br><b>      2</b> <i>avec un rég</i>. façonner par son travail, travailler qqe ch. : χρυσόν, OD. <i>3, 435,</i> de l’or ; γῆν καὶ ξύλα καὶ λίθους, XÉN. <i>Hell. 3, 3, 7,</i> la terre, le bois et la pierre ; <i>abs</i>. ἐργάζεσθαι, XÉN. <i>Cyr. 1, 6, 11,</i> travailler la terre ; ἐργ. θάλασσαν, DH. <i>3, 46, ou</i> γλαυκήν, HÉS. <i>Th. 440,</i> pratiquer la mer comme marchand <i>ou</i> comme pêcheur ; τὴν τροφήν, ARSTT. <i>H.A. 9, 18, 1,</i> digérer la nourriture ; <i>fig</i>. τέχνην, PLAT. <i>Rsp. 374</i> a ; ἐργασίαν, PLAT. <i>Phæd. 60</i> e, pratiquer un art, un métier ; ἀρετήν, ISOCR. <i>292</i> a, pratiquer une vertu ;<br><b>      3</b> produire par son travail : ἔργα, IL. <i>24, 733 ;</i> OD. <i>20, 72,</i> des oeuvres ; ἀγάλματα, PD. <i>N. 5, 2 ;</i> εἰκόνας, PLAT. <i>Crat. 431</i> c ; ἀνδριάντας, XÉN. <i>Mem. 2, 6, 6,</i> des statues ; ὕμνους, PD. <i>I. 2, 66,</i> composer des chants ; τὸν βίον, AND. <i>18, 42,</i> se procurer des ressources pour vivre ; ἀργύριον, PLAT. <i>Hipp. ma. 282</i> d ; χρήματα, HDT. <i>1, 24 ;</i> AR. <i>Eq. 840,</i> se procurer de l’argent, des richesses ; <i>d’où abs</i>. se procurer des ressources en trafiquant, faire du commerce : ἀργυρίῳ, DÉM. <i>1293, 3,</i> avec de l’argent, <i>càd</i>. comme banquier ; σώματι, DÉM. <i>1351, 21 ;</i> ἀπὸ τοῦ σώματος, POL. <i>12, 13, 2,</i> trafiquer de son corps ; ἐν τῇ ἀγορᾷ, DÉM. <i>1308, 9 ;</i> κατὰ θάλασσαν, DÉM. <i>1297, 8,</i> faire du commerce sur la place publique, sur mer ; <i>abs</i>. οἱ ἐργαζόμενοι, DÉM. <i>922, 10,</i> les commerçants ;<br><b>      4</b> <i>p. ext</i>. produire, accomplir, faire : ἐργ. ἔργον, SOPH. <i>Ant. 267,</i> agir (<i>p. opp. à</i> βουλεύειν) ; φίλα, OD. <i>17, 321, etc</i>. faire des choses agréables (à qqn), travailler selon le désir de qqn ; ἐργ. κακά, PLAT. <i>Prot. 345</i> e ; δεινὰ καὶ ἀσεϐῆ, PLAT. <i>Rsp. 391</i> d, commettre de mauvaises actions, des actions coupables et impies ; <i>avec double rég</i>. ἀγαθὰ <i>ou</i> κακὰ ἐργ. τινα, HDT. <i>8, 79 ;</i> THC. <i>1, 137 ;</i> SOPH. <i>El. 1206, Aj. 109 ;</i> PLAT. <i>Phædr. 244</i> b, faire du bien <i>ou</i> du mal à qqn ; <i>rar</i>. τί τινι, EUR. <i>Hec. 1085 ;</i> AR. <i>Vesp. 1350 ;</i> τι εἴς τινα, SYN. <i>193,</i> faire qqe ch. à qqn ; <i>p. suite,</i> causer : πημονάς, SOPH. <i>Ant. 236,</i> de l’affliction ; πόθον τινί, DÉM. <i>1404, 18,</i> du regret à qqn ; <i>avec double rég. :</i> τινα μέγαν, EL. <i>V.H. 3, 1,</i> rendre qqn grand (<i>d’ord</i>. ἀπεργάζεσθαι) ;<br><b>   II</b> <i>pass. (touj. au fut</i>. ἐργασθήσομαι, <i>à l’ao</i>. εἰργάσθην ; <i>souv. au pf</i>. εἴργασμαι <i>et pl.q.pf</i>. εἰργάσμην ; <i>rar. au prés. ou à l’impf</i>.) être travaillé, <i>en parl. de la terre, de matériaux, d’objets fabriqués :</i> εἰργασμένη γῆ, XÉN. <i>Œc. 19, 8,</i> terre cultivée ; λίθοι εἰργασμένοι, THC. <i>1, 93,</i> pierres travaillées ; οἰκοδόμημα διὰ ταχέων εἰργασμένον, THC. <i>4, 8,</i> construction faite en hâte ; θώρακας εὖ εἰργασμένους, XÉN. <i>Mem. 3, 10, 9,</i> cuirasses bien faites ; <i>en parl. d’actions ;</i> τὰ εἰργασμένα EUR. <i>Ion 1281,</i> les choses faites, les actions ; ἔργ' ἔστι εἰργασμένα, SOPH. <i>O.R. 1374,</i> des actes ont été commis ; τὰ ἐργασμένα (<i>ion</i>.) Πέρσῃσι, HDT. <i>7, 53,</i> les faits et gestes des Perses ; τὸ χρῆμ' ἐργάζεται, AR. <i>Eccl. 148,</i> l’affaire presse (<i>litt</i>. est en pleine activité).<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. l’impf. et l’ao. d’ord. en</i> ἠ-, <i>le pf. touj. en</i> εἰ-: ἠργάζοντο, CIA. <i>2, 14, 17 (387 av. J.C</i>.) ; ἠργάζετο, CIA. <i>2, 782, 11 (4<sup>e</sup> siècle av. J.C</i>.) ; ἠργάζετο, CIA. <i>2, 780, 8 (envir. 300 av. J.C</i>.) ; ἠργάσατο, <i>Bull. de corr. hell. 2, 547 (inscr. du 4<sup>e</sup> siècle av. J.C.) ; par except. dans les composés</i> κατειργάσθησαν <i>et</i> ἐπειργάσαντο (<i>v. Meisterh. p. 136, note 1190) ; pour le pf. touj</i>. εἴργασμαι, <i>sauf une except</i>. τῶν ἠργασμένων, <i>Mitt. 8, 59, 12 (commenc. du 1<sup>er</sup> siècle av. J.C.) (v. Meisterh. Mitt.). — Formes poét. ou rares : prés. impér</i>. ἐργάζευ, HÉS. <i>O. 299. Impf. épq. et ion</i>. ἐργαζόμην, OD. <i>24, 210 ;</i> HDT. <i>1, 66. Fut. dor. 2 sg</i>. ἐργαξῇ, THCR. <i>Idyl. 10, 23 ; réc</i>. ἐργῶμαι = ἐργάσομαι, SPT. <i>Gen. 29, 27 ; 2 sg</i>. ἐργᾷ = ἐργάσῃ, SPT. <i>Ex. 20, 9 ; 3 sg</i>. ἐργᾶται = ἐργάσεται, SPT. <i>Sir. 13, 4. Ao. dor</i>. εἰργασάμαν, PD. <i>I. 2, 46 ; opt. 2 sg. épq</i>. ἐργάσσαιο, HÉS. <i>O. 43 ; 3 pl</i>. ἐργασαίατο, AR. <i>Av. 1147, Lys. 42. Pf. ion</i>. ἔργασμαι, HDT. <i>2, 121, etc. — Au sens pass. prés</i>. DH. <i>8, 87 ; impf. 3 sg</i>. ἠργάζετο, HYPÉR. <i>Eux. 44 ; fut</i>. ἐργασθήσομαι, SOPH. <i>Tr. 1218 ;</i> ISOCR. <i>Ep. 6 ; ao</i>. εἰργάσθην, PLAT. <i>Pol. 281</i> e, <i>Rsp. 353</i> a ; <i>pf</i>. εἴργασμαι, ESCHL. <i>Ag. 254, 1346 ;</i> SOPH. <i>O.R. 1369 ;</i> EUR. <i>Or. 384 ;</i> AR. <i>Ran. 1023 ;</i> THC. <i>1, 93 ;</i> PLAT. <i>Rsp. 381</i> a ; <i>pl.q.pf</i>. HDT. <i>1, 179 (3 sg. ion</i>. ἔργαστο) ; DÉM. <i>53, 18</i>.<br><span><b>Étym</b>. ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εργαζομαι - ἐργάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n40 fois dans 37 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (8)</li>\n<li>Actes (3)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2039":"<h1>ergasia</h1>\n<p>Strong n° 2039 <i>Prononciation [er-gas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un travail, une réalisation</li>\n<li>affaire</li>\n<li>gain obtenu par le travail, profit</li>\n<li>s'efforcer, tâcher de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐργασία, ας (ἡ)</b> <span>[γᾰ]</span><br><b>   I</b> <i>abs. :</i><br><b>      1</b> travail, HH. <i>Merc. 486 ; p. opp. à</i> ἀργία, XÉN. <i>Mem. 2, 7, 7 ;</i> ARSTT. <i>Nic. 4, 1, 40 ; en parl. d’abeilles,</i> ARSTT. <i>H.A. 9, 40 ; p. suite,</i> soin, peine qu’on a pour qqe ch. : ἐργασίαν διδόναι, <i>avec l’inf</i>. NT. <i>Luc. 12, 58,</i> donner son soin à, se donner de la peine pour ;<br><b>      2</b> force active, force productrice <i>d’où</i> propriété (physique <i>ou</i> chimique) d’un corps, PHIL. BYZ. ;<br><b>   II</b> <i>avec un rég</i>. action de façonner par son travail, action de travailler qqe ch., <i>d’où :</i><br><b>      1</b> travail, préparation : σιδήρου, HDT. <i>1, 68 ;</i> ἐρίων, ξύλων, PLAT. <i>Charm. 173</i> e, du fer, de la laine, du bois ; γῆς, AR. <i>Ran. 1034,</i> de la terre ; περὶ τὰ ξύλα, PLAT. <i>Euthyd. 281</i> a, travail du bois ; τροφῆς, ARSTT. <i>Pol. 11, 1,</i> travail de la digestion ;<br><b>      2</b> pratique : τῆς τραπέζης, DÉM. <i>946, 3,</i> trafic de banque ; τῶν τεχνῶν, PLAT. <i>Gorg. 450</i> e, pratique des arts ;<br><b>      3</b> action de produire par son travail : τειχῶν, THC. <i>7, 6,</i> construction de murs ; ἱματίων, ὑποδημάτων, PLAT. <i>Gorg. 449</i> d, <i>Theæt. 146</i> d, confection de vêtements, de chaussures ; ἐσθῆτος ἐκ τῶν ἐρίων, XÉN. <i>Œc. 7, 21,</i> confection d’un vêtement avec de la laine ; χρημάτων, ARSTT. <i>Nic. 8, 9, 5,</i> action d’acquérir de l’argent ; <i>d’où abs</i>. action de se procurer des ressources, HDT. <i>2, 135 ;</i> XÉN. <i>Mem. 3, 10, 1, etc. ;</i> action de produire, <i>en gén</i>. intérêt (d’un capital) CHRYS. <i>50, 529 Migne</i>.<br><span><b>Étym</b>. ἐργάζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εργασια - ἐργασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (4)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2040":"<h1>ergates</h1>\n<p>Strong n° 2040 <i>Prononciation [er-gat'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un travailleur, un ouvrier, artisan\n<ol type=\"a\">\n<li>généralement celui qui travaille en se louant, un ouvrier agricole</li>\n</ol>\n</li>\n<li>celui qui fait, le travailleur, le commettant</li>\n<li>les apôtres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐργάτης, ου</b> <span>[ᾰ]</span><br><b>   I</b> <i>subst</i>. (ὁ) qui travaille, <i>d’où :</i><br><b>      1</b> auteur <i>ou</i> artisan de qqe ch. : ἐ. τῶν καλῶν, XÉN. <i>Mem. 2, 1, 27 ;</i> ἀδικίας, NT. <i>Luc. 13, 27,</i> artisan de belles œuvres, d’injustice ; <i>abs</i>. SOPH. <i>Ant. 252 ;</i><br><b>      2</b> homme de travail, artisan, ouvrier : γῆς ἐργ. HDT. <i>4, 109 ; 5, 6 ;</i> PLUT. <i>Cim. 8, ou simpl</i>. ἐργ. SOPH. <i>O.R. 859 ;</i> EUR. <i>El. 75 ;</i> XÉN. <i>Cyr. 5, 4, 24, 28,</i> cultivateur, laboureur ; ἐ. θαλάσσης, ALCIPHR. <i>1, 11,</i> pêcheur ; ἐ. λίθων, LUC. <i>Somn. 2,</i> tailleur de pierres ; ἐ. δίκης, LYC. <i>128,</i> juge ;<br><b>      3</b> <i>t. de mécan</i>. levier de serrage d’une vis, BITON (<i>Math. 110</i> e) ;<br><b>   II</b> <i>adj. :</i><br><b>      1</b> qui travaille, <i>en parl. d’animaux (bœufs, abeilles, etc</i>.) SOPH. <i>fr. 149 ;</i> ARSTT. <i>H.A. 9, 41, 2, etc. ;</i><br><b>      2</b> actif, laborieux, XÉN. <i>Cyr. 1, 6, 18, p. opp. à</i> ἀργός ; PLAT. <i>Euthyd. 281</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. dor</i>. ἐργάτᾳ, THCR. <i>Idyl. 10, 9</i>.<br><span><b>Étym</b>. ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εργατης - ἐργάτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Luc (4)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2041":"<h1>ergon</h1>\n<p>Strong n° 2041 <i>Prononciation [er'-gon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>affaire, emploi, ce à quoi chacun est employé\n<ol type=\"a\">\n<li>ce que chacun entreprend de faire, entreprise</li>\n</ol>\n</li>\n<li>tout produit réalisé, ce qui est fait à la main, art, œuvre de l'esprit</li>\n<li>acte, ce qui est fait, action</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔργον, ου (τὸ) :<br>   I</b> action, <i>p. opp. à inaction</i> (ἀεργίη) HÉS. <i>O. 313 ; p. opp. à</i> parole, vain mot (ἔπος, ESCHL. <i>Pers. 170 ;</i> HDT. <i>3, 135 ;</i> μῦθος, IL. <i>9, 443 ;</i> ESCHL. <i>Pr. 1080 ;</i> λόγος, SOPH. <i>El. 358 ;</i> EUR. <i>Alc. 339 ;</i> ῥῆμα, SOPH. <i>O.C. 873 ;</i> ὄνομα, THC. <i>8, 78, 89 ;</i> EUR. <i>I.A. 128, etc.) ; en ce sens, qqf. au plur</i>. λόγῳ μὲν…, τοῖσι δ' ἔργοισιν, SOPH. <i>O.C. 782 ;</i> λόγῳ…, τοῖς δ' ἔργοισιν, EUR. <i>Erechth. fr. 362, 13 Nauck,</i> en parole…, mais en fait ; <i>avec les deux termes au plur</i>. λόγοισιν εἴτ' ἔργοισιν, SOPH. <i>O.R. 517</i> soit en parole, soit en action ; <i>p. suite,</i> réalisation <i>ou</i> exécution d’une ch. ; χωρεῖν πρὸς ἔργον, SOPH. <i>Aj. 116,</i> en venir à l’exécution ; τὸ μὲν ἐνθύμημα χαρίεν, τὸ δὲ ἔργον ἀδύνατον, XÉN. <i>An. 3, 5, 12,</i> la pensée est agréable, mais la réalisation est impossible ;<br><b>   II</b> œuvre, ouvrage :<br><b>      1</b> occupation, travail : ἄλλος ἄλλοισιν ἐπιτέρπεται ἔργοις, OD. <i>14, 228,</i> l’un se plaît à un travail, l’autre à un autre ; ἐπὶ ἔργα τραπέσθαι, IL. <i>3, 422,</i> se tourner vers ses travaux ; ἔργων παύσασθαι, OD. <i>4, 683,</i> cesser ses travaux ; πίονα ἔργα, IL. <i>12, 280,</i> les travaux féconds (du labour) ; <i>p. ext</i>. terre labourée : ἔργα Ἰθάκης, OD. <i>14, 344,</i> les terres d’Ithaque ; <i>d’où</i> bien <i>ou</i> domaine de campagne : πατρώϊα ἔργα, OD. <i>2, 22,</i> les domaines paternels ; <i>cf</i>. OD. <i>2, 127, 252 ; au sg</i>. ἔργον ἀέξειν, OD. <i>14, 65 ; 15, 372,</i> accroître son bien ; <i>en parl. de la guerre,</i> πολεμήϊα ἔργα, IL. <i>2, 338 ;</i> OD. <i>12, 116,</i> travaux de la guerre ; ἔργον μάχης, IL. <i>6, 522,</i> l’œuvre du combat ; <i>abs</i>. ἔργον, guerre, combat, IL. <i>4, 175 ;</i> ESCHL. <i>Sept. 414 ;</i> τὸ Τρωϊκὸν ἔργον, ARR. <i>An. 1, 11, 12,</i> la guerre de Troie (<i>cf. franç</i>. une geste) ; ἔργον ἔχεσθαι, PD. <i>P. 4, 414,</i> engager une action (<i>cf. lat</i>. rem gerere) ; ἐν τῷ ἔργῳ, THC. <i>2, 89,</i> pendant l’action ; θαλάσσια ἔργα, IL. <i>2, 614 ;</i> OD. <i>5, 67,</i> travaux de la mer, <i>en parl. de pêcheurs,</i> OD. <i>5, 67 ; ou de marins,</i> IL. <i>2, 614 ;</i> ἔργα ἀργυρεῖα, XÉN. <i>Vect. 4, 5,</i> travaux dans les mines d’argent, <i>cf</i>. DÉM. <i>967, 17 ; abs. en ce sens :</i> ἔργα ἐργάζεσθαι, OD. <i>20, 72 ; 22, 422,</i> faire des travaux de tapisserie, de broderie ; <i>p. ext. joint par périphr. à beaucoup d’autres mots :</i> ἔργα δαιτός, IL. <i>9, 228 ;</i> γάμοιο, IL. <i>5, 429,</i> festin, mariage, <i>etc. ;</i><br><b>      2</b> <i>en mauv. part,</i> manœuvre, intrigue, SOPH. <i>O.R. 538 ;</i><br><b>      3</b> affaire dont on se charge, besogne propre à qqn ; ἔργον ἔχω, <i>inf</i>. XÉN. <i>Mem. 2, 10, 6,</i> c’est mon affaire de ; ἀνδρῶν τόδ' ἐστὶν ἔργον, ESCHL. <i>Ch. 673,</i> c’est l’affaire des hommes ; ὅπερ ἐστὶν ἔργον ἀγαθοῦ πολίτου, PLAT. <i>Gorg. 517</i> c, ce qui est l’affaire d’un bon citoyen ; <i>en parl. de choses :</i> ἅπερ νεῶν ἄμεινον πλεουσῶν ἔργα ἐστίν, THC. <i>2, 89,</i> toutes choses qui sont l’affaire de navires bons marcheurs ; <i>avec le dat. :</i> οἷς τοῦτο ἔργον ἦν, XÉN. <i>Cyr. 4, 5, 36,</i> ceux dont c’était l’affaire ; <i>avec un pron. :</i> σόν, ἐμόν, ὑμέτερον ἔργον ἐστί, <i>avec l’inf</i>. ESCHL. <i>Pr. 635, Eum. 734 ;</i> AR. <i>Pax 426,</i> c’est mon, ton, votre affaire de, <i>etc. ; avec l’art</i>. ἡμέτερον τὸ ἔργον, HDT. <i>5, 1,</i> c’est notre affaire ; <i>par parenth</i>. σὸν ἔργον, θῦε θεοῖς, AR. <i>Av. 862,</i> sacrifie aux dieux, c’est ton affaire ; ἔργον ποιεῖσθαί τι, XÉN. <i>Hier. 9, 10 ;</i> PLAT. <i>Tim. 27</i> a, <i>Phædr. 232</i> a, <i>Eryx. 392</i> b ; ἐν ἔργῳ τίθεσθαι, EL. <i>V.H. 4, 15,</i> faire son affaire de qqe ch., apporter toute son attention à qqe ch. ; <i>particul</i>. travail difficile <i>ou</i> pénible : ἔργον (ἐστί) <i>avec l’inf</i>. XÉN. <i>Cyr. 3, 3, 27 ; ou</i> ἔργον ἐστὶν εἰ, DÉM. <i>716, 22,</i> c’est une affaire de, <i>etc. ;</i> ce serait une affaire si, <i>etc. ;</i> μέγα ἔργον ἐστί, <i>avec l’inf</i>. PLAT. <i>Conv. 187</i> e ; EUR. <i>Bacch. 267 ;</i> ἔργον χαλεπόν ἐστι, AR. <i>Ran. 1100 ;</i> πολὺ ἔργον ἐστί, XÉN. <i>Mem. 4, 6, 1,</i> c’est une grosse affaire de, <i>etc. ;</i><br><b>      4</b> affaire dont il faut se charger, besoin, nécessité (<i>cf. lat</i>. opus) : τί δῆτα τόξων ἔργον ; EUR. <i>Alc. 39,</i> quel besoin d’arcs ? <i>avec une nég</i>. οὐδὲν ἔργον ἐστί, <i>gén</i>. AR. <i>Pax 1310, Pl. 1158 ; cf</i>. EUR. <i>Hipp. 911 ; ou inf</i>. SOPH. <i>Aj. 852,</i> il n’y a aucun besoin de, <i>etc. ; avec un dat. de pers. :</i> οὐ μακρῶν λόγων ἡμὶν τόδε τοὔργον, SOPH. <i>El. 1372,</i> nous n’avons pas besoin de longs discours ; ἔργον ἐστί, <i>avec une prop. inf</i>. il est nécessaire que, ARSTT. <i>Pol. 3, 15, 8 ;</i><br><b>      5</b> affaire, embarras : ἔργα παρέχειν τινί, AR. <i>Nub. 515 ;</i> PLAT. <i>Tim. 29</i> d, causer de l’ennui à qqn ; ἔργον ἔχειν, <i>avec un part,</i> XÉN. <i>Cyr. 8, 4, 6,</i> être ennuyé <i>ou</i> troublé de, <i>etc. ;</i><br><b>   III</b> travail accompli :<br><b>      1</b> œuvre, ouvrage : ἔργα γυναικῶν, IL. <i>6, 289 ;</i> OD. <i>7, 97, etc</i>. œuvres de femmes, <i>en parl. de vêtements ;</i> λώτινον ἔργον, THCR. <i>Idyl. 24, 25,</i> ouvrage en bois de lotus ; <i>en parl. d’armes,</i> IL. <i>19, 22 ; d’une statue,</i> XÉN. <i>Mem. 3, 10, 7 ; de travaux de siège,</i> POL. <i>5, 3, 6 ; d’écrits,</i> DH. <i>5, 208 Reiske ;</i> ANTH. <i>11, 354, 8, etc. ;</i> τὰ ἑπτὰ ἐπιφανέστατα ἔργα, DS. <i>1, 63,</i> les sept merveilles du monde (<i>v</i>. ἑπτά) ; <i>en mauv. part</i>. ἔργον εἶναι <i>ou</i> γίγνεσθαι, <i>gén</i>. être <i>ou</i> devenir l’œuvre accomplie (par qqn <i>ou</i> par qqe ch.) : ἔργον εἶναι νόσου, ANON. (SUID. <i>v.°</i> ἄτολμος) devenir la proie <i>ou</i> la victime de la maladie ; κτεινόμενος ὑμέτερον ἔργον εἰμί, PLUT. <i>Eum. 17,</i> si je suis tué, ce sera par votre fait, <i>litt</i>. ce sera votre œuvre ;<br><b>      2</b> <i>en parl. d’argent,</i> ce qui est l’œuvre de, ce qui est produit par : ἔργον χρημάτων, IS. <i>88, 24 ;</i> DÉM. <i>816, 16 ; 819, 2,</i> produit d’un capital, intérêts ;<br><b>   IV</b> <i>en gén</i>. chose, affaire, <i>càd</i>. fait, acte, événement, IL. <i>2, 252 ; 6, 348, etc. ;</i> OD. <i>17, 78, etc. ;</i> ἄκουε τοὔργον, SOPH. <i>Tr. 1157,</i> écoute la chose.<br><span><b><span class=\"arrow\"></span></b> Crase <i>au sg</i>. τοὔργον (<i>v. ci-dessus) ; au plur</i>. τἄργα, SOPH. <i>Ph. 99</i>.<br><span><b>Étym</b>. <i>p</i>. *ϝέργον, <i>cf</i>. ἔρδω <i>et</i> ῥέζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εργον - ἔργον</font>\n<br><br>vient du mot primaire mais désuet 'ergo' (travailler)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n174 fois dans 159 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (27)</li>\n<li>Actes (11)</li>\n<li>Romains (18)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (3)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (8)</li>\n<li>Hébreux (10)</li>\n<li>Jacques (15)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (3)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (20)</li>\n</ul>\n</td></tr>\n</table>","G2042":"<h1>erethizo</h1>\n<p>Strong n° 2042 <i>Prononciation [er-eth-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bousculer, exciter, stimuler, provoquer, irriter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρεθίζω</b> <span>(<i>impf</i>. ἠρέθιζον, <i>f</i>. ἐρεθίσω, <i>att. et ion</i>. -ιῶ ; <i>ao</i>. ἠρέθισα, <i>pf</i>. ἠρέθικα ; <i>pass. ao</i>. ἠρεθίσθην, <i>pf</i>. ἠρέθισμαι, <i>pl.q.pf</i>. ἠρεθίσμην)</span><br><b>      1</b> provoquer au combat, provoquer : τινά, IL. <i>1, 32 ; 5, 419, etc. ;</i> HDT. <i>3, 146 ;</i> SOPH. <i>Ant. 965 ;</i> AR. <i>Lys. 475,</i> qqn ; <i>en parl. d’un lion :</i> ἐρ. κύνας τ' ἄνδρας τε, IL. <i>17, 658,</i> provoquer les chiens et les hommes ; ἐρ. κερτομίοισι ἔπεσσι, IL. <i>4, 5,</i> provoquer par des paroles outrageantes ;<br><b>      2</b> <i>en gén</i>. exciter : τινά, OD. <i>19, 45,</i> la curiosité de qqn ; φρένας, ESCHL. <i>Pr. 181,</i> exciter l’esprit ; <i>p. anal</i>. πνεῦμα ἠρεθισμένον, EUR. <i>Med. 1119,</i> souffle (pressé) d’un coureur ; ἕλκος ἠρεθισμένον, HPC. <i>Fract. 768 ;</i> POL. <i>1, 81, 6,</i> blessure <i>ou</i> plaie irritée ;<br><b>      3</b> <i>p. suite,</i> mettre en mouvement : χορούς, EUR. <i>Bacch. 148,</i> des chœurs de danse ; μάγαδιν, TÉLEST. (ATH. <i>637</i> a) toucher de la harpe.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. dor</i>. ἐρεθίσδω, THCR. <i>Idyl. 5, 110 ; inf. épq</i>. ἐρεθιζέμεν, IL. <i>4, 5 ; impf. épq</i>. ἐρέθιζον, IL. <i>5, 419 ;</i> TÉLEST. <i>4 Bgk ; ao. poét</i>. ἐρέθισα, ESCHL. <i>Pr. 181 ; inf. poét</i>. ἐρεθίξαι, ANTH. <i>12, 57</i>.<br><span><b>Étym</b>. ἐρέθω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερεθιζω - ἐρεθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2043":"<h1>ereido</h1>\n<p>Strong n° 2043 <i>Prononciation [er-i'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fixer, s'appuyer fermement, fortement, engager solidement, enfoncer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρείδω</b> <span>(<i>impf</i>. ἤρειδον, <i>f</i>. ἐρείσω, <i>ao</i>. ἤρεισα, <i>pf. réc</i>. ἐρήρεικα ; <i>pass. ao</i>. ἠρείσθην, <i>pf</i>. ἐρήρεισμαι <i>et</i> ἤρεισμαι ; <i>pl.q.pf</i>. ἠρηρείσμην)</span><br><b>   I <i>tr</i>.<br>      1</b> appuyer fortement : πόδας ἔς τι, A. RH. <i>1, 1010,</i> ses pieds sur qqe ch. ; τι πρός τι, IL. <i>22, 112 ;</i> OD. <i>8, 66, 473 ;</i> PLAT. <i>Phædr. 254</i> e ; <i>ou</i> ἐπί τινι, IL. <i>22, 97 ;</i> A. RH. <i>1, 1234 ;</i> ἐπί τινος, PLAT. <i>Tim. 43</i> e ; εἴς τι, PLAT. <i>Tim. 91</i> e ; κατά τινος, PLUT. <i>Flam. 20,</i> appuyer une ch. sur <i>ou</i> contre une autre ; <i>fig</i>. ὄμμα ἐς γῆν, EUR. <i>I.A. 1123 ;</i> ἐπὶ χθονὸς ὄμματα, A. RH. <i>1, 784,</i> fixer ses yeux vers la terre ; <i>au pass</i>. être appuyé fortement, <i>càd</i>. être fixé solidement, être ferme, solide, <i>en parl. de pierres solidement fixées,</i> IL. <i>23, 329 ; de sièges,</i> OD. <i>7, 95 ;</i> ἔγχος διὰ θώρηκος ἠρήρειστο, IL. <i>3, 358,</i> la javeline, traversant la cuirasse, s’était fixée solidement ;<br><b>      2</b> <i>p. suite,</i> soutenir : ἀσπὶς ἄρ' ἀσπίδ' ἔρειδε, κόρυς κόρυν, ἀνέρα δ' ἀνήρ, IL. <i>13, 131 ; 16, 215,</i> ils étaient bouclier contre bouclier, casque contre casque, homme contre homme ; κίον' οὐρανοῦ τε καὶ χθονὸς ὤμοιν ἐρ. ESCHL. <i>Pr. 350,</i> soutenir sur ses épaules la colonne du ciel et de la terre ;<br><b>      3</b> <i>p. ext</i>. enfoncer avec force : ἄγκυραν χθονί, PD. <i>P. 10, 51,</i> une ancre dans le sol ; τόξῳ, PD. <i>O. 9, 33,</i> percer qqn d’un trait ;<br><b>   II <i>intr</i>.<br>      1</b> s’appuyer fortement : ἀλλήλῃσιν, OD. <i>22, 450,</i> les unes sur les autres ; ἐρ. ἐπὶ τὸ ἔδαφος, HÉRON <i>Aut. 245,</i> avoir de l’adhérence sur le sol, <i>en parl. de roues motrices d’un mécanisme ; abs</i>. ἔρειδε, AR. <i>Pax 31,</i> appuie ! <i>càd</i>. ferme ! <i>en t. de mar</i>. souque ! <i>pour commander une vogue ou nage accélérée ;</i><br><b>      2</b> <i>p. suite,</i> s’abattre sur, fondre sur, <i>abs. en parl. d’une maladie,</i> ESCHL. <i>Ag. 1004 ;</i> ἐπὶ γῆν, PLUT. <i>Num. 2,</i> sur la terre ; <i>fig</i>. εἴς τινα, AR. <i>Nub. 558,</i> s’attaquer à qqn, s’acharner après qqn ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr</i>.<br>      1</b> s’appuyer sur : σκήπτρῳ, IL. <i>2, 109,</i> sur son sceptre ; ἔγχει, IL. <i>14, 38,</i> s’appuyer sur sa lance ; <i>avec</i> ἐπί <i>et le gén</i>. IL. <i>22, 225 ; avec le gén</i>. χειρὶ γαίης, IL. <i>5, 309,</i> s’appuyer de la main sur la terre ; <i>abs</i>. se poser solidement, IL. <i>12, 457 ;</i><br><b>      2</b> s’appuyer l’un contre l’autre, s’étreindre en luttant, IL. <i>23, 735 ;</i><br><b>   II <i>tr.</i></b> appuyer : ἐπὶ γαῖαν ἴχνος, ANTH. <i>12, 84,</i> ses pas sur la terre ; χειρὶ παρείην, A. RH. <i>3, 1160,</i> sa joue sur sa main ; λίθον ἐπὶ τοίχῳ, THCR. <i>Idyl. 23, 49,</i> fixer une pierre sur un mur ; <i>fig</i>. ἔπος πρὸς ἔπος, AR. <i>Nub. 1375,</i> opposer parole contre parole, <i>càd</i>. se donner vivement la réplique, riposter vivement.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. poét</i>. ἔρεισα, HH. <i>Ap. 1, 117 ;</i> A. RH. <i>1, 1198 ; pf. réc</i>. ἐρήρεικα, DIOSC. <i>Eup. 1, 90. — Pass. pf. 3 pl</i>. ἐρήρεινται, A. RH. <i>2, 320, ou épq</i>. ἐρηρέδαται, IL. <i>23, 284 ; pl.q.pf. 3 pl. épq</i>. ἐρηρέδατο, OD. <i>7, 95 (var</i>. ἐληλάδατο) ; <i>fut. ant. 3 sg</i>. ἐρηρείσεται, HPC. <i>8, 292. — Moy. ao</i>. ἐρεισάμην, IL. <i>5, 309</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερειδω - ἐρείδω</font>\n<br><br>affinité obscure</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2044":"<h1>ereugomai</h1>\n<p>Strong n° 2044 <i>Prononciation [er-yoog'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cracher ou vomir, rejeter</li>\n<li>être vidé, se décharger\n<ol type=\"a\">\n<li>vider, décharger, rejeter, utilisé pour fleuves et rivières</li>\n</ol>\n</li>\n<li>émettre des paroles, parler à voix haute, publier, donner de la voix, proclamer, crier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρεύγομαι</b> (ἐρεύξομαι, <i>ao</i>. ἠρευξάμην, <i>ao.2</i> ἤρυγον <span>[ῠ]</span>) faire un bruit ronflant, <i>d’où :</i><br><b>   I</b> (<i>seul. ao.2</i> ἤρυγον <span>[ῡ]</span>) <i>en parl. de taureaux,</i> mugir, IL. <i>20, 403 ; en parl. de lions,</i> rugir, SPT. <i>Hos. 11, 10 ; 1 Macc. 3, 4 ; d’où</i> crier du plus profond de la poitrine, THCR. <i>Idyl. 13, 58 ;</i><br><b>   II</b> rejeter avec bruit, <i>d’où :</i><br><b>      1</b> roter, OD. <i>9, 374 ;</i> HPC. <i>485, 29 ;</i> ARSTT. <i>Probl. 10, 37 ;</i><br><b>      2</b> vomir avec bruit, vomir (du sang, du poison) IL. <i>16, 162 ;</i> NIC. <i>Th. 232 ; p. anal. abs. en parl. d’un volcan,</i> PD. <i>P. 1, 40 ; de la mer qui vomit son écume ou se brise sur le rivage,</i> IL. <i>17, 265 ;</i> OD. <i>5, 403, 438 ; avec un rég</i>. ἀφρόν, ὕδατος ἄχνην, DP. <i>539, etc</i>. vomir de l’écume ; <i>fig</i>. χρυσόν, ANTH. <i>5, 2,</i> avoir toujours son or à la bouche, vanter sa fortune ;<br><b>      3</b> <i>p. ext</i>. parler d’une voix forte, crier, SPT. <i>Ps. 18, 2 ; 118, 171 ; 144, 7 ;</i> NT. <i>Matth. 13, 55</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét. 3 sg</i>. ἐρεύγετο, OD. <i>9, 374</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁reug-, roter ; <i>cf. lat</i>. ē-rūgō, rūgiō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερευγομαι - ἐρεύγομαι</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2045":"<h1>ereunao</h1>\n<p>Strong n° 2045 <i>Prononciation [er-yoo-nah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>chercher, examiner, sonder</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐραυνάω-ῶ</b>, <i>forme alexandrine p</i>. ἐρευνάω, SPT. <i>Gen. 31, 33 ; 44, 12, var. ;</i> NT. <i>Joh. 5, 39 (var</i>. ἐρευ-) ; <i>1Cor. 2, 10 ; 1Petr. 1, 11 ; Apoc. 2, 23</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερευναω - ἐραυνάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2046":"<h1>ereo</h1>\n<p>Strong n° 2046 <i>Prononciation [er-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prononcer, parler, dire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εἶπον</b>, <i>v</i>. *.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερεω - εἶπον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n71 fois dans 71 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (2)</li>\n<li>Luc (18)</li>\n<li>Jean (6)</li>\n<li>Actes (7)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2047":"<h1>eremia</h1>\n<p>Strong n° 2047 <i>Prononciation [er-ay-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une solitude, une région inhabitée, un désert</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρημία, ας (ἡ) :<br>      1</b> lieu solitaire, désert, HDT. <i>3, 98 ;</i> ESCHL. <i>Pr. 2 ;</i> AR. <i>Ach. 704 ; au plur</i>. ARSTT. <i>H.A. 9, 3, 2, etc. ;</i><br><b>      2</b> état d’une personne qui vit seule, solitude, isolement : ἐρημίαν ἄγειν, EUR. <i>Med. 50, ou</i> ἔχειν, EUR. <i>Bacch. 609 ;</i> ἐρημίας τυχεῖν, EUR. <i>El. 510,</i> vivre dans la solitude ;<br><b>      3</b> <i>en parl. de lieux,</i> désolation, dévastation : ναοὺς δοῦναι ἐρημίᾳ, EUR. <i>Tr. 26, 95,</i> livrer des temples à la dévastation ;<br><b>      4</b> <i>en gén</i>. vide, absence <i>ou</i> privation de : φίλων, XÉN. <i>Mem. 2, 2, 14 ;</i> ἀνδρῶν, EUR. <i>Hec. 1017 ;</i> THC. <i>6, 102,</i> manque d’amis, d’hommes ; δι' ἐρημίας πολεμίων πορεύεσθαι, XÉN. <i>Hell. 3, 4, 21,</i> s’avancer sans rencontrer d’ennemis ; ἐρ. κακῶν, EUR. <i>H.f. 1157,</i> délivrance de maux.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἐρημίη, HDT. <i>l. c</i>.<br><span><b>Étym</b>. ἔρημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερημια - ἐρημία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2048":"<h1>eremos</h1>\n<p>Strong n° 2048 <i>Prononciation [er'-ay-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>solitaire, seul, désolé, inhabité\n<ol type=\"a\">\n<li>pour des lieux\n<ol>\n<li>un désert</li>\n<li>un lieu désertique, région abandonnée</li>\n<li>région non cultivée convenant au pâturage</li>\n</ol>\n</li>\n<li>pour des personnes\n<ol>\n<li>abandonné des autres</li>\n<li>privé de l'aide et de la protection des autres, en particulier d'amis, de relations</li>\n<li>délaissé\n<ol type=\"a\">\n<li>comme un troupeau abandonné du berger</li>\n<li>d'une femme négligée par son mari, que son mari refuse</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔρημος, ος, ον</b>, <i>poét</i>. <b>ἐρῆμος, η, ον :<br>   I</b> <i>abs. :</i><br><b>      1</b> désert, solitaire, <i>en parl. d’un lieu :</i> νῆσος ἐρ. OD. <i>3, 270,</i> île déserte ; χῶρος ἐρ. IL. <i>10, 520,</i> lieu désert ; λιμὴν ἔρ. THC. <i>2, 96, 98 ;</i> χώρα ἔρ. XÉN. <i>Cyr. 4, 4, 5,</i> port désert, pays désert ; ἡ ἔρημος (<i>s.-e</i>. χώρα) HDT. <i>2, 32, etc. ; ou</i> ἡ ἐρήμη, EL. <i>N.A. 7, 58 ; au plur</i>. αἱ ἔρημοι, EL. <i>N.A. 3, 26 ;</i> τὰ ἔρημα, <i>poét</i>. ἐρῆμα, IL. <i>5, 140 ;</i> HDT. <i>3, 32,</i> la solitude ; <i>adv</i>., ἔρημον ἐμϐλέπειν, AR. <i>fr. 393,</i> avoir la solitude dans les yeux, <i>càd</i>. avoir le regard vide ;<br><b>      2</b> <i>en parl. d’êtres vivants,</i> solitaire, isolé, seul, <i>en parl. de pers</i>. ESCHL. <i>Pers. 734, Ag. 862 ;</i> ἔρημος κἄφιλος, SOPH. <i>Ph. 228,</i> seul et sans amis ; <i>en parl. de malheureux, de pauvres etc</i>. AND. <i>31, 8 ; joint à</i> ἄπορος, DÉM. <i>551, 7 ; à</i> ὀρφανός, PLAT. <i>Leg. 927</i> c ; <i>en parl. d’animaux,</i> IL. <i>5, 140 ;</i> SOPH. <i>Tr. 530 ; particul. de certaines espèces d’animaux,</i> solitaire, qui ne vit pas en troupe, PLUT. <i>Cæs. 63 ; en parl. de choses (sort, condition</i>) solitaire, SOPH. <i>O.C. 1114, 1716 ;</i><br><b>   II</b> <i>avec un rég. :</i> vide de, dépourvu de, <i>gén. ; en parl. de choses :</i> χώρη ἔρ. πάντων, HDT. <i>2, 23,</i> pays dépourvu de tout ; στέγαι ἔρ. φίλων, SOPH. <i>El. 1405,</i> toit vide d’amis ; <i>en parl. de pers</i>. ἔρ. συμμάχων, HDT. <i>7, 160,</i> sans alliés ; πατρός, SOPH. <i>O.C. 1717 ;</i> PLAT. <i>Leg. 927</i> d, qui n’a plus de père ; ἔρ. πρὸς φίλων, SOPH. <i>Ant. 919,</i> sans amis ;<br><b>   III</b> ἡ ἐρήμη, <i>qqf</i>. ἡ ἔρημος <i>avec ou sans</i> δίκη, γραφή, δίαιτα, procès où l’une des parties fait défaut ; ἐρήμην κατηγορεῖν, PLAT. <i>Ap. 18</i> c, accuser par défaut ; ἐρήμην καταγιγνώσκειν, DÉM. <i>903, 9, ou</i> καταδιαιτᾶν τινος, DÉM. <i>1013, 22,</i> condamner qqn par défaut ; ἐρήμῃ δίκῃ θάνατον καταγιγνώσκειν τινός, THC. <i>6, 61,</i> condamner qqn à mort par défaut ; ἐρήμην αἱρεῖν, DÉM. <i>540, 21,</i> obtenir un jugement par défaut contre qqn ; ἔρημον διδόναι, LYS. <i>542, 4,</i> rendre un jugement par défaut ; ἔρημον ὦφλε δίκην, DÉM. <i>542, 23,</i> il fut condamné par défaut.<br><span>•<i> Cp</i>. -ότερος, THC. <i>3, 11 ;</i> LYS. <i>29, 1</i>. <i>• Sup</i>. -ότατος, HDT. <i>9, 118 ;</i> SPT. <i>Ex. 13, 20</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἐρήμη, OD. <i>3, 270 ;</i> SOPH. <i>O.C. 1719, Ant. 739, Tr. 530, et dans la loc</i>. δίκη ἐρήμη (<i>v. ci-dessus</i>).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁r(e)h₁-, séparé, rare.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερημος - ἔρημος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 47 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (8)</li>\n<li>Luc (10)</li>\n<li>Jean (5)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2049":"<h1>eremoo</h1>\n<p>Strong n° 2049 <i>Prononciation [er-ay-mo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener à la désolation, rendre désert</li>\n<li>ruiner, dévaster</li>\n<li>dépouiller une ville de ses trésors</li>\n<li>seulement forme passive : être changé en désert, être rasé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρημόω-ῶ</b> <span>(<i>impf</i>. ἠρήμουν, <i>f</i>. ἐρημώσω, <i>ao</i>. ἠρήμωσα, <i>pf. inus. ; pass. ao</i>. ἠρημώθην, <i>pf</i>. ἠρήμωμαι)</span><br><b>      1</b> rendre désert, dévaster, dépeupler (un pays, une ville, <i>etc.) acc</i>. THC. <i>3, 58 ;</i> AND. <i>26, 10 ; au pass</i>. HDT. <i>7, 171 ;</i> THC. <i>1, 23 ;</i><br><b>      2</b> priver de, <i>gén. :</i> ἀνδρῶν ἐρ. ἑστίαν, PD. <i>I. 3, 35,</i> dépeupler un foyer d’hommes ; ἐρ. ναυϐατῶν ἐρετμά, EUR. <i>Hel. 1610,</i> laisser les rames sans rameurs ; <i>au pass</i>. être dépeuplé, dépouillé <i>ou</i> privé : ἀνδρῶν, HDT. <i>1, 164 ;</i> συμμάχων, HDT. <i>7, 174,</i> être privé d’hommes, d’alliés ; <i>avec deux acc. :</i> ἐρημοῦν τινά τι, PD. <i>P. 3, 97,</i> priver qqn de qqe ch. ; <i>en b. part,</i> affranchir, délivrer : τινά <i>ou</i> τί τινος, EUR. <i>H.f. 360 ;</i> PLUT. <i>Cim. 12,</i> qqn <i>ou</i> qqe ch. (d’un fléau, d’un danger) ;<br><b>      3</b> déserter, abandonner, <i>acc</i>. PD. <i>P. 4, 479 ;</i> ESCHL. <i>Pers. 298 ;</i> EUR. <i>Andr. 314 ;</i> THC. <i>5, 4 ; d’où au pass</i>. être isolé : τοῦ ὁμίλου, HDT. <i>4, 135,</i> être séparé de la foule ; ὑπό τινος, DH. <i>11, 9,</i> être abandonné par qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao. poét</i>. ἐρήμωσα, PD. <i>I. 3, 35 ; P. 3, 97 ; pass. pl.q.pf. 3 sg. ion</i>. ἐρήμωτο, HDT. <i>6, 22</i>.<br><span><b>Étym</b>. ἔρημος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερημοω - ἐρημόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2050":"<h1>eremosis</h1>\n<p>Strong n° 2050 <i>Prononciation [er-ay'-mo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est désolé, désolation, dévastation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρήμωσις, εως (ἡ)</b> dépopulation, dévastation, ARR. <i>An. 1, 9, 13 ; d’où en gén</i>. désolation, SPT. <i>Lev. 26, 34 ; 2Par. 30, 7 ; Jer. 4, 7 ; 7, 34 ; Dan. 3, 13 ;</i> NT. <i>Matth. 24, 15 ; Marc. 13, 14 ; Luc. 21, 20 ; au plur</i>. SPT. <i>Dan. 9, 27</i>.<br><span><b>Étym</b>. ἐρημόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερημωσις - ἐρήμωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2051":"<h1>erizo</h1>\n<p>Strong n° 2051 <i>Prononciation [er-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se quereller, s'engager dans une lutte\n<ol type=\"a\">\n<li>utilisé pour décrire l'humeur calme de Jésus en contraste avec la véhémence des docteurs Juifs se disputant à propos de principes et de pratiques</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρίζω</b> <span>(<i>impf</i>. ἤριζον, <i>f</i>. ἐρίσω, <i>ao</i>. ἤρισα, <i>pf</i>. ἤρικα, <i>pf. pass</i>. ἐρήρισμαι)</span><br><b>      1</b> se quereller, être en querelle <i>ou</i> en lutte : τινί, OD. <i>18, 38 ;</i> πρός τινα, PD. <i>P. 2, 88 ;</i> HDT. <i>7, 50, 1 ;</i> avec qqn ; ἔριν ἐρίζειν, THCR. <i>Idyl. 5, 23,</i> engager une querelle, être en querelle ;<br><b>      2</b> <i>p. ext</i>. disputer, lutter, rivaliser (dans un concours, dans une lutte courtoise, <i>etc</i>.) : τινί, IL. <i>3, 223 ;</i> OD. <i>8, 371 ;</i> HDT. <i>4, 152 ;</i> πρός τινα, PLAT. <i>Rsp. 395</i> d ; THCR. <i>Idyl. 5, 136,</i> lutter contre qqn ; τι, HÉS. <i>Sc. 5 ;</i> περί τινος, IL. <i>15, 284 ;</i> OD. <i>8, 225 ;</i> XÉN. <i>Ages. 1, 5 ;</i> ἀμφί τινι, PD. <i>I. 7, 27,</i> au sujet de qqe ch. ; τινί τι, IL. <i>9, 389 ;</i> OD. <i>5, 213 ;</i> THCR. <i>Idyl. 4, 8 ;</i> τινὶ περί τινος, XÉN. <i>An. 1, 2, 8,</i> rivaliser avec qqn pour qqe ch. ; <i>ou avec le dat. de l’objet de la lutte :</i> τινὶ δρηστοσύνῃ, OD. <i>15, 321,</i> lutter d’agilité avec qqn ; <i>avec un inf</i>. OD. <i>18, 38 ; avec un relat</i>. ὅστις ἀρείων, THCR. <i>Idyl. 5, 67 ;</i> ὁπότερος γενναιότερος, PLAT. <i>Lys. 207</i> c, être en contestation pour décider lequel est le plus habile, lequel des deux est le plus généreux ;<br><b>      3</b> discuter, <i>en parl. de sophistes, p. opp. à</i> διαλέγεσθαι, PLAT. <i>Rsp. 454</i> a ; <i>cf</i>. PLAT. <i>Prot. 337</i> b ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ἐρίσομαι, <i>ao</i>. ἠρισάμην)</span> lutter, combattre : τινι, IL. <i>5, 172 ;</i> OD. <i>4, 80 ;</i> HÉS. <i>Th. 534 ;</i> PD. <i>O. 1, 95 ; I. 3, 47,</i> avec qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. dor</i>. ἐρίζοντι, PD. <i>N. 5, 39 ; inf</i>. ἐριζέμεναι, IL. <i>21, 185, ou</i> ἐριζέμεν, IL. <i>23, 404. Prés. éol</i>. ἐρίσδω, THCR. <i>Idyl. 1, 24 ; 7, 41. Impf. poét</i>. ἔριζον, IL. <i>2, 555 ; 3 sg. éol</i>. ἔρισδεν, THCR. <i>Idyl. 6, 5 ; 1 pl. éol</i>. ἐρίσδομες, THCR. <i>Idyl. 5, 67. Impf. itér</i>. ἐρίζεσκον, OD. <i>8, 225 ;</i> CRATÈS <i>4 Bgk. Fut. dor</i>. ἐρίξω, PD. <i>fr. 189 Bgk. Ao. poét</i>. ἔρισα <span>[ῑ]</span> PD. <i>I. 8, 27 ; opt. 3 sg</i>. ἐρίσσειε, IL. <i>3, 223. Moy. impf. 3 sg. poét</i>. ἐρίζετο, HÉS. <i>Th. 534. Fut. épq</i>. ἐρίσσομαι, <i>d’où ao. sbj. épq. 3 sg</i>. ἐρίσσεται (<i>p</i>. -ηται) OD. <i>4, 80</i>.<br><span><b>Étym</b>. ἔρις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εριζω - ἐρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2052":"<h1>eritheia</h1>\n<p>Strong n° 2052 <i>Prononciation [er-ith-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire une campagne électorale ou intriguer pour une fonction\n<ol type=\"a\">\n<li>esprit partisan, querelleur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐριθεία, ας (ἡ)</b> <span>[ῑ]</span> lutte, <i>d’où</i> brigue, ARSTT. <i>Pol. 5, 2, 3 ; au plur. ib. 5, 3, 9</i>.<br><span><b>Étym</b>. ἐριθεύομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εριθεια - ἐριθεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (2)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G2053":"<h1>erion</h1>\n<p>Strong n° 2053 <i>Prononciation [er'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>laine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔριον</b>, <i>ion. et épq</i>. <b>εἴριον, ου (τὸ) :<br>   I</b> laine, IL. <i>12, 434 ;</i> OD. <i>4, 124 ;</i> PLAT. <i>Conv. 175</i> d, <i>Rsp. 398</i> a ; <i>au plur</i>. IL. <i>3, 388 ;</i> OD. <i>18, 316 ;</i> AR. <i>Ran. 1067, etc. ;</i><br><b>   II</b> <i>p. ext. ou p. anal. :</i><br><b>      1</b> εἴρια ἀπὸ ξύλων, HDT. <i>3, 47, etc. ;</i> TH. <i>H.P. 4, 7, 7,</i> laine de cotonnier, coton ;<br><b>      2</b> ἔρ. τῆς θαλάττης, ALCIPHR. <i>1, 2,</i> sorte de filaments laineux d’un coquillage ;<br><b>      3</b> ἔρ. τῆς ἀράχνης, PHILSTR. <i>853,</i> fil <i>ou</i> toile d’araignée.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. εἴριον, HOM. <i>ll. cc. (par except. gén</i>. ἐρίοιο, OD. <i>4, 124</i>) ; HDT. <i>l. c</i>.<br><span><b>Étym</b>. <i>voir</i> εἶρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εριον - ἔριον</font>\n<br><br>affinité obscure</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2054":"<h1>eris</h1>\n<p>Strong n° 2054 <i>Prononciation [er'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lutte, dispute, querelle, contentieux, rivalité, noise</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔρις, ιδος (ἡ) :<br>      1</b> querelle à main armée, lutte, combat, IL. <i>1, 177 ; 3, 7 ; 5, 891, etc. ; avec un gén</i>. ἔρις πτολέμοιο, IL. <i>14, 389, ou</i> ἔρις μάχης, XÉN. <i>Cyr. 2, 3, 15,</i> querelle que l’on vide par un combat ; ἔριδα ξυνάγειν Ἄρηος, IL. <i>5, 861,</i> engager un combat ; ἔριδι μάχεσθαι, IL. <i>1, 8 ; ou</i> ἐξ ἔριδος μάχεσθαι, IL. <i>7, 111,</i> combattre par suite d’une querelle ;<br><b>      2</b> querelle, discorde, contestation : ἔριν συμϐάλλειν τινί, EUR. <i>Med. 521,</i> engager une querelle avec qqn ; εἰς ἔριν ἐμπίπτειν, EUR. <i>I.A. 377, ou</i> ἀφικνεῖσθαι, EUR. <i>I.A. 319, ou</i> ἐλθεῖν, AR. <i>Ran. 877,</i> tomber en querelle, en arriver à se quereller ; ἐς ἔριν ἐλθεῖν τινι, HDT. <i>9, 33 ;</i> δι' ἐρίδων εἶναί τινι, PLUT. <i>Cæs. 33,</i> en arriver à se quereller avec qqn ; ἔριν τιθέναι, EUR. <i>Hel. 100 ;</i> στρέφειν, PD. <i>N. 4, 93,</i> engager une querelle ; συμϐάλλειν εἰς ἔριν περί τινος, XÉN. <i>Lac. 4, 2, ou</i> δι' ἐρίδων γίγνεσθαι, PLAT. <i>Tim. 88</i> a, engager une querelle <i>ou</i> une contestation au sujet de qqe ch. ; γίγνεται ἔρις τινὶ πρός τινα, THC. <i>6, 31,</i> une querelle naît d’une personne à une autre ; κατ' ἔριν, PLAT. <i>Criti. 109,</i> en querelle ; ἔριν ἔχειν, PLAT. <i>Leg. 736</i> c, avoir une contestation ; ἐν πολλῇ ἔριδι εἶναι, THC. <i>2, 21,</i> être engagé dans une forte querelle ; ἐν πολλῇ πρὸς ἀλλήλους ἔριδι εἶναι, THC. <i>6, 35,</i> être engagés les uns avec les autres dans une forte querelle ; <i>avec</i> εἴτε : ἦν πολλὴ ἔρις καὶ ἄγνοια, εἴτε… εἴτε, THC. <i>3, 11,</i> il y avait une forte contestation pour savoir si… ou si, <i>etc. ; cf</i>. ANTH. <i>7, 18 ;</i><br><b>      3</b> <i>p. ext</i>. rivalité, <i>en gén. :</i> τινός, OD. <i>8, 210, etc. ;</i> ἀμφί τινι, HDT. <i>6, 129,</i> au sujet de qqe ch. : κατ' ἔριν τινός, HDT. <i>5, 88,</i> en rivalité avec qqn ; ἔριδος ἕνεκα, PLAT. <i>Soph. 237</i> b, par rivalité ; ἔριν ἐμϐάλλειν τισὶ πρὸς ἀλλήλους, XÉN. <i>Cyr. 6, 2, 4, etc</i>. provoquer la rivalité de plusieurs personnes les unes contre les autres ; Διὸς βρονταῖσιν εἰς ἔριν κτυπεῖν, EUR. <i>Cycl. 328,</i> faire un grand bruit, de façon à lutter avec le tonnerre de Zeus ; <i>en b. part,</i> émulation : τινὰς εἰς ἔριν συμϐάλλειν περί τινος, XÉN. <i>Lac. 4, 2,</i> exciter l’émulation de qqes personnes pour qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Acc. att</i>. ἔριν, <i>aussi dans</i> OD. <i>3, 136, 161 ; 16, 292 ; 19, 11 ; d’ord. acc. épq</i>. ἔριδα, IL. <i>5, 861 ; 20, 55 ;</i> OD. <i>6, 92 ; 8, 210, etc. ; plur. nom</i>. ἔρεις, NT. <i>2Cor. 12, 20 ; Gal. 5, 20 ; 1Tim. 6, 4 ; Tit. 3, 9</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερις - ἔρις</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 7 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2055":"<h1>eriphion</h1>\n<p>Strong n° 2055 <i>Prononciation [er-if'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un chevreau, un jeune bouc (littéralement petit bouc)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρίφιον, ου (τὸ)</b> <span>[ρῐ]</span>, petit chevreau, ATHÉNION (ATH. <i>661</i> b) ; GAL. <i>7, 327 ;</i> NT. <i>Matth. 25, 33</i>.<br><span><b>Étym</b>. <i>dim. de</i> ἔριφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εριφιον - ἐρίφιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2056":"<h1>eriphos</h1>\n<p>Strong n° 2056 <i>Prononciation [er'-if-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un chevreau, un jeune bouc</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔριφος, ου (ὁ)</b> <span>[ῐ]</span> chevreau, jeune bouc, IL. <i>5, 392, etc. ;</i> OD. <i>9, 226 ;</i> HÉS. <i>O. 541, etc. ;</i> οἱ ἔριφοι, THCR. <i>Idyl. 7, 53 ;</i> ARAT. <i>158,</i> les Chevreaux, <i>constellation qui annonçait le mauvais temps à son lever en octobre ; dans la constellation actuelle du Cocher, avec son étoile principale</i> « la Chèvre ».<br><span><b><span class=\"arrow\"></span></b> <i>Par crase</i> ὥριφος = ὁ ἔριφος, THCR. <i>Idyl. 5, 24, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εριφος - ἔριφος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2057":"<h1>Hermas</h1>\n<p>Strong n° 2057 <i>Prononciation [her-mas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hermès (Angl. Hermas) = « Mercure »\n<ol><li>Chrétien mentionné en <a class=\"ref\" data-r=\"ROM16.14\">Romains 16.14</a>. Selon la tradition, il fut l'un des soixante-dix disciples, et ensuite évêque de Dalmatie. (en 55)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἑρμᾶς</b>, <i>v</i>. Ἑρμῆς.<br><br>\n<b>Ἑρμῆς, οῦ (ὁ) :<br>      1</b> Hermès, <i>fils de Zeus et de Mæa, messager des dieux : p. suite, dieu des relations pacifiques et des rapports sociaux entre les hommes, protecteur du commerce et des voyages sur terre et sur mer ; comme interprète des ordres divins, dieu de la parole et de l’éloquence, chargé de conduire les âmes aux enfers ; comme dieu voyageur et coureur infatigable, dieu des éphèbes, présidant aux luttes et aux concours gymniques ; selon les mythologues, dieu personnifiant le double crépuscule du soir et du matin, entraîné dans une course continuelle, disparaissant chaque soir à l’occident pour reparaître chaque matin à l’orient ; dès lors conçu comme un dieu voyageur, protecteur des routes ; par suite, comme un dieu bienfaisant qui procure le gain et préserve du mal ; personnification du crépuscule qui devance l’aurore, il annonce Zeus, le dieu du jour, dont il est le héraut et le message ; de même, il est le précurseur des divinités de la nuit ; comme tel, considéré comme dieu des enfers, il y conduit les âmes et parfois les en ramène,</i> IL. <i>5, 390, etc. ;</i> OD. <i>5, 28, etc. (v. ci-dessous) ; prov</i>. <span>Ἑρμῆν ἕλκειν</span>, STRATT. (ATH. <i>32</i> b, <i>473</i> c) vider la dernière coupe du souper, en l’honneur d’Hermès, <i>en parl. de convives qui se lèvent de table après le repas du soir, parce qu’Hermès présidait au sommeil ;</i> κοινὸς Ἑρμῆς, ARSTT. <i>Rhet. 2, 24, 2 ;</i> TH. <i>Char. 30, etc</i>. part à deux ! <i>en parl. d’une trouvaille à partager ;</i> ὁ Ἑρμῆς ἐπεισῆλθε, PLUT. <i>M. 502</i> f, voilà Hermès arrivé, <i>pour dire qu’une conversation cesse tout à coup ;</i><br><b>      2</b> hermès, <i>buste ou tête d’Hermès posée sur une petite colonne dans les rues, sur les places, etc., soit parce qu’Hermès était le dieu des voyageurs et le protecteur des chemins, soit plutôt (et par l’intermédiaire des diminutifs</i> ἑρμάδιον <i>ou</i> ἑρμίδιον) <i>par suite d’une confusion d’idées avec les mots</i> ἕρμα « borne » <i>ou</i> « poteau », <i>ou</i> ἕρμαι « tas de pierres » <i>qui marquaient les bifurcations de chemins ou la limite des propriétés ; d’où au pl</i>. ἑρμαῖ, des hermès, THC. <i>6, 27 et 53 ;</i> AND. <i>6, 7 etc. ;</i><br><b>      3</b> Mercure, <i>planète,</i> ARSTT. <i>Meteor. 1, 6 ;</i> TH. <i>Sign. 3, 9 ;</i> CLÉOM. <i>13, 29 ;</i> A. TAT. ASTR. <i>Isag. in Arat. 956</i> a <i>Migne ;</i><br><b>      4</b> Ἑρμοῦ ἡμέρα, DC. <i>37, 18 ;</i> CLÉM. <i>2, 504 Migne,</i> le jour de Mercure = <i>lat</i>. Mercurii dies (<i>franç</i>. mercredi).<br><span><b><span class=\"arrow\"></span></b> Ἑρμῆς, <i>contraction de</i> Ἑρμέας ; <i>les différentes formes de ce nom peuvent se répartir comme il suit :</i><br><b>A</b> <i>Formes non contractes :</i><br><b>   I</b> Ἑρμέας, <i>d’où :</i><br><b>      1</b> Ἑρμέας, <i>épq. et ion. ; gén</i>. Ἑρμέω, HH. <i>Merc. 413 (dissyll</i>.) ; HH. <i>Ven. 148 (dissyll</i>.) ; HDT. <i>2, 51 ; 5, 7 ;</i> LUC. <i>Astr. 20 ;</i> THCR. <i>Idyl. 25, 4, etc. ; dat</i>. Ἑρμέᾳ, IL. <i>5, 390 (dissyll</i>.) ;<br><b>      2</b> <i>ion</i>. Ἑρμέης, <i>d’où acc</i>. Ἑρμέην, HDT. <i>5, 7 ;</i><br><b>   II</b> <i>par développ. de</i> Ἑρμέας, <i>la forme</i> Ἑρμείας, <i>d’où :</i><br><b>      1</b> Ἑρμείας, IL. <i>2, 104 ; 24, 694 ;</i> OD. <i>8, 323 ; 24, 10 ;</i> A. RH. <i>2, 1147 ; 4, 1135 ;</i> ANTH. <i>9, 72, etc. Voc</i>. Ἑρμεία <span>[ᾱ]</span> IL. <i>24, 334 ;</i> OD. <i>5, 29, etc. ;</i> ORPH. <i>H. 28, 1 ;</i> ANTH. <i>6, 23, etc. Gén. épq</i>. Ἑρμείαο, OD. <i>12, 390 ; 15, 319 ;</i> HH. <i>Pan 19, 1 ;</i> A. RH. <i>1, 51, etc. ;</i> THCR. <i>Idyl. 24, 114, etc. ; rar</i>. Ἑρμεία <span>[ᾱ]</span> ANTH. <i>7, 480 ; att</i>. Ἑρμείου, PLAT. <i>Ep. 322</i> d ; THCR. <i>Epigr. app. 38, etc. Dat</i>. Ἑρμείᾳ, ANTH. <i>6, 294 ; 10, 12 ;</i> ATH. <i>697</i> a. <i>Acc</i>. Ἑρμείαν, IL. <i>24, 333, 679, etc. ;</i> OD. <i>1, 38 ; 5, 28 ;</i> HÉS. <i>O. 68 ;</i> LUC. <i>Philopatr. 7, etc. ;</i><br><b>      2</b> <i>ion</i>. Ἑρμείης, MOSCH. <i>2, 56 ;</i> CALL. <i>H. 3, 69 et 143. Voc</i>. Ἑρμείη, ANTH. <i>6, 68. Gén</i>. Ἑρμείω (<i>p</i>. *Ἑρμείεω) IL. <i>15, 214. Dat</i>. Ἑρμείῃ, CALL. <i>H. 4, 272 ;</i> ANTH. <i>6, 29, etc. Acc</i>. Ἑρμείην, BABR. <i>30, 127 ;</i> ANTH. <i>10, 12, etc. ;</i><br><b>B</b> <i>Formes contractes :</i><br><b>      1</b> Ἑρμῆς, <i>voc</i>. Ἑρμῆ, ESCHL. <i>Pers. 629. Gén</i>. Ἑρμοῦ. <i>Dat</i>. Ἑρμῇ, OD. <i>14, 435 ; postér</i>. Ἑρμεῖ, PLUT. <i>Qu. conv. 9, 3, 2 ; poét</i>. Ἑρμηῖ, ANTH. <i>12, 143. Acc</i>. Ἑρμῆν. <i>Plur</i>. Ἑρμαῖ, <i>etc. (v. ci-dessus</i>) ;<br><b>      2</b> <i>dor</i>. Ἑρμᾶς, PD. <i>P. 2, 18 ; I. 1, 85 ; 4, 316 ;</i> EUR. <i>Hel. 670 ; I.A. 1302 ;</i> LUC. <i>Nav. 12. Gén</i>. Ἑρμᾶ, PD. <i>O. 8, 106 ;</i> ESCHL. <i>fr. 401 ;</i> AR. <i>Ach. 816 ;</i> T. LOCR. <i>96</i> e. <i>Dat</i>. Ἑρμᾷ, PD. <i>N. 10, 98 ;</i> EUR. <i>El. 462, etc. Acc</i>. Ἑρμᾶν, PD. <i>O. 6, 132 ;</i> ESCHL. <i>fr. 258 ;</i> AR. <i>Ach. 708, etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ερμας - Ἑρμᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2058":"<h1>hermeneia</h1>\n<p>Strong n° 2058 <i>Prononciation [her-may-ni'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>interprétation, traduction\n<ol type=\"a\">\n<li>de ce qui est dit plus ou moins clairement par les autres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑρμηνεία, ας (ἡ) :<br>   I</b> expression d’une pensée, <i>d’où</i> élocution, faculté de s’exprimer, XÉN. <i>Mem. 4, 3, 12 ;</i> ARSTT. <i>P.A. 3, 17, 5 ; au plur</i>. Πλατωνικαὶ ἑρμ. DH. <i>Pomp. 1, 2,</i> manières de parler propres à Platon ;<br><b>   II</b> interprétation d’une pensée, <i>d’où :</i><br><b>      1</b> éclaircissement, explication, PLAT. <i>Rsp. 524</i> b, <i>Theæt. 209</i> a ;<br><b>      2</b> interprétation, traduction, PHIL. <i>2, 141 ;</i> JOS. <i>A.J. 12, 2, 4</i>.<br><span><b>Étym</b>. ἑρμηνεύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερμηνια - ἑρμηνεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2059":"<h1>hermeneuo</h1>\n<p>Strong n° 2059 <i>Prononciation [her-mayn-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>expliquer par des mots, exposer</li>\n<li>interpréter\n<ol type=\"a\">\n<li>traduire ce qui a été dit ou écrit dans une langue étrangère</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑρμηνεύω</b> <span>(<i>impf</i>. ἡρμήνευον, <i>ao</i>. ἡρμήνευσα)</span><br><b>      1</b> exprimer sa pensée par la parole, THC. <i>2, 60 ;</i> PLAT. <i>Leg. 966</i> b ; DH. <i>Thuc. 42 ;</i><br><b>      2</b> <i>p. suite,</i> faire connaître, indiquer, exposer (qqe ch.) SOPH. <i>O.C. 398 ;</i> EUR. <i>fr. 637 ;</i> PLAT. <i>Ion 535</i> a ;<br><b>      3</b> interpréter, traduire, XÉN. <i>An. 5, 4, 4 ;</i> SPT. <i>Job 42, 18 ; 2Esdr. 4, 7 ;</i> DH. <i>6, 938, 12 Reiske etc. ;</i><br><b><i>Moy.</i></b> se communiquer (qqe ch.) PLAT. <i>Epin. 985</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερμηνευω - ἑρμηνεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2060":"<h1>Hermes</h1>\n<p>Strong n° 2060 <i>Prononciation [her-mace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Mercure ou Hermas (Hermès) (Mercurius, Hermes) = « héraut des dieux »\n<ol>\n<li>divinité grecque appelée Mercure par les Romains</li>\n<li>un certain Chrétien</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἑρμῆς, οῦ (ὁ) :<br>      1</b> Hermès, <i>fils de Zeus et de Mæa, messager des dieux : p. suite, dieu des relations pacifiques et des rapports sociaux entre les hommes, protecteur du commerce et des voyages sur terre et sur mer ; comme interprète des ordres divins, dieu de la parole et de l’éloquence, chargé de conduire les âmes aux enfers ; comme dieu voyageur et coureur infatigable, dieu des éphèbes, présidant aux luttes et aux concours gymniques ; selon les mythologues, dieu personnifiant le double crépuscule du soir et du matin, entraîné dans une course continuelle, disparaissant chaque soir à l’occident pour reparaître chaque matin à l’orient ; dès lors conçu comme un dieu voyageur, protecteur des routes ; par suite, comme un dieu bienfaisant qui procure le gain et préserve du mal ; personnification du crépuscule qui devance l’aurore, il annonce Zeus, le dieu du jour, dont il est le héraut et le message ; de même, il est le précurseur des divinités de la nuit ; comme tel, considéré comme dieu des enfers, il y conduit les âmes et parfois les en ramène,</i> IL. <i>5, 390, etc. ;</i> OD. <i>5, 28, etc. (v. ci-dessous) ; prov</i>. <span>Ἑρμῆν ἕλκειν</span>, STRATT. (ATH. <i>32</i> b, <i>473</i> c) vider la dernière coupe du souper, en l’honneur d’Hermès, <i>en parl. de convives qui se lèvent de table après le repas du soir, parce qu’Hermès présidait au sommeil ;</i> κοινὸς Ἑρμῆς, ARSTT. <i>Rhet. 2, 24, 2 ;</i> TH. <i>Char. 30, etc</i>. part à deux ! <i>en parl. d’une trouvaille à partager ;</i> ὁ Ἑρμῆς ἐπεισῆλθε, PLUT. <i>M. 502</i> f, voilà Hermès arrivé, <i>pour dire qu’une conversation cesse tout à coup ;</i><br><b>      2</b> hermès, <i>buste ou tête d’Hermès posée sur une petite colonne dans les rues, sur les places, etc., soit parce qu’Hermès était le dieu des voyageurs et le protecteur des chemins, soit plutôt (et par l’intermédiaire des diminutifs</i> ἑρμάδιον <i>ou</i> ἑρμίδιον) <i>par suite d’une confusion d’idées avec les mots</i> ἕρμα « borne » <i>ou</i> « poteau », <i>ou</i> ἕρμαι « tas de pierres » <i>qui marquaient les bifurcations de chemins ou la limite des propriétés ; d’où au pl</i>. ἑρμαῖ, des hermès, THC. <i>6, 27 et 53 ;</i> AND. <i>6, 7 etc. ;</i><br><b>      3</b> Mercure, <i>planète,</i> ARSTT. <i>Meteor. 1, 6 ;</i> TH. <i>Sign. 3, 9 ;</i> CLÉOM. <i>13, 29 ;</i> A. TAT. ASTR. <i>Isag. in Arat. 956</i> a <i>Migne ;</i><br><b>      4</b> Ἑρμοῦ ἡμέρα, DC. <i>37, 18 ;</i> CLÉM. <i>2, 504 Migne,</i> le jour de Mercure = <i>lat</i>. Mercurii dies (<i>franç</i>. mercredi).<br><span><b><span class=\"arrow\"></span></b> Ἑρμῆς, <i>contraction de</i> Ἑρμέας ; <i>les différentes formes de ce nom peuvent se répartir comme il suit :</i><br><b>A</b> <i>Formes non contractes :</i><br><b>   I</b> Ἑρμέας, <i>d’où :</i><br><b>      1</b> Ἑρμέας, <i>épq. et ion. ; gén</i>. Ἑρμέω, HH. <i>Merc. 413 (dissyll</i>.) ; HH. <i>Ven. 148 (dissyll</i>.) ; HDT. <i>2, 51 ; 5, 7 ;</i> LUC. <i>Astr. 20 ;</i> THCR. <i>Idyl. 25, 4, etc. ; dat</i>. Ἑρμέᾳ, IL. <i>5, 390 (dissyll</i>.) ;<br><b>      2</b> <i>ion</i>. Ἑρμέης, <i>d’où acc</i>. Ἑρμέην, HDT. <i>5, 7 ;</i><br><b>   II</b> <i>par développ. de</i> Ἑρμέας, <i>la forme</i> Ἑρμείας, <i>d’où :</i><br><b>      1</b> Ἑρμείας, IL. <i>2, 104 ; 24, 694 ;</i> OD. <i>8, 323 ; 24, 10 ;</i> A. RH. <i>2, 1147 ; 4, 1135 ;</i> ANTH. <i>9, 72, etc. Voc</i>. Ἑρμεία <span>[ᾱ]</span> IL. <i>24, 334 ;</i> OD. <i>5, 29, etc. ;</i> ORPH. <i>H. 28, 1 ;</i> ANTH. <i>6, 23, etc. Gén. épq</i>. Ἑρμείαο, OD. <i>12, 390 ; 15, 319 ;</i> HH. <i>Pan 19, 1 ;</i> A. RH. <i>1, 51, etc. ;</i> THCR. <i>Idyl. 24, 114, etc. ; rar</i>. Ἑρμεία <span>[ᾱ]</span> ANTH. <i>7, 480 ; att</i>. Ἑρμείου, PLAT. <i>Ep. 322</i> d ; THCR. <i>Epigr. app. 38, etc. Dat</i>. Ἑρμείᾳ, ANTH. <i>6, 294 ; 10, 12 ;</i> ATH. <i>697</i> a. <i>Acc</i>. Ἑρμείαν, IL. <i>24, 333, 679, etc. ;</i> OD. <i>1, 38 ; 5, 28 ;</i> HÉS. <i>O. 68 ;</i> LUC. <i>Philopatr. 7, etc. ;</i><br><b>      2</b> <i>ion</i>. Ἑρμείης, MOSCH. <i>2, 56 ;</i> CALL. <i>H. 3, 69 et 143. Voc</i>. Ἑρμείη, ANTH. <i>6, 68. Gén</i>. Ἑρμείω (<i>p</i>. *Ἑρμείεω) IL. <i>15, 214. Dat</i>. Ἑρμείῃ, CALL. <i>H. 4, 272 ;</i> ANTH. <i>6, 29, etc. Acc</i>. Ἑρμείην, BABR. <i>30, 127 ;</i> ANTH. <i>10, 12, etc. ;</i><br><b>B</b> <i>Formes contractes :</i><br><b>      1</b> Ἑρμῆς, <i>voc</i>. Ἑρμῆ, ESCHL. <i>Pers. 629. Gén</i>. Ἑρμοῦ. <i>Dat</i>. Ἑρμῇ, OD. <i>14, 435 ; postér</i>. Ἑρμεῖ, PLUT. <i>Qu. conv. 9, 3, 2 ; poét</i>. Ἑρμηῖ, ANTH. <i>12, 143. Acc</i>. Ἑρμῆν. <i>Plur</i>. Ἑρμαῖ, <i>etc. (v. ci-dessus</i>) ;<br><b>      2</b> <i>dor</i>. Ἑρμᾶς, PD. <i>P. 2, 18 ; I. 1, 85 ; 4, 316 ;</i> EUR. <i>Hel. 670 ; I.A. 1302 ;</i> LUC. <i>Nav. 12. Gén</i>. Ἑρμᾶ, PD. <i>O. 8, 106 ;</i> ESCHL. <i>fr. 401 ;</i> AR. <i>Ach. 816 ;</i> T. LOCR. <i>96</i> e. <i>Dat</i>. Ἑρμᾷ, PD. <i>N. 10, 98 ;</i> EUR. <i>El. 462, etc. Acc</i>. Ἑρμᾶν, PD. <i>O. 6, 132 ;</i> ESCHL. <i>fr. 258 ;</i> AR. <i>Ach. 708, etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ερμης - Ἑρμῆς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2061":"<h1>Hermogenes</h1>\n<p>Strong n° 2061 <i>Prononciation [her-mog-en'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Hermogène (Angl. Hermogenes) = « naissance heureuse » ou « né de Mercure »\n<ol><li>un certain Chrétien d'Asie, mentionné dans <a class=\"ref\" data-r=\"2TI1.15\">2 Timothée 1.15</a></li></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ἑρμο·γένης, ους (ὁ)</b> Hermogénès (Hermogène) :<br><b>      1</b> <i>n. de divers personnages,</i> XÉN. <i>Conv. 3, 14 ; Mem. 2, 10, 3 ; Hell. 4, 8, 13 ;</i> PLAT. <i>Phæd. 59</i> b ;<br><b>      2</b> <i>n. d’un rhéteur célèbre,</i> PHILSTR. <i>V. soph. 2, 7</i>.<br><span><b>Étym</b>. Ἑ. γένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ερμογενης - Ἑρμογένης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2062":"<h1>herpeton</h1>\n<p>Strong n° 2062 <i>Prononciation [her-pet-on']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un animal rampant, reptile\n<ol type=\"a\">\n<li>utilisé surtout pour les serpents</li>\n</ol>\n</li>\n<li>un animal quelconque\n<ol type=\"a\">\n<li>animaux à quatre pattes et oiseaux</li>\n<li>animaux marins</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑρπετόν, οῦ (τὸ) :<br>   I</b> tout ce qui rampe <i>ou</i> se traîne, bête, animal, <i>p. opp. à l’homme,</i> OD. <i>4, 418 ;</i> XÉN. <i>Mem. 1, 4, 11 ; ou p. opp. aux oiseaux</i> (πετεινά) HDT. <i>1, 148 ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> reptile, serpent, EUR. <i>Andr. 269 ;</i> AR. <i>Av. 1069 ;</i> THCR. <i>Idyl. 24, 56 ;</i><br><b>      2</b> insecte, SIM. AM. <i>fr. 13,</i> NIC. <i>fr. 2, 46</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. ὄρπετον, THCR. <i>Idyl. 29, 13</i>.<br><span><b>Étym</b>. ἕρπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερπετον - ἑρπετόν</font>\n<br><br>mot dérivé de 'herpo' (ramper)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2063":"<h1>eruthros</h1>\n<p>Strong n° 2063 <i>Prononciation [er-oo-thros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la mer Rouge\n<ol type=\"a\">\n<li>l'océan Indien baigne les côtes de l'Arabie avec ses deux golfes dont l'un, à l'est qui est appelé Golfe Persique, l'autre, à l'ouest, la Mer Rouge. Dans le N.T., le mot s'applique à la partie supérieure de la Mer Rouge, c'est à dire le Golfe de Suez, par où sont passés les Israélites pour aller d'Egypte aux côtes d'Arabie.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρυθρός, ά, όν</b> <span>[ῠ]</span><br><b>   I</b> rouge (nectar, vin, cuivre, sang, <i>etc</i>.) IL. <i>19, 38, etc. ;</i> OD. <i>5, 93, etc. ;</i> ESCHL. <i>Eum. 265 ;</i> HDT. <i>3, 57, etc. ; subst</i>. τὰ ἐρυθρά, pustules, HPC. <i>Coac. 147, etc. ou</i> menstrues, HPC. <i>1128</i> g ;<br><b>   II</b> ἡ Ἐρυθρὰ θάλασσα, <i>etc. ;</i> Ἐρυθρὴ θάλασσα, HDT. <i>1, 180, 202 ; 2, 8, etc. ;</i> Ἐρυθρὸς πόντος, PD. <i>P. 4, 448,</i> la mer Rouge, <i>càd. :</i><br><b>      1</b> l’Océan indien <i>(non seulement la mer Rouge, mais en outre la partie de l’Océan de l’Afrique à l’Hindoustan) ; et, p. ext. le littoral, d’où</i> toute la région voisine de la mer Rouge, POL. <i>5, 46, 7 ;</i><br><b>      2</b> <i>postér</i>. le golfe Persique, XÉN. <i>Cyr. 8, 6, 10 ;</i> DS. <i>2, 11</i>.<br><span>•<i> Cp. (malgré l’ῠ)</i> -ότερος, XÉN. <i>Œc. 10, 2 ;</i> PLAT. <i>Tim. 83</i> b (<i>var</i>. -ώτερος) ; DROM. (ATH. <i>240</i> d). <i>• Sup</i>. -ότατος, PLAT. <i>Epin. 987</i> c (<i>var</i>. -ώτατος).<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> AR. <i>Av. 145, Eq. 1088, Ach. 787, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *h₁reud<sup>h</sup>-, rouge ; <i>cf. lat</i>. rŭber, rūfus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερυθρος - ἐρυθρός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2064":"<h1>erchomai</h1>\n<p>Strong n° 2064 <i>Prononciation [er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir\n<ol type=\"a\">\n<li>de personnes\n<ol>\n<li>arriver d'un lieu vers un autre, utilisé aussi pour les arrivants</li>\n<li>apparaître, venir devant le public</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>arriver dans la vie, s'élever, se montrer, avoir une place ou de l'influence</li>\n<li>être établi, devenir connu, venir (tomber) dans ou sur</li>\n</ol>\n</li>\n<li>aller, suivre quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔρχομαι</b> <span>(<i>f</i>. ἐλεύσομαι, <i>att</i>. εἶμι, <i>ao.2</i> ἦλθον, <i>pf</i>. ἐλήλυθα <span>[ῠ]</span>)</span><br><b>A<br>   I</b> venir : δεῦρο ἐλθόντες, PLAT. <i>Phædr. 250</i> d, étant venus ici ; ἐπείπερ ἐνταῦθα ἐληλύθαμεν, PLAT. <i>Rsp. 445</i> b, puisque nous en sommes arrivés là ; πεζὸς εἰλήλουθα, IL. <i>5, 204,</i> je suis venu par terre (à Ilion) ; ἀποροῦντι αὐτῷ ἔρχεται Προμηθεύς, PLAT. <i>Prot. 321</i> c, comme il était dans l’embarras, Prométhée vient à son secours, <i>etc. ;</i><br><b>   II</b> <i>p. ext</i>. aller, <i>en gén. :</i> ἔρχεσθαι πεδίοιο, IL. <i>2, 801,</i> aller à travers la plaine ; ὀδύνη διὰ χροὸς ἦλθε, IL. <i>11, 398,</i> une douleur traversa ses membres (<i>litt</i>. sa peau), περὶ δέ σφεας ἤλυθ' ἰωή, OD. <i>17, 261,</i> et le son (de la lyre) vint jusqu’à eux (<i>litt</i>. autour d’eux) ; <i>avec un part</i>. ἔρχομαι ἐρέων, HDT. <i>1, 5,</i> je vais dire, <i>etc. ;</i><br><b>   III</b> s’en aller : οἴκαδ' ἔρχ. AR. <i>Vesp. 1322,</i> s’en retourner chez soi ; στεῖχε· τοῦτο δ' ἴσθ' ὅτι ἄνους μὲν ἔρχει, SOPH. <i>Ant. 99,</i> va, mais sache que tu pars insensée ; ἐλθὼν κόρην ἄνες, SOPH. <i>Ant. 1100,</i> va et relâche la jeune fille ; δρᾶ νυν τάδ' ἐλθών, SOPH. <i>Ant. 1107,</i> eh bien donc, va et fais-le ; γέρας ἔρχεται ἄλλῃ, IL. <i>1, 120,</i> la récompense s’en va d’un autre côté (je perds la captive qui était ma récompense) ; <i>cf</i>. SOPH. <i>Ph. 48, 1181, etc. ;</i><br><b>B</b> <i>Construction. Quelle que soit sa signif</i>. ἔρχομαι <i>peut se construire :</i><br><b>   I</b> <i>avec un suj. de pers. ou d’êtres animés :</i><br><b>      1</b> <i>au propre : avec un acc. de but : acc</i>. Ἀΐδαο δόμους ἔρχ. IL. <i>22, 483,</i> aller dans la demeure d’Hadès ; ἔρχεσθον κλισίην, IL. <i>1, 322,</i> allez tous deux à la tente (d’Achille) ; νᾶσον ἔρχ. PD. <i>P. 4, 52,</i> venir dans une île ; ἔρχ. δόμους, SOPH. <i>El. 64 ;</i> οἶκον, OD. <i>19, 313,</i> venir dans une maison ; πόλιν, SOPH. <i>Tr. 259,</i> arriver dans une ville ; <i>avec un acc. de pers</i>. ἐλθεῖν τινα, PD. <i>I. 2, 48,</i> venir auprès de qqn ; — <i>acc. de direction :</i> ὁδὸν ἐλθέμεναι, IL. <i>1, 151, ou</i> ἐλθεῖν, PLAT. <i>Prot. 317</i> b, faire un trajet ; ἐλθ' αὐτὰ κέλευθα, IL. <i>12, 225,</i> être venu par les mêmes chemins ; ἄλλην ὁδόν, ἄλλα κέλευθα ἐλθ. OD. <i>9, 262,</i> être venu par une autre route, par d’autres chemins ; — <i>acc. de cause :</i> ἀγγελίην ἐλθεῖν, IL. <i>11, 140 ; 24, 235 ;</i> ἐξεσίην ἐλθεῖν, OD. <i>21, 20,</i> être venu en ambassade ; — <i>acc. d’instrument :</i> νόστιμον πόδα ἐλθεῖν, EUR. <i>Alc. 1153,</i> avoir fait le trajet pour revenir (dans sa patrie) ; — <i>avec un gén. : gén. du lieu par lequel on passe :</i> ἐλθ. πεδίοιο (<i>v. ci-dessus</i> A, II) ; <i>gén. du lieu d’où l’on vient :</i> ἐλθ. γῆς τινος, SOPH. <i>O.C. 572,</i> être venu d’un pays ; — <i>avec un dat. : dat. de pers. au sens de</i> venir en aide à, venir assister : τινι, qqn, OD. <i>16, 453 ;</i> ESCHL. <i>Pr. 663 ;</i> THC. <i>1, 13, etc. (cf. ci-dessus,</i> A, I) ; — <i>dat. d’instrument :</i> πόδεσσιν ἔρχεσθαι, OD. <i>6, 40,</i> venir de son pied ; — <i>avec une prép. suivie d’un n. de pers</i>. ἔρχεσθαι πρός τινα, SOPH. <i>Ant. 868,</i> venir auprès de qqn ; παρά τινα, PD. <i>O. 1, 111 ; N. 10, 49 ;</i> ESCHL. <i>Ag. 180 ;</i> THC. <i>1, 40 ; 5, 56, m. sign. ;</i> ἐπί τινα, ESCHL. <i>Pr. 864 ;</i> THC. <i>5, 4, m. sign. ;</i> ἐς θεόν, PD. <i>O. 7, 31 ;</i> ἐς θεούς, EUR. <i>El. 312,</i> venir dans le temple d’un dieu, dans les temples des dieux ; ἐς τοὺς Βοιωτούς, THC. <i>5, 32 et 39,</i> venir chez les Béotiens ; ὡς τοὺς Ἀθηναίους, THC. <i>1, 31 ; 2, 73 ; 5, 4,</i> venir chez les Athéniens ; ἀπό τινος, PLAT. <i>Prot. 309</i> b, venir de chez qqn ; <i>particul. en parl. de relations intimes :</i> παρὰ γυναῖκα, HDT. <i>2, 115 ;</i> παρὰ τὸν Ἀρίστωνα, HDT. <i>6, 68 ;</i> πρός τινα, XÉN. <i>Œc. 7, 5 ;</i> avec une femme, avec Aristôn, avec qqn ; — <i>suivie d’un n. de lieu, ou, en gén., d’un rég. de ch. :</i> ἐλθεῖν πρὸς δώματα, OD. <i>8, 42,</i> être venu vers une demeure ; πρὸς Ἄργος, ESCHL. <i>Pr. 854,</i> vers Argos ; ἐς Λακεδαίμονα, AR. <i>Lys. 1231,</i> à Lacédémone ; ἀνὰ ἄστυ, OD. <i>8, 173 ;</i> κατὰ ἄστυ, OD. <i>7, 40,</i> à travers la ville ; ἐπὶ τὴν Ἑλλάδα, THC. <i>1, 18,</i> contre la Grèce ; ἐπὶ Ποτιδαίας ἔρχεσθαι, THC. <i>4, 130,</i> venir dans la direction de Potidée ; εἰς Ἅιδου ἔρχ. PLAT. <i>Tim. 44</i> c, aller dans la demeure d’Hadès ; ἐκ Πύλου, OD. <i>15, 42,</i> venir de Pylos ; ἐπὶ πόντον ἔρχ. OD. <i>2, 265,</i> aller sur la mer ; ἔρχ. ἐπὶ δεῖπνον, IL. <i>19, 275,</i> aller prendre (<i>litt</i>. vers) le repas ; ἔρχεσθαι ἐπὶ τὰ πράγματα, THC. <i>1, 88 ;</i> ἐπὶ πόλεμον, THC. <i>6, 36,</i> en venir aux affaires, à une guerre ; ἐπὶ τὰς μαθήσεις, PLAT. <i>Theæt. 144</i> b, chercher à acquérir les connaissances ; — <i>avec un adv</i>. ἐλθ. δεῦρο, ἐνταῦθα, <i>etc. (v. ci-dessus</i> A, I) ; πάλιν ἐλθέμεν, OD. <i>19, 533,</i> aller de nouveau ; ἂψ ἐλθεῖν, OD. <i>19, 544,</i> revenir ; — <i>avec un part. : part. de but au fut</i>. ἔρχομαι οἰσόμενος ἔγχος, IL. <i>13, 256,</i> je viens pour emporter une lance (de ta tente) ; μαρτυρήσων ἦλθον, ESCHL. <i>Eum. 576,</i> je suis venu pour porter témoignage ; <i>au sens d’un auxil., à peu près comme en franç</i>. « je vais dire, je vais faire » : ἔρχομαι ἐρέων (<i>v. ci-dessus</i> A, II) ; ἔρχομαι φράσων, HDT. <i>3, 6,</i> je vais dire ; <i>cf</i>. HDT. <i>2, 40 ; 7, 102 ;</i> ἔρχομαι δὲ περὶ Αἰγύπτου μηκυνέων τὸν λόγον, HDT. <i>2, 35,</i> je vais maintenant continuer mon récit sur l’Égypte ; <i>cf</i>. PLAT. <i>Euthyphr. 2</i> c, <i>Theag. 129</i> a, <i>Prot. 313</i> a, <i>Theæt. 198</i> e, <i>etc. ; ou au prés. :</i> ἔρχομαι ἐπιχειρῶν σοι ἐπιδείξασθαι, PLAT. <i>Phæd. 100</i> b, je vais essayer de te montrer ; — <i>part. de manière :</i> μὴ καὶ πεφοϐημένος ἔλθῃς, IL. <i>10, 510,</i> de peur que tu ne viennes ayant été mis en fuite ; ἦλθε φθάμενος, IL. <i>23, 779,</i> il vint (l’)ayant devancé ; — <i>avec un adj. de manière :</i> πεζὸς εἰλήλουθα (<i>v. ci-dessus</i> A, I) ; — <i>abs</i>. τῶν ἐρχομένων, IL. <i>2, 457,</i> (l’éclat des armées, des guerriers) qui s’avancent ; <i>à l’impér. en un sens d’exhortation, à peu près comme</i> ἄγε : ἔρχεο, θέων Αἴαντα κάλεσσον, IL. <i>12, 343,</i> viens, allons (<i>litt</i>. cours) et appelle Ajax ; ἀλλ' ἔρχευ, λέκτρον δ' ἴομεν, OD. <i>23, 254,</i> mais viens, allons au lit ; — <i>au. sens de</i> arriver, revenir : ἀγγελίην στρατοῦ ἐρχομένοιο, OD. <i>2, 30,</i> nouvelle de l’armée qui arrive ; — <i>au part. ao.2</i> ἐλθών <i>employé comme explétif :</i> οὐ δύναμαι μάχεσθαι ἐλθών, IL. <i>16, 521,</i> je ne puis (<i>litt</i>. étant venu) combattre l’ennemi ; δρᾶ νῦν τάδ' ἐλθών (<i>v. ci-dessus</i> A, III) ;<br><b>      2</b> <i>fig. dans un grand nombre de phrases où</i> ἔρχεσθαι <i>et</i> ἐλθεῖν, <i>employés d’abord au sens propre, ont fini par former des locut. courantes en un sens fig. :</i> εἰς λόγους ἔρχεσθαί τινι, HDT. <i>6, 86 ;</i> διὰ λόγων ἐλθεῖν, ATT. <i>etc.,</i> entrer en conversation avec qqn ; εἰς χεῖρας ἐλθεῖν τινι (<i>v</i>. χείρ) ; ἐς μάχην ἐλθεῖν τινι, HDT. <i>7, 9, 3 ;</i> EUR. <i>H.f. 579 ;</i> πρός τινα εἰς μάχην ἐλθεῖν, EUR. <i>Bacch. 636 ;</i> διὰ μάχης τινὶ ἔρχεσθαι, EUR. <i>Hel. 978 ;</i> THC. <i>2, 11,</i> en venir aux mains avec qqn, engager un combat avec qqn ; διὰ πολέμου ἔρχ. HDT. <i>6, 9 ;</i> THC. <i>2, 11,</i> engager une guerre ; τινὶ δι' ἀπεχθείας ἐλθεῖν, ESCHL. <i>Pr. 121</i> encourir la haine de qqn ; διὰ φόϐου ἔρχ. EUR. <i>Or. 757,</i> entrer en crainte ; εἰς ὀργάς τινι ἐλθ. PLAT. <i>Rsp. 572</i> a, entrer dans des sentiments de colère contre qqn ; διὰ πολλῶν κινδύνων ἐλθόντες καὶ φόϐων, PLAT. <i>2 Alc. 142</i> a, ayant traversé beaucoup de dangers et éprouvé beaucoup de craintes ; οἱ διὰ πάντων τῶν καλῶν ἐληλυθότες, XÉN. <i>Cyr. 1, 2, 15,</i> ceux qui ont parcouru toute la série des belles actions ; ἐπὶ μεῖζον ἔρχεσθαι, SOPH. <i>Ph. 259,</i> s’accroître ; ἐς οὐδὲν πρᾶγμα οὕτω μέγα ἐλθεῖν, THC. <i>8, 72,</i> une si grande entreprise en être venue à rien, <i>càd</i>. avoir abouti au néant ; ἐς ἀριθμὸν ἐλθεῖν, THC. <i>2, 72,</i> entrer en compte ; ὅσοι ἐνταῦθα ἡλικίας ἦλθον, PLAT. <i>Pol. 329</i> b, tous ceux qui sont arrivés à cet âge ; εἰς τοῦτο τρυφῆς ἐλθεῖν, XÉN. <i>Hell. 6, 2, 6,</i> en être venu à ce degré de mollesse ; εἰς τοσοῦτον αἰσχύνης ἐλθεῖν ὥστε, PLAT. <i>Gorg. 487</i> b, en être venu à ce degré de honte, que, <i>etc. ;</i> παρὰ μικρὸν ἐλθεῖν, <i>avec l’inf</i>. PLUT. <i>Pyrrh. 10,</i> en être venu à peu de distance de, près de, sur le point de, <i>etc. ;</i> παρὰ τοσοῦτον ἐλθ. κινδύνου, THC. <i>3, 49,</i> en venir à cette extrémité de péril ; <i>ou avec inf</i>. παρὰ τοσοῦτον ἐλθ. αἰχμαλωτίζεσθαι, APP. <i>1, 344, 94 Schweigh</i>. en être venu au point d’être fait prisonnier ;<br><b>   II</b> <i>avec un suj. de chose : en parl. de navires,</i> IL. <i>15, 549 ;</i> OD. <i>14, 334 ;</i> THC. <i>8, 80 ; — en parl. d’armes de jet (javelines, lances etc.)</i> IL. <i>3, 357 ; 7, 261 ; en parl. de la foudre,</i> ESCHL. <i>Pr. 358 ; — d’un flot de sang qui vient à la bouche,</i> OD. <i>18, 97 ; — en parl. de phénomènes naturels, d’un cours d’eau,</i> IL. <i>5, 91 ; de nuages,</i> IL. <i>4, 276 ; 16, 364 ; des vents,</i> OD. <i>12, 427 ; du vent et de la tempête,</i> IL. <i>9, 6 ;</i> OD. <i>12, 288 ; de la nuit :</i> εἰς ὅ κεν ἔλθῃ νύξ, IL. <i>14, 77 (cf. 24, 351</i>), jusqu’à ce que vienne la nuit ; <i>des ténèbres :</i> ἦλθε κνέφας, IL. <i>8, 500,</i> l’obscurité se répandit ; ἐπὶ κνέφας ἤλυθε γαῖαν, IL. <i>24, 531,</i> l’obscurité se répandit sur la terre ; <i>d’astres qui se lèvent,</i> OD. <i>13, 94 ; de sons :</i> περὶ δέ σφεας ἤλυθ' ἰωή, OD. <i>17, 261, (v. ci-dessus</i> A, II) ; <i>du temps :</i> ἐπὴν ἔλθῃσι θέρος, OD. <i>11, 192,</i> lorsque sera venu l’été ; — <i>en parl. de l’ivresse :</i> Κύκλωπα περὶ φρένας ἤλυθε οἶνος, OD. <i>9, 362,</i> l’ivresse (<i>litt</i>. le vin) enveloppa la raison du Cyclope ; — <i>de la douleur physique :</i> ὀδύνη διὰ χροὸς ἦλθε (<i>v. ci-dessus</i> A, II) ; — <i>de la vieillesse, etc. :</i> εἰς ὅ κε γῆρας ἔλθῃ καὶ θάνατος, OD. <i>13, 60,</i> jusqu’à ce que soient venues la vieillesse et la mort ; — <i>en parl. de choses envoyées (présent, lettre, nouvelle, etc.)</i> : γέρας ἔρχεται ἄλλῃ (<i>v. ci-dessus</i> A, III) ; ἐλθούσης ἐπιστολῆς, THC. <i>8, 33,</i> une lettre étant arrivée ; ἐλθούσης ἀγγελίας αὐτοῖς ἀποπλεῖν πάλιν, THC. <i>8, 19,</i> l’avis leur étant arrivé de reprendre la mer ; τοῖς δὲ Ἀθηναίοις ὡς ἦλθε τὰ περὶ τὴν Εὔϐοιαν γεγενημένα, THC. <i>8, 96,</i> lorsque arriva aux Athéniens la nouvelle des événements accomplis dans la région de l’Eubée ;— <i>en parl. d’événements :</i> ὁμόσ' ἦλθε μάχη, IL. <i>13, 337,</i> le combat en vint au même point ; εἰ πάλιν ἔλθοι τῇ Ἑλλάδι κίνδυνος ὑπὸ βαρϐάρων, XÉN. <i>Hell. 6, 5, 43,</i> s’il survenait de nouveau pour la Grèce un danger de la part des barbares ; — <i>en parl. de bruits, d’ordres,</i> ESCHL. <i>Pr. 663 ;</i> THC. <i>8, 19 et 96 ; — en parl. de sentiments (douleur, désir, etc.)</i> : ἦ κέ μοι αἰνὸν ἀπὸ πραπίδων ἄχος ἔλθοι, IL. <i>22, 43, litt</i>. une douleur terrible serait sortie de mes entrailles ; τὰ θεῶν μελεδήμαθ' ὅταν φρένας ἔλθῃ, EUR. <i>Hipp. 1102,</i> lorsque la sollicitude des dieux vient à l’esprit ; — <i>en parl. de raisonnements :</i> ὅθεν ὁ νῦν παρὼν ἡμῖν λόγος ἐλήλυθε, PLAT. <i>Leg. 917</i> a, le point où a commencé (<i>litt</i>. d’où est parti) notre entretien présent.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 2 sg. épq</i>. ἔρχεαι, IL. <i>10, 385 ;</i> THGN. <i>1374 ; impér. 2 sg. épq</i>. ἔρχεο, IL. <i>15, 54 ;</i> ἔρχευ, IL. <i>23, 893 ; 2 pl</i>. ἔρχεσθε, IL. <i>9, 649 ; 2 duel</i> ἔρχεσθον, IL. <i>1, 322 ;</i> AR. <i>Ach. 1144 ; sbj. rare 3 sg</i>. ἔρχηται, IL. <i>10, 185 ;</i> HPC. <i>7, 598 Littré, etc. ; 1 pl</i>. ἐρχώμεθα, HIÉROCL. <i>Facet. 181 Eberhard ; 3 pl</i>. ἔρχωνται, HIM. <i>Or. 15, 3 ; opt. inus. ; inf</i>. ἔρχεσθαι, IL. <i>15, 161, etc. ; part</i>. ἐρχόμενος, IL. <i>3, 22 ;</i> OD. <i>21, 39, etc</i>. —<i>Impf</i>. ἠρχόμην <i>rare et réc. (sauf dans les cps</i>. διηρχόμην, ἐπηρχόμην, <i>etc.)</i> HPC. <i>5, 426 ; 9, 328 Littré ;</i> LUC. <i>J. voc. 4,</i> PAUS. <i>5, 8, 2 ;</i> SPT. <i>Gen. 48, 7 ; Ezech. 9, 2 ;</i> NT. <i>Marc. 1, 45, etc. (ne pas confondre avec</i> ἠρχόμην, <i>impf. pass. de</i> ἄρχω, PLAT. <i>Leg. 685, Conv. 240, etc.). — Fut</i>. ἐλεύσομαι, <i>poét</i>. IL. <i>13, 753 ;</i> OD. <i>16, 8, etc. ; et de prose ion</i>. HDT. <i>6, 9 ; 8, 130 ;</i> HPC. <i>7, 498 et 612 ; 8, 38 et 74 Littré ; rare en poésie att</i>. ESCHL. <i>Pr. 854, Suppl. 522 ;</i> SOPH. <i>O.C. 1206, Tr. 595 ; inus. chez les Comiques ; très rare en prose att. (où le fut. usuel est</i> εἶμι <i>ou</i> ἥξω, <i>qqf</i>. ἀφίξομαι) LYS. <i>22, 11 Baiter-Sauppe ; usuel chez les écrivains réc</i>. DH. <i>3, 15 ; 5, 31, etc. ;</i> APP. <i>Civ. 1, 89 ; 5, 123, etc. — Ao.1 rare</i> ἤλυθα <span>[ῠ]</span> NONN. <i>D. 37, 424 ; 2 pl</i>. ἤλθατε, NT. <i>Matth. 25, 36 ; 3 pl</i>. ἦλθαν, NT. <i>Ap. 12, 10 ; impér. 3 sg</i>. ἐλθάτω, SPT. <i>Esth. 5, 4 ; 2 pl</i>. ἔλθατε, SPT. <i>Prov. 9, 5. — Ao.2 poét</i>. ἤλυθον <span>[ῠ]</span> <i>épq</i>. IL. <i>1, 152 ; 10, 28 ;</i> HÉS. <i>Th. 668 ;</i> PD. <i>N. 10, 79 ; P. 3, 99, et de poésie att. d’ord. dans les chœurs,</i> SOPH. <i>Aj. 234 ;</i> EUR. <i>Or. 813, Ph. 823, etc. ; rar. dans le dialogue,</i> EUR. <i>El. 598, Tr. 374, Rhes. 660 ; par sync</i>. ἦλθον, IL. <i>1, 207 ;</i> OD. <i>4, 82 ;</i> HÉS. <i>Th. 176 ;</i> PD. <i>O. 1, 44 ; N. 6, 12 ;</i> ESCHL. <i>Eum. 251 ;</i> SOPH. <i>O.R. 447, etc. ; seule forme us. en prose,</i> HDT. <i>2, 115 ;</i> THC. <i>2, 56 ; 6, 82, etc. ; 3 pl. alexandr</i>. ἤλθοσαν, Ps.-CALLISTH. <i>2, 35 ; impér</i>. ἐλθέ, IL. <i>23, 770 ;</i> SOPH. <i>Ph. 1190, etc. ; sbj</i>. ἔλθω, IL. <i>22, 113 ;</i> HDT. <i>1, 209, etc. ; 3 sg. poét</i>. ἔλθῃσι, IL. <i>5, 132 ;</i> HÉS. <i>fr. 80, 10 Göttling ; opt</i>. ἔλθοιμι, IL. <i>5, 301 ;</i> OD. <i>11, 501 ;</i> THC. <i>6, 37, etc. ; inf</i>. ἐλθεῖν (<i>31 ex. homér</i>. IL. <i>7, 160, etc</i>.) ; HDT. <i>1, 27 ; 2, 32 ;</i> THC. <i>2, 5, etc. ; épq</i>. ἐλθέμεναι (<i>8 ex. homér</i>.) IL. <i>1, 151, etc. ; ou</i> ἐλθέμεν (<i>23 ex. homér</i>.) IL. <i>15, 146, etc.) ; part</i>. ἐλθών, IL. <i>14, 8 ;</i> THC. <i>4, 83, etc. ; dat. pl. dor</i>. ἐλθόντεσσι, PD. <i>P. 4, 30 ; — ao.2 dor</i>. ἦνθον, EPICH. <i>fr. 126 Ahrens ;</i> CALL. <i>L. Pall. 8, Cer. 27 ;</i> THCR. <i>Idyl. 2, 118 ; 16, 9 ; — lacon</i>. ἦλσον, <i>d’où sbj. 3 sg</i>. ἔλσῃ, AR. <i>Lys. 105 ; opt</i>. ἔλσοιμι, <i>ibid. 118 ; part</i>. ἐλσών, <i>ibid. 1081. — Pf</i>. ἐλήλυθα, HDT. <i>8, 68 ;</i> ESCHL. <i>Pr. 943 ;</i> SOPH. <i>O.C. 366, etc. ;</i> XÉN. <i>Cyr. 1, 2, 15, etc. ; 1 pl</i>. ἐληλύθαμεν, PLAT. <i>Leg. 683, etc. ; par sync</i>. ἐλήλυμεν, CRAT. (<i>Com. fr. 2, 153</i>) ; ACH. <i>fr. 22 ; 2 pl. par sync</i>. ἐλήλυτε, <i>ibid. ; — pf. épq</i>. ἐλήλουθα, <i>d’où part</i>. ἐληλουθώς, IL. <i>15, 81 ; et</i> εἰλήλουθα, IL. <i>5, 204 ; 15, 131, etc. ;</i> THCR. <i>Idyl. 25, 35 ; 1 pl. sync</i>. εἰλήλουθμεν, IL. <i>9, 49 ;</i> OD. <i>3, 81 ; part</i>. εἰληλουθώς, OD. <i>19, 28 ; 20, 360. — Pl.q.pf. 3 sg</i>. ἐληλύθει, EUP. (AR. <i>Eq. 1306 ;</i> εἰληλύθ- <i>Mein. Dind.) ; 3 sg. ion</i>. ἐληλύθεε, HDT. <i>5, 98 ; 8, 114 ; épq</i>. εἰληλούθει, IL. <i>4, 520 ; 5, 44 ; 17, 350. — Moy. ao. opt</i>. ἐλθοίμην BATR. <i>179</i> (ἐλθοίην <i>Franke ;</i> ἐρχοίμην <i>Wolf</i>).<br><span><b>Étym</b>. ἔρχομαι <i>de la R. indo-europ</i>. *h₁erg<sup>h</sup>-, *h₁er-, bouger, aller ; ἐλεύσομαι, ἤλυθον <i>et</i> ἐλήλυθα <i>de la</i> R. *h₁leud<sup>h</sup>-, pousser, grandir, <i>cf</i>. ἐλεύθερος ; <i>l’étym. de</i> ἐλθεῖν <i>est incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερχομαι - ἔρχομαι</font>\n<br><br>verbe primaire, utilisé seulement au présent et à l'imparfait, les autres temps étant eleuthomai (el-yoo'-thom-ahee), ou eltho (el'-tho)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote généralement un mouvement ou une marche, et de toute sorte, aussi bien « venir » et arriver à, que « aller »\n<br><br> – signifie d'une façon primaire « se promener », « marcher », indiquant le moyen de déplacement ; « partir »\n<br><br> – exprime le mouvement en général, souvent confiné dans certaines limites, ou donnant la prééminence à la conduite ; c'est le mot utilisé pour la marche d'une armée\n<br><br> – accentue toujours l'idée de séparation, de changement de lieu, et n'indique pas, comme le , le mouvement externe et perceptible</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n646 fois dans 601 versets de 24 livres bibliques (NT)\n<ul>\n<li>Matthieu (117)</li>\n<li>Marc (83)</li>\n<li>Luc (102)</li>\n<li>Jean (161)</li>\n<li>Actes (55)</li>\n<li>Romains (11)</li>\n<li>1 Corinthiens (19)</li>\n<li>2 Corinthiens (16)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Hébreux (5)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (4)</li>\n<li>2 Jean (3)</li>\n<li>3 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (36)</li>\n</ul>\n</td></tr>\n</table>","G2065":"<h1>erotao</h1>\n<p>Strong n° 2065 <i>Prononciation [er-o-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>interroger</li>\n<li>demander à\n<ol type=\"a\">\n<li>demander, supplier, prier</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐρωτάω-ῶ</b> <span>(<i>impf</i>. ἠρώτων, <i>f</i>. ἐρωτήσω, <i>ao</i>. ἠρώτησα, <i>pf</i>. ἠρώτηκα)</span><br><b>      1</b> demander, interroger : τινα, OD. <i>5, 97 ;</i> XÉN. <i>An. 3, 1, 7 ; Mem. 1, 3, 1,</i> qqn ; <i>en ce sens, dans une inscr. att</i>. CIA. <i>2, 601, 7 (après 300 av. J.C. ; v. Meisterh. p. 146, 5</i>) ; τινα ἀμφί τινος, EUR. <i>Ion 236,</i> interroger qqn sur qqe ch. ; τι, OD. <i>4, 347, etc. ;</i> ESCHL. <i>Pr. 226 ;</i> PLAT. <i>Rsp. 508</i> a, demander qqe ch. ; ἐρ. ἐρώτημα, PLAT. <i>Rsp. 487</i> e, faire une question ; ἐρ. τι περί τινος, PLAT. <i>Theæt. 185</i> c, demander une chose au sujet d’une autre ; ἐρ. τινά τι, OD. <i>4, 347 ; 17, 138 ;</i> SOPH. <i>O.R. 1122, etc. ;</i> EUR. <i>I.A. 1129 ;</i> PLAT. <i>Rsp. 337</i> a, <i>etc</i>. demander qqe ch. à qqn ; <i>avec un relat. :</i> ἐρ. ὅπου, XÉN. <i>Cyr. 2, 4, 30,</i> demander où, <i>etc. ;</i> εἰρώτα τίς εἴη καὶ πόθεν ἔλθοι, OD. <i>15, 423,</i> il demandait qui elle était et d’où elle venait ; ἐρωτᾶν τίνες εἶεν, EN. TACT. demander qui ils étaient, crier « qui vive ! » ; <i>avec une conj</i>. ἐρ. εἰ, XÉN. <i>Cyr. 2, 4, 30 ;</i> ἐρ. ἤν, HPC. <i>682, 46 ;</i> ATT. demander si, <i>etc. ; au pass</i>. τὸ ἐρωτώμενον, XÉN. <i>Mem. 4, 2, 23,</i> la question posée ; τὸ ἐρωτηθέν, THC. <i>3, 61,</i> la question qui avait été posée ; τὰ ἠρωτημένα, PLAT. <i>Leg. 662</i> d, les questions qui ont été posées ;<br><b>      2</b> <i>t. de dialect</i>. poser une question, ARR. <i>Epict. 2, 18, 18 ; 2, 19, 1,</i> SEXT. <i>10, 13 ; 113, 23 ; 144, 9 et 23 Bkk. ;</i> DL. <i>2, 108 ; 9, 23 ; particul</i>. poser une question à l’adversaire pour l’amener à une conclusion, <i>d’où</i> argumenter, raisonner sous forme d’interrogation, <i>p. opp. à l’argumentation par syllogisme direct,</i> ARSTT. <i>An. pr. 1, 1, 3 ;</i> LUC. <i>H. conscr. 17 ;</i><br><b>      3</b> <i>postér</i>. prier, demander avec prière : τινά τι, SPT. <i>1Reg. 30, 21,</i> qqe ch. à qqn ; ἐρ. τινα <i>avec l’inf</i>. NT. <i>8, 37 ;</i> ἐρ. τινα <i>et le sbj</i>. NT. <i>Marc. 7, 26 ; Luc. 7, 36 ;</i> ἐρ. τινα ὅπως, NT. <i>Luc. 7, 3,</i> prier que, demander de, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. dor</i>. ἐρώτη, AR. <i>Ach. 800 ; impf. 3 sg. ion</i>. ἠρώτη, THCR. <i>Idyl. 5, 74. Épq. et ion</i>. εἰρωτάω, OD. <i>17, 138 ;</i> HDT. <i>3, 14 ; impf. 3 sg</i>. εἰρώτα, OD. <i>15, 423 ;</i> HDT. <i>1, 88 ; 3 pl</i>. εἰρώτεον, HDT. <i>4, 145, ou</i> εἰρώτευν, HDT. <i>1, 158 ; postér</i>. ἠρώτουν. NT. <i>Ap. 1, 6 (var</i>.).<br><span><b>Étym</b>. <i>apparenté à</i> *ἔρομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ερωταω - ἐρωτάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote une requête de la volonté\n<br><br> – une demande pour un besoin\n<br><br> – dénote la forme de la requête</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n58 fois dans 57 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (14)</li>\n<li>Jean (27)</li>\n<li>Actes (6)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2066":"<h1>esthes</h1>\n<p>Strong n° 2066 <i>Prononciation [es-thace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être vêtu, habit, habillement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐσθής, ῆτος (ἡ) :<br>      1</b> vêtement, habit, OD. <i>1, 165 ; 5, 38 ;</i> ESCHL. <i>Ag. 1270 ;</i> THC. <i>1, 6 ; au pl</i>. vêtements <i>pour plus. pers</i>. ESCHL. <i>Sept. 871 ;</i> PLAT. <i>1 Alc. 122</i> c ; <i>pour une seule,</i> EUR. <i>Hel. 421 ; au sg. collect</i>. des vêtements, OD. <i>5, 38 ; 7, 6 ;</i> HDT. <i>3, 66 ;</i> XÉN. <i>An. 3, 1, 19, etc. ; particul</i>. linge, <i>comme la partie principale du vêtement,</i> OD. <i>6, 74 ;</i><br><b>      2</b> <i>p. ext</i>. tout ce qui sert à envelopper, couverture de lit, OD. <i>23, 290</i>.<br><span><b>Étym</b>. ἕννυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσθης - ἐσθής</font>\n<br><br>vient de 'hennumi' (vêtir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>Jacques (3)</li>\n</ul>\n</td></tr>\n</table>","G2067":"<h1>esthesis</h1>\n<p>Strong n° 2067 <i>Prononciation [es'-thay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vêtements, habillement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσθησις, εως (ἡ)</b> action de se vêtir, <i>d’où</i> vêtement, <i>au plur</i>. ATH. <i>18</i> e ; NT. <i>Luc. 24, 4</i>.<br><span><b>Étym</b>. ἐσθέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσθησις - ἔσθησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2068":"<h1>esthio</h1>\n<p>Strong n° 2068 <i>Prononciation [es-thee'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manger</li>\n<li>consommer une chose\n<ol type=\"a\">\n<li>prendre de la nourriture, se nourrir</li>\n</ol>\n</li>\n<li>métaph. dévorer, consumer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐσθίω</b> <span>(<i>impf</i>. ἤσθιον, <i>fut</i>. ἔδομαι, <i>et réc</i>. φάγομαι, <i>ao.2</i> ἔφαγον, <i>pf</i>. ἐδήδοκα, <i>pf.2</i> ἔδηδα, <i>pl.q.pf</i>. ἐδηδόκειν ; <i>pass. ao</i>. ἠδέσθην, <i>pf</i>. ἐδήδεσμαι)</span><br><b>   I</b> manger :<br><b>      1</b> <i>en parl. de pers</i>. OD. <i>2, 305 ; 20, 348, etc. ;</i> THC. <i>3, 49 ; à côté de</i> πίνειν, THGN. <i>33 ;</i> XÉN. <i>Cyr. 8, 8, 11, etc. ;</i> τι, OD. <i>20, 348,</i> qqe ch. (de la viande) ; τινός, XÉN. <i>Hell. 3, 3, 6, etc</i>. de qqe ch. ; τὰ ἐσθίοντα, XÉN. <i>Cyr. 1, 6, 17,</i> l’organe qui sert à manger, la bouche ;<br><b>      2</b> <i>rar. en parl. d’animaux,</i> paître, se repaître, OD. <i>9, 292 ;</i> HÉS. <i>Th. 524, 773, etc. ;</i> SIM. (ATH. <i>299</i> c) ; AR. <i>Pax 31 ;</i> ARSTT. <i>H.A. 6, 18 ;</i><br><b>      3</b> <i>fig</i>. dévorer, consumer, <i>en parl. de la ruine d’une maison,</i> OD. <i>4, 318 ; en parl. du feu,</i> IL. <i>23, 182 ; d’un mal,</i> ESCHL. <i>fr. 246 ; de soucis,</i> PYTHAG. (PLUT. <i>M. 12</i> e) ;<br><b>   II</b> <i>p. ext</i>. se mordre (la lèvre) AR. <i>Vesp. 1083 ;</i><br><b><i>Moy.</i></b> ronger, dévorer, HPC. <i>1128</i> f.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. épq</i>. ἐσθιέμεν, OD. <i>21, 69 ; impf</i>. ἤσθιον, OD. <i>20, 19 ;</i> HÉS. <i>O. 147 ;</i> EUR. <i>Cycl. 233 ;</i> THC. <i>3, 49 ;</i> XÉN. <i>Ages. 9, 3. Ao.2 sbj. 3 sg. épq</i>. φάγῃσι, OD. <i>8, 477 ; inf. épq</i>. φαγέειν, OD. <i>16, 429 ;</i> HPC. <i>8, 610 Littré ; ou</i> φαγέμεν, OD. <i>16, 143 ; 18, 3</i>.<br><span><b>Étym</b>. <i>cf</i>. ἔδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσθιω - ἐσθίω</font>\n<br><br>renforcement du mot 'edo' (manger)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n65 fois dans 55 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (11)</li>\n<li>Luc (12)</li>\n<li>Actes (1)</li>\n<li>Romains (10)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2069":"<h1>Esli</h1>\n<p>Strong n° 2069 <i>Prononciation [es-lee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Esli = « réservé de l'Eternel »\n<ol><li>le fils de Naggaï dans la généalogie de Christ. <a class=\"ref\" data-r=\"LUK3.25\">Luc 3.25</a></li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εσλι</font> &lt; חסלי - <font face=\"Georgia\">Ἑσλί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2070":"<h1>esmen</h1>\n<p>Strong n° 2070 <i>Prononciation [es-men']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>première personne du pluriel de « être »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσμεν - ἐσμέν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n53 fois dans 51 versets de 13 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (5)</li>\n<li>Actes (9)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Jean (7)</li>\n</ul>\n</td></tr>\n</table>","G2071":"<h1>esomai</h1>\n<p>Strong n° 2071 <i>Prononciation [es'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>première personne du singulier du futur du verbe « être »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσομαι</b>, <i>fut. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσομαι - ἔσομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n187 fois dans 169 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (47)</li>\n<li>Marc (18)</li>\n<li>Luc (49)</li>\n<li>Jean (6)</li>\n<li>Actes (9)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (8)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (5)</li>\n<li>Hébreux (7)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (2)</li>\n<li>2 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (15)</li>\n</ul>\n</td></tr>\n</table>","G2072":"<h1>esoptron</h1>\n<p>Strong n° 2072 <i>Prononciation [es'-op-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un miroir\n<ol type=\"a\">\n<li>les miroirs anciens n'étaient pas faits de verre mais de métal poli</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσοπτρον</b>, <i>anc. att. c</i>. εἴσοπτρον.<br><br>\n<b>*εἴσοπτρον</b>, <i>seul</i>. <b>ἔσοπτρον, ου (τὸ)</b> miroir, PD. <i>N. 7, 14 ;</i> JOS. <i>A.J. 12, 2, 9 ;</i> PLUT. <i>M. 139</i> f, <i>765</i> a.<br><span><b>Étym</b>. εἰσόψομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσοπτρον - ἔσοπτρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2073":"<h1>hespera</h1>\n<p>Strong n° 2073 <i>Prononciation [hes-per'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>soir, soirée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑσπέρα, ας (ἡ) :<br>      1</b> le soir : ἑσπέρας, PD. <i>P. 4, 70 ;</i> AR. <i>Nub. 175 ;</i> ἑσπέρην, HPC. <i>644, 25,</i> le soir, sur le soir ; πρὸς ἑσπέρᾳ, AR. <i>Vesp. 1085 ;</i> εἰς τὴν ἑσπέραν, XÉN. <i>Hell. 1, 6, 20 ; An. 3, 1, 3 ;</i> εἰς ἑσπέραν, PLAT. <i>Conv. 223</i> d ; καθ' ἑσπέραν, SPT. <i>1Reg. 23, 24,</i> sur le soir ; πρὸς ἑσπέραν, XÉN. <i>Hell. 1, 1, 30 ;</i> PLAT. <i>Rsp. 328</i> a ; τὸ πρὸς ἑσπέραν, SPT. <i>Gen. 8, 11,</i> vers le soir ; ἄκρᾳ σὺν ἑσπέρᾳ, PD. <i>P. 11, 10,</i> à la fin de la soirée, au commencement de la nuit ; εὐθὺς ἀφ' ἑσπέρας XÉN. <i>Hell. 2, 4, 15 ;</i> ἀπὸ ἑσπέρας εὐθ. THC. <i>3, 112,</i> à la tombée de la nuit ; περὶ ἑσπέραν βαθεῖαν, PLUT. <i>M. 179</i> d, tard dans la soirée ; ἐπειδὴ ἑσπέρα ἦν, PLAT. <i>Conv. 220</i> c, lorsque le soir fut venu ; ἐπεὶ πρὸς ἑσπέραν ἦν, XÉN. <i>Hell. 4, 3, 22,</i> lorsqu’on vint au soir ; ἑσπέρας γενομένης, XÉN. <i>Cyr. 1, 4, 17,</i> le soir venu ; ἑσπέρας ἐπιγενομένης, XÉN. <i>Hell. 6, 5, 17,</i> le soir étant survenu ; <i>au plur</i>. les heures de la soirée, PD. <i>I. 7, 44 ; fig</i>. βίου ἑσπ. ARSTT. <i>Poet. 21, 13,</i> le soir de la vie ;<br><b>      2</b> la région du couchant : πρὸς ἑσπέραν, EUR. <i>Or. 260,</i> du côté de l’occident ; τὰ πρὸς ἑσπέραν, THC. <i>6, 2 ;</i> ἡ πρὸς ἑσπέρην χώρη, HDT. <i>1, 82 ;</i> τὸ πρὸς ἑσπέρης, HDT. <i>8, 130,</i> la région du couchant <i>ou</i> de l’occident ; <i>particul. en parl. de l’Italie, par rapport à l’Égypte, à la Syrie et à l’Asie Mineure,</i> POL. <i>5, 104, 10 ; 9, 37, 10 ;</i> HPC. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>fém. de</i> ἕσπερος, <i>par analog. avec</i> ἡμέρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσπερα - ἑσπέρα</font>\n<br><br>vient d'un adjectif 'hesperos' (soir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2074":"<h1>Esrom</h1>\n<p>Strong n° 2074 <i>Prononciation [es-rome]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Esrom ou Hetsron = « entouré d'un mur, rempart »\n<ol><li>le fils de Ruben, et ancêtre des Hetsronites</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Εσρωμ</font> &lt; חצרון - <font face=\"Georgia\">Ἑσρώμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2075":"<h1>este</h1>\n<p>Strong n° 2075 <i>Prononciation [es-teh']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>seconde personne du pluriel de « être »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐστέ</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εστε - ἐστέ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n92 fois dans 88 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (4)</li>\n<li>Luc (10)</li>\n<li>Jean (16)</li>\n<li>Actes (4)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (6)</li>\n<li>Ephésiens (4)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>Hébreux (2)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2076":"<h1>esti</h1>\n<p>Strong n° 2076 <i>Prononciation [es-tee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>troisième personne du singulier du verbe « être »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐστί</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εστι - ἐστί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n908 fois dans 820 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (120)</li>\n<li>Marc (73)</li>\n<li>Luc (106)</li>\n<li>Jean (166)</li>\n<li>Actes (69)</li>\n<li>Romains (39)</li>\n<li>1 Corinthiens (74)</li>\n<li>2 Corinthiens (14)</li>\n<li>Galates (18)</li>\n<li>Ephésiens (23)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (18)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (5)</li>\n<li>1 Timothée (12)</li>\n<li>2 Timothée (7)</li>\n<li>Tite (3)</li>\n<li>Hébreux (12)</li>\n<li>Jacques (18)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (5)</li>\n<li>1 Jean (74)</li>\n<li>2 Jean (3)</li>\n<li>3 Jean (2)</li>\n<li>Apocalypse (34)</li>\n</ul>\n</td></tr>\n</table>","G2077":"<h1>esto</h1>\n<p>Strong n° 2077 <i>Prononciation [es'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>troisième personne du singulier du verbe « être »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔστω</b>, <i>3 sg. impér. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εστω - ἔστω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (1)</li>\n<li>Actes (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>1 Timothée (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2078":"<h1>eschatos</h1>\n<p>Strong n° 2078 <i>Prononciation [es'-khat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>extrême\n<ol type=\"a\">\n<li>dernier en temps ou lieu</li>\n<li>dernier dans des séries de lieux</li>\n<li>dernier dans une succession dans le temps</li>\n</ol>\n</li>\n<li>le dernier\n<ol type=\"a\">\n<li>dernier, se référant aux temps</li>\n<li>de l'espace, partie extrême, la fin de la terre</li>\n<li>d'un rang ou grade, le plus bas</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσχατος, η, ον</b> <span>[ᾰ]</span> qui est à l’extrémité, extrême, dernier :<br><b>   I</b> (<i>avec idée de lieu</i>) :<br><b>      1</b> <i>au propre :</i> θάλαμος ἔσχ. OD. <i>21, 9,</i> la chambre la plus reculée ; ἔσχατοι ἀνδρῶν, OD. <i>1, 23,</i> les plus lointains des hommes, ceux qui habitent aux extrémités du monde (les Éthiopiens) ; <i>cf</i>. OD. <i>6, 205 ;</i> HDT. <i>3, 106 ;</i> THC. <i>2, 96 ;</i> ATT. ; τὰ ἔσχ. τοῦ ἄστεος, τοῦ στρατοπέδου, THC. <i>8, 95 ; 4, 96,</i> l’extrémité de la ville, du camp ; <i>ou sans art</i>. ἐπ' ἔσχατα, SOPH. <i>fr. 655 ;</i> παρ' ἔσχατα, PLAT. <i>Phæd. 113</i> b, à l’extrémité ; <i>adv</i>., ἔσχατα, IL. <i>11, 8,</i> aux extrémités (du camp) ;<br><b>      2</b> <i>p. suite,</i> la partie la plus haute <i>ou</i> la plus basse, <i>d’où</i> ἔσχ. πυρά, SOPH. <i>El. 900,</i> le sommet d’un tombeau ; ἔσχ. Ἀΐδαν, THCR. <i>Idyl. 16, 52,</i> le fond des Enfers ; ἐσχάτας σάρκας, SOPH. <i>Tr. 1053,</i> l’intérieur des chairs ;<br><b>      3</b> <i>fig</i>. qui est au plus haut degré, extrême, dernier : ἔσχατ' ἐσχάτων κακά, SOPH. <i>Ph. 65,</i> les derniers des derniers des maux ; ἐσχ. ὀδύνη, PLAT. <i>Prot. 354</i> b, douleur extrême ; ἀπικέσθαι ἐς τὸ ἔσχατον κακοῦ, HDT. <i>8, 52,</i> en être arrivé au dernier degré du malheur ; ἐπ' ἔσχατον θράσους, SOPH. <i>Ant. 853,</i> au dernier degré d’audace ; ἐπ' ἔσχατα βαίνειν, SOPH. <i>O.C. 217,</i> s’avancer jusqu’au dernier degré (de misère, d’infortune, <i>etc</i>.) ; πᾶσι τοῖς ἐσχάτοις ζημιοῦσθαι, PLAT. <i>Pol. 297</i> e, être puni du dernier châtiment ;<br><b>      4</b> <i>au sens mor</i>. dernier, le plus bas, le plus vil, DS. <i>Exc. Vat. p. 9 ;</i> DC. <i>42, 5 ;</i> ALCIPHR. <i>3, 43 ; prov</i>. <span>οὐδεὶς οὐδ' ὁ Μυσῶν ἔσχ</span>. MÉN. <i>fr. 481,</i> personne, pas même le dernier des Mysiens, <i>càd</i>. le dernier <i>ou</i> le plus vil des hommes ;<br><b>   II</b> (<i>avec idée de temps</i>) : ἔσχ. Ἑλλήνων, Ῥωμαίων, PLUT. <i>Phil. 1, Brut. 44,</i> le dernier des Grecs, des Romains ; ἐς τὸ ἔσχατον, HDT. <i>7, 107 ;</i> THC. <i>3, 46 ;</i> jusqu’à la fin ; <i>adv</i>., τὸ ἔσχατον, PLAT. <i>Gorg. 473</i> c ; ἔσχατον, SOPH. <i>O.C. 1550,</i> pour la dernière fois.<br><span>•<i> Cp</i>. -ώτερος, ARSTT. <i>Metaph. 9, 44 ;</i> <i>• Sup</i>. -ώτατος, XÉN. <i>Hell. 2, 3, 49</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἔσχατος, ARAT. <i>625, 628</i>.<br><span><b>Étym</b>. ἐξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσχατως - ἔσχατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n53 fois dans 48 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (5)</li>\n<li>Luc (6)</li>\n<li>Jean (8)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (2)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2079":"<h1>eschatos</h1>\n<p>Strong n° 2079 <i>Prononciation [es-khat'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>extrême, être dans les derniers sursauts, à l'article de la mort être sur le point de rendre l'âme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐσχάτως</b> <span>[ᾰ]</span> <i>adv. :</i><br><b>      1</b> extrêmement, au plus haut point, XÉN. <i>An. 2, 6, 1 ;</i> ἐ. διακεῖσθαι, POL. <i>1, 24, 2 ;</i> DS. <i>18, 48,</i> être dans une situation extrême, <i>càd</i>. la plus grave possible ;<br><b>      2</b> jusqu’à l’extrémité : ἐ. διαμάχεσθαι, ARSTT. <i>H.A. 9, 7, 6,</i> combattre avec ténacité, jusqu’au bout.<br><span><b>Étym</b>. ἔσχατος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσχατως - ἐσχάτως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2080":"<h1>eso</h1>\n<p>Strong n° 2080 <i>Prononciation [es'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entrer, en, dans, à l'intérieur</li>\n<li>en dedans de\n<ol type=\"a\">\n<li>l'homme intérieur</li>\n<li>l'âme, la conscience</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσω</b>, <i>v</i>. εἴσω.<br><br>\n<b>εἴσω</b>, <i>ion. et anc. att</i>. <b>ἔσω</b>, <i>adv. et prép. :</i><br><b>   I</b> (<i>avec idée de lieu</i>) à l’intérieur, <i>d’où :</i><br><b>      1</b> au dedans : <i>avec mouv., construit avec l’acc. :</i> ὀτρῦναι πόλιν εἴσω, OD. <i>15, 40,</i> envoie-le à la ville ; ἡγήσατο Ἴλιον εἴσω, IL. <i>1, 71,</i> il conduisit (les vaisseaux) jusqu’à Ilion ; δῦναι δόμον Ἄϊδος εἴσω, IL. <i>3, 322,</i> descendre au fond de la demeure d’Hadès ; <i>avec le gén</i>. ἐϐήσετο δώματος εἴσω, OD. <i>7, 135,</i> il entra dans l’intérieur de la maison (<i>en ce sens dans Hom. après le gén., excepté</i> IL. <i>21, 125</i>) ; παρῆλθον εἴσω αὐτοῦ, XÉN. <i>An. 2, 4, 12,</i> ils s’avancèrent dans l’intérieur, <i>càd</i>. au-delà (du retranchement) ; <i>abs</i>. φεύγειν εἴσω, XÉN. <i>Cyr. 7, 5, 26,</i> se réfugier à l’intérieur ; τὸ εἴσω, τὰ εἴσω (<i>ou</i> ἔσω) ATT. à l’intérieur ;<br><b>      2</b> <i>sans mouv. avec le gén</i>. μένειν εἴσω δόμων, ESCHL. <i>Sept. 232,</i> rester à l’intérieur de la maison ; αἱ ἔσω στέγης, SOPH. <i>Tr. 202,</i> celles qui sont dans la maison ; <i>abs</i>. εἴσω δόρπον ἐκόσμει, OD. <i>7, 13,</i> elle préparait le repas à l’intérieur (de la chambre) ; ἔσω καθῆσθαι, ESCHL. <i>Ch. 919,</i> être à l’intérieur ; τὸ ἔσω μέτωπον, THC. <i>3, 21,</i> le front (de l’armée) au centre ;<br><b>      3</b> à portée de : εἴσω ξίφους, EUR. <i>Or. 1531 ;</i> βέλους, ARR. <i>An. 1, 6,</i> à portée de l’épée, du trait ;<br><b>   II</b> <i>avec idée de temps,</i> pendant ce temps, AR. <i>Eq. 2 Arg</i>.<br><span>•<i> Cp</i>. ἐσωτέρω, HDT. <i>8, 66 ;</i> HPC. <i>783</i> e. <i>• Sup</i>. ἐσωτάτω, HPC. <i>276, 18 ; 785</i> c.<br><span><b><span class=\"arrow\"></span></b> ἔσω, OD. <i>7, 50 ; 24, 155, 184, 199 ;</i> ESCHL. <i>Ag. 1343 ;</i> SOPH. <i>Tr. 202 ;</i> THC. <i>l. c. ;</i> THCR. <i>Idyl. 3, 5 ; 13, 71, etc. — Dans les inscr. att. la forme</i> εἴσω <i>se rencontre à partir de 347 av. J.C. (v. Meisterh. p. 175, 14)</i>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσω - ἔσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2081":"<h1>esothen</h1>\n<p>Strong n° 2081 <i>Prononciation [es'-o-then]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>du dedans de</li>\n<li>dedans, ce qui est en dedans, l'intérieur\n<ol type=\"a\">\n<li>votre âme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔσωθεν</b>, <i>adv. :</i><br><b>      1</b> du dedans au dehors, HPC. <i>Art. 811, 812 ;</i> HDT. <i>7, 36 ; 8, 37 ;</i> ATT. ;<br><b>      2</b> en dedans, au dedans, HDT. <i>1, 181 ; 2, 36 ;</i> ESCHL. <i>Ag. 991 ; avec le gén</i>. EUR. <i>Cycl. 516</i>.<br><span><b>Étym</b>. ἔσω, -θεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσωθεν - ἔσωθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2082":"<h1>esoteros</h1>\n<p>Strong n° 2082 <i>Prononciation [es-o'-ter-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>intérieur\n<ol type=\"a\">\n<li>l'espace intérieur qui est derrière le voile</li>\n<li>le Sanctuaire, le Saint des Saints, les cieux par rapport au temple terrestre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐσώτερος, α, ον</b>, plus intérieur, plus intime, NT. <i>Ap. 16, 24</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εσωτερος - ἐσώτερος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2083":"<h1>hetairos</h1>\n<p>Strong n° 2083 <i>Prononciation [het-ah'-ee-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un camarade, un compagnon, un associé</li>\n<li>dit avec bonté :\n<ol type=\"a\">\n<li>ami, (mon bon ami), enfant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑταῖρος, ου (ὁ) :<br>A</b> <i>subst. :</i><br><b>   I</b> compagnon, compagnon d’un chef, compagnon d’armes, IL. <i>1, 179, etc. ;</i> compagnon de table, IL. <i>17, 577 ;</i> compagnon d’esclavage, OD. <i>14, 407, etc. ; avec un gén</i>. δαιτὸς ἑτ. HH. <i>Merc. 436,</i> compagnon de repas ; νυκτὸς ἑτ. HH. <i>Merc. 290,</i> compagnon <i>ou</i> associé de la nuit (qui lui permet de faire des vols) ; <i>fig</i>. ἐσθλὸς ἑτ. OD. <i>11, 7, etc</i>. bon compagnon, <i>en parl. d’un bon vent ;</i> γέλως ἑτ. ὕϐρεως, PLUT. <i>M. 622</i> b, le rire, compagnon de la moquerie ; <i>particul. :</i><br><b>      1</b> disciple d’un maître, ARSTT. <i>Metaph. 1, 4, 9 (Démocrite</i> ἑτ. <i>de Leucippe) ; au plur. en parl. des disciples de Socrate etc</i>. XÉN. <i>Mem. 2, 8, 1, etc. ;</i> ARSTT. <i>Pol. 2, 12, 7 ;</i> PLUT. <i>M. 67</i> d, <i>etc. ;</i><br><b>      2</b> adhérents d’un parti politique, partisans, LYS. <i>124, 14 ;</i> DÉM. <i>521, 12 ;</i><br><b>      3</b> hétaïres, <i>gardes à cheval des rois de Macédoine,</i> POL. (ATH. <i>194</i> e) ; POL. <i>5, 53, 4 ;</i> DS. <i>17, 37 ;</i><br><b>   II</b> <i>dans la conversation :</i> ἑταῖρε, IL. <i>1, 179, etc. ;</i> OD. <i>13, 266 ;</i> PLAT. <i>Gorg. 473</i> a ; ὦ 'ταῖρε, AR. <i>Vesp. 1239 ;</i> φίλ' ἑταῖρε, THGN. <i>751 ;</i> ὦ φίλε ἑταῖρε, PLAT. <i>Gorg. 482</i> a, mon ami, mon bon ami ;<br><b>   III</b> amant, SIM. AM. <i>fr. 7, 49 ;</i> AR. <i>Eccl. 913 ;</i><br><b>B</b> <i>adj. :</i><br><b>   I</b> compagnon <i>ou</i> compagne de, <i>joint à</i> ἀνήρ, OD. <i>8, 584 ;</i> HDT. <i>3, 95 ;</i> ANT. <i>113, 24 ;</i> σαργῶν γένος πέτρῃσιν ἑταῖρον, OPP. <i>H. 4, 267,</i> la race des sargues aime les rochers ; <i>fig</i>. τὸ ἐπιθυμητικὸν ἡδονῶν ἑταῖρον, PLAT. <i>Rsp. 439</i> d, le désir est le compagnon des plaisirs ;<br><b>   II</b> qui vit en troupe <i>ou</i> par bandes, <i>en parl. d’animaux,</i> OPP. <i>C. 2, 325</i>.<br><span>•<i> Sup</i>. -ότατος, PLAT. <i>Gorg. 487</i> d, <i>Phæd. 89</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. ἕταρος <span>[ᾰ]</span> IL. <i>3, 27, etc. ;</i> OD. <i>1, 6, etc. ;</i> ESCHL. <i>Pers. 990 ;</i> ANTH. <i>7, 470</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *se-, <i>cf</i>. ἕ, <i>avec élargissement</i> -t- ; <i>cf</i>. ἔτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εταιρος - ἑταῖρος</font>\n<br><br>vient de 'etes' (homme du clan)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (4)</li>\n</ul>\n</td></tr>\n</table>","G2084":"<h1>heteroglossos</h1>\n<p>Strong n° 2084 <i>Prononciation [het-er-og'-loce-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui parle un langage étranger</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτερό·γλωσσος</b>, <i>att</i>. <b>-ωττος, ος, ον</b>, qui parle une autre langue, POL. <i>24, 9, 5 ;</i> STR. <i>333 ;</i> NT. <i>1Cor. 14, 21</i>.<br><span><b>Étym</b>. ἕ. γλῶσσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετερογλωσσος - ἑτερόγλωσσος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2085":"<h1>heterodidaskaleo</h1>\n<p>Strong n° 2085 <i>Prononciation [het-er-od-id-as-kal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enseigner des doctrines autres ou différentes\n<ol type=\"a\">\n<li>déviation de la vérité</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτερο·διδασκαλέω-ῶ</b> <span>[ῐκᾰ]</span> enseigner une autre (<i>càd</i>. une fausse) doctrine, NT. <i>1Tim. 1, 3</i>.<br><span><b>Étym</b>. ἕ. διδάσκαλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετεροδιδασκαλεω - ἑτεροδιδασκαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G2086":"<h1>heterozugeo</h1>\n<p>Strong n° 2086 <i>Prononciation [het-er-od-zoog-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir sous un joug déséquilibré, être inégalement attelé\n<ol type=\"a\">\n<li>avoir des relations d'amitiés avec quelqu'un de différent : <a class=\"ref\" data-r=\"2CO6.14\">2 Corinthiens 6.14</a> où l'apôtre interdit aux chrétiens leur liaison avec des idolâtres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτεροζυγέω-ῶ</b> <span>[ῠ]</span> tirer le joug d’un autre côté que son compagnon ; <i>fig</i>. contracter une alliance mal assortie : τινι, NT. <i>2Cor. 6, 14,</i> avec qqn.<br><span><b>Étym</b>. ἑτερόζυγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετεροζυγεω - ἑτεροζυγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2087":"<h1>heteros</h1>\n<p>Strong n° 2087 <i>Prononciation [het'-er-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'autre, un autre, autre\n<ol type=\"a\">\n<li>énumérer\n<ol>\n<li>énumérer en comparaison à quelque personne ou chose</li>\n<li>l'autre de deux</li>\n</ol>\n</li>\n<li>qualifier\n<ol>\n<li>un autre : pas de la même nature, forme, classe, genre, différent</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἕτερος, α</b> <span>[ᾱ]</span>, <b>ον :<br>   I</b> autre, <i>en parl. de deux, càd. :</i><br><b>      1</b> l’un des deux <i>ou</i> l’autre des deux, <i>en parl. des organes doubles :</i> χειρὶ ἑτέρῃ, IL. <i>12, 452,</i> OD. <i>10, 171,</i> de l’une des deux mains <i>d’ord</i>. la gauche, IL. <i>18, 477 ;</i> OD. <i>19, 481 ;</i> THCR. <i>Idyl. 24, 25</i>) ; ἡ ἑτέρα (τῶν γνάθων) XÉN. <i>Eq. 1, 9,</i> l’une des deux mâchoires ; ὁ ἕτ. τῶν ὀφθαλμῶν, DH. <i>5, 23,</i> l’un des deux yeux ; <i>en gén. en parl. de pers. ou de choses au nombre de deux :</i> ὁ ἕτ. τῶν στρατηγῶν, THC. <i>4, 43,</i> l’un des deux généraux ; δυοῖν ἀγαθοῖν τὸ ἕτ. THC. <i>4, 28,</i> de deux biens l’un ; <i>p. opp. à</i> εἷς, μία, ἕν, LUC. <i>Bacch. 2 ;</i> M. ANT. <i>5, 9 ;</i> ANTH. <i>9, 680 ;</i> DYSC. <i>Synt. p. 172, 5 ;</i> GAL. <i>12, 474, 587, etc. ; particul. dans les loc. formées avec le neutre :</i> θάτερον <span>[ᾱ]</span> <i>contr. p</i>. τὸ ἕτερον (<i>gén</i>. θἀτέρου <i>ou</i> θατέρου, <i>dat</i>. θἀτέρῳ <i>ou</i> θατέρῳ ; <i>pl</i>. θάτερα, <i>contr. p</i>. τὰ ἕτερα) l’un des deux : δυοῖν θάτερον ἢ… ἤ, PLAT. <i>Theæt. 187</i> b, <i>etc</i>. de deux choses l’une, ou… ou ; ἑλοῦ γε θάτερ' ἢ… ἤ, SOPH. <i>El. 345,</i> choisis donc l’un des deux partis, ou… ou ; ἐπὶ θάτερα, HPC. <i>783</i> d ; PLAT. <i>Soph. 259</i> c, d’un côté, de l’autre (<i>v. ci-dessous</i>) ; ἐκ τοῦ ἐπὶ θάτερα, THC. <i>7, 37,</i> en venant de l’autre côté ; τἀπὶ θάτερα, XÉN. <i>Hell. 3, 7, 4,</i> de l’autre côté ; ἐς τὰ ἐπὶ θάτερα, THC. <i>1, 87,</i> de l’autre côté ; <i>avec le gén. :</i> ἐς τὰ ἐπὶ θάτερα τοῦ ποταμοῦ, THC. <i>7, 84 ;</i> εἰς τἀπὶ θ. τῆς πόλεως, XÉN. <i>Hell. 6, 2, 7,</i> de l’autre côté du fleuve, de la ville ; <i>p. opp. à un premier terme,</i> l’autre des deux : ἢ θάτερον… ἢ θάτερον, EUR. <i>Ion 849,</i> ou l’une… ou l’autre (des deux choses) ; ἐπὶ θάτερα μὲν…, ἐπὶ θάτερα δέ, HPC. <i>783</i> d, d’un côté…, de l’autre ; ἐκ μὲν τοῦ ἐπὶ θάτερα, ἐκ δὲ τοῦ ἐπὶ θάτερα, PLAT. <i>Prot. 315</i> a, d’un côté, de l’autre ; <i>au plur</i>. οἱ ἕτεροι, les uns ou les autres de deux groupes, IL. <i>4, 306 ; 20, 210, etc. ; p. opp. à un autre</i> (ἕτερος <i>ou</i> ἄλλος) : ἕτ. … ἕτ. IL. <i>3, 103 ; 16, 250 ;</i> ἕτ. μὲν… ἕτ. δέ, IL. <i>14, 272 ;</i> ἕτ. μὲν… ὁ δὲ ἕτ. IL. <i>21, 164,</i> ὁ ἕτ… ἕτ. δέ, OD. <i>5, 265 ;</i> ὁ μὲν… ὁ δ' ἕτ. IL. <i>22, 149 ;</i> ὁ μὲν… ὁ δὲ ἕτερος, CIA. <i>4, b, 27, b, 51 (439 av. J.C., v. Meisterh. p. 209, 5) ; ou sans</i> ὁ μέν : δύο σφραγῖδε λιθίνω, χρυσοῦν ἔχουσα τὸν δακτύλιον, ἡ δ' ἑτέρα ἀργυροῦν, CIA. <i>2, 652, a, 45 (398 av. J.C.)</i> deux sceaux de pierre ayant l’anneau (l’un) en or, l’autre en argent ; <i>de même</i> ἕτ. … ὁ δέ, OD. <i>8, 374 ; 20, 132 ;</i> ἕτ. μὲν… ἄλλος δέ, IL. <i>9, 313, 472, etc. ;</i> ἄλλος… ἕτ. IL. <i>13, 731 ;</i> ὁ ἕτ. … ὁ λοιπός, XÉN. <i>An. 4, 1, 23 ;</i> καὶ τῇδε… χἀτέρᾳ, SOPH. <i>O.C. 1444</i> (que ces choses arrivent) de cette façon ou de l’autre, <i>càd</i>. (tournent) bien ou mal ; τότε μὲν ἕτερος, ἄλλοτε δὲ ἄλλος, PLAT. <i>Epin. 982</i> c, <i>1 Alc. 116</i> e, tantôt l’un, tantôt l’autre ; <i>souv. opposé dans une même prop. :</i> ἐξ ἑτέρων ἕτερ' ἐστίν, OD. <i>17, 266,</i> l’une des choses dépend de l’autre ; ἕτεροι ἑτέρων ἄρχουσι, THC. <i>2, 64</i>. l’un commande à l’autre ; ἕτ. ἀφ' ἑτέρου ἔθνῃσκον, THC. <i>2, 51,</i> ils mouraient l’un après l’autre ; <i>en un sens réciproque :</i> ὁ ἕτ. τὸν ἕτερον παίει, XÉN. <i>An. 5, 9, 5,</i> ils se frappent l’un l’autre ; ἕτερα ἑτέροις ἐστὶν ἡδέα, ARSTT. <i>Nic. 3, 1,</i> les uns se plaisent à une chose, les autres à une autre ;<br><b>      2</b> <i>dans une énumération,</i> le second : ἡ μὲν… ἡ δ' ἡτέρη (<i>ion</i>.) …, ἡ δὲ τρίτη, OD. <i>10, 352,</i> la première, la seconde, la troisième ; <i>cf. 13, 67 ;</i> IL. <i>12, 93 ;</i> HDT. <i>7, 57 ;</i> XÉN. <i>Cyr. 2, 3, 22 ;</i> ἡ ἑτέρα (<i>s.-e</i>. ἡμέρα) le second jour ensuite, <i>càd</i>. le surlendemain, XÉN. <i>Cyr. 4, 6, 10 ; ou</i> le lendemain, SOPH. <i>O.R. 782 ;</i> EUR. <i>Rhes. 449 ;</i><br><b>      3</b> <i>p. suite,</i> un autre semblable <i>ou</i> analogue, <i>d’ord. avec</i> τοιοῦτος, τοσοῦτος, <i>etc., ou un nom de nombre :</i> τοιοῦτος ἕτερος, HDT. <i>3, 47 ;</i> PLAT. <i>Phæd. 58</i> d, <i>etc. ; ou</i> ἕτερος τοιοῦτος, PLAT. <i>Gorg. 493</i> b, <i>Lach. 200</i> a, <i>etc</i>. un autre du même genre ; ἕτ. τοιαῦτα, HDT. <i>1, 120, etc</i>. d’autres choses du même genre ; τόσσοι δ' αὖθ' ἕτεροι, HÉS. <i>Th. 367,</i> d’autres en aussi grand nombre ; ἑτέρου τοσούτου χρόνου, ISOCR. <i>72</i> d, encore pour autant de temps : δεύτερος, τρίτος ἕτ. DÉM. <i>643, 18 ; 644, 171, etc</i>. encore un second, un troisième, <i>etc. ;</i> ἕτ. αὐτοί, ARSTT. <i>Nic. 8, 12, 13,</i> d’autres eux-mêmes ; <i>avec</i> ἄττα (<i>cf</i>. ἄλλ' ἄττα) : ἕτερ' ἄττα, PLAT. <i>Theæt. 188</i> b ; LUC. <i>Pseud. 10 ;</i> M. TYR. <i>17, 1, 313,</i> quelques autres choses ;<br><b>      4</b> <i>p. ext</i>. autre, <i>en gén. avec</i> τις : ταῦτ' οὖν καὶ ἕτερός τις ὑμῶν πέπονθεν, οὐ μόνος ἐγώ, PLAT. <i>Rsp. 345</i> b, cela donc n’importe lequel d’entre vous l’a éprouvé, non moi seul ; <i>en ce sens souv. joint à</i> ἄλλος : ἕτερος ἄλλος, EUR. <i>Suppl. 573 ;</i> ἄλλος ἕτερος, EUR. <i>Or. 346 ;</i> PLAT. <i>Crat. 438</i> d ; DÉM. <i>198, 21,</i> un autre ; οἷος οὐχ ἕτερος, THC. <i>1, 23 ; 7, 20,</i> comme pas un autre ; ἑτέρᾳ (<i>s.-e</i>. ὁδῷ) SOPH. <i>O.C. 1444 ;</i> AR. <i>Nub. 812,</i> dans un autre sens ; ἑτέραν ἐκτρέπεσθαι, LUC. <i>Tim. 5,</i> se détourner par un autre chemin ;<br><b>   II</b> autre, <i>càd. :</i><br><b>      1</b> différent, contraire, opposé : ὅς χ' ἕτερον μὲν κεύθῃ ἐνὶ φρεσὶν ἄλλο δὲ εἴπῃ, IL. <i>9, 313,</i> celui qui pense une chose au fond de son cœur et qui en dit une autre ; ἕτερα μὲν λέγειν, ἕτερα δὲ φρονεῖν, DIN. <i>96, 14,</i> dire une chose et en penser une autre, dire le contraire de ce qu’on pense ; τὰ ἕτερα τῷ εἴδει, ARSTT. <i>Nic. 10, 4,</i> les choses d’autre sorte, <i>càd</i>. d’espèce différente ; <i>adv</i>., ἕτερα μὲν ὁ πούς, ἕτερα δὲ ὁ ῥυθμός, LUC. <i>Salt. 80,</i> autre chose est le pied, autre chose le rythme ; <i>avec le gén</i>. autre que, PLAT. <i>Prot. 333</i> a ; DÉM. <i>142, 26 ;</i> φίλους ἑτ. τῶν νῦν ὄντων, THC. <i>1, 28,</i> des amis tout autres que ceux d’aujourd’hui ; <i>avec le dat</i>. ὁ ἐμὸς πατὴρ τῷ σῷ πατρὶ ἤτοι ἕτερός ἐστιν ἢ ὁ αὐτός, DL. <i>3, 53,</i> mon père est ou autre que le tien ou le même que le tien ; <i>avec</i> ἤ, HDT. SOPH. <i>Tr. 835 ;</i> EUR. <i>Or. 346,</i> autre que ; <i>avec</i> ἀλλ' ἤ : οὐδὲν ἕτερον ἀλλ' ἤ, HDN <i>3, 10, 12,</i> rien autre chose que, <i>etc. ; avec</i> παρά <i>et l’acc</i>. XÉN. <i>Cyr. 1, 6, 2 ;</i> PLAT. <i>Phæd. 74</i> a ; ARSTT. <i>Pol. 4, 8, 10,</i> différent en comparaison de ; <i>avec</i> καί : ἕτερα φρονῶν καὶ δημηγορῶν, DIN. <i>92, 23,</i> disant au peuple le contraire de ce qu’il pense ;<br><b>      2</b> <i>abs</i>. autre qu’il ne faudrait, <i>càd</i>. mauvais, <i>par euphém. p. opp. à</i> ἀγαθός, DÉM. <i>597, 3 ; à</i> εὖ : παθεῖν μὲν εὖ, παθεῖν δὲ θάτερα, SOPH. <i>Ph. 503,</i> être bien traité ou au contraire ; <i>cf</i>. PD. <i>P. 3, 62 ;</i> ESCHL. <i>Ag. 151 ;</i> EUR. <i>Med. 639</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém. ion</i>. ἑτέρη, THCR. <i>Idyl. 22, 120 ; gén. masc. dor</i>. ἑτέρω, THCR. <i>Idyl. 29, 15 ; dat. fém. poét. au sens instrumental,</i> ἑτέρηφι, IL. <i>16, 734 ; 18, 477 ; 22, 80 ;</i> THCR. <i>Idyl. 25, 207 et 253 ; dat. fém. éol</i>. ἐτέρᾳ, THCR. <i>Idyl. 30, 20 (ms</i>. ἑ) — <i>Crases :</i> ὁ ἕτερος = <i>att</i>. ἅτερος <span>[ᾱ]</span> SOPH. <i>Aj. 1109, El. 739 ;</i> AR. <i>Vesp. 138 ;</i> PLAT. <i>Leg. 695</i> b, <i>etc. ; ion</i>. οὕτερος, HDT. <i>1, 34, 134 ; dor</i>. ὥτερος, THCR. <i>Idyl. 7, 36 ; 8, 90 ;</i> ἡ ἑτέρα = <i>att</i>. ἁτέρα <i>ou</i> ἡτέρα, SOPH. <i>O.C. 497 ;</i> AR. <i>Lys. 85, 90 ; dans les inscr. att</i>. ἡτέρα, CIA. <i>2, 742, a, 14 (350/300 av. J.C.), etc. ; à côté de</i> ἡ ἑτέρα, CIA. <i>2, 797, c, 24 (353/349 av. J.C.) etc., v. Meisterh. p. 55, 3 ;</i> τὸ ἕτερον = <i>att</i>. θάτερον, PLAT. <i>Phæd. 114</i> e ; <i>dans une inscr. att</i>. τὸ ἕτερον, CIA. <i>2, 798, c, 19 (après 357 av. J.C.) ; v. Meisterh. p. 55, 3, note 501 ; ion</i>. θάτερον, HPC. <i>802</i> c ; <i>ou</i> τοὔτερον, HDT. <i>1, 1, 32 ; dor</i>. θώτερον, THCR. <i>Idyl. 11, 32. Gén</i>. τοῦ ἑτέρου = <i>att</i>. θατέρου, ARSTT. <i>Mund. 3 ; ion</i>. τοὐτέρου, SIM. AM. <i>fr. 7, 113 ; dor</i>. θατέρω, T. LOCR. <i>94</i> a ; PLUT. <i>Lyc. 19 ; ou</i> θωτέρω, EPICH. (ATH. <i>282</i> e). <i>Dat</i>. τῷ ἑτέρῳ = <i>att</i>. θατέρῳ, ESCHL. <i>Pr. 778 ;</i> AR. <i>Eccl. 498, Vesp. 497 ;</i> τῇ ἑτέρᾳ = <i>att</i>. θατέρᾳ, SOPH. <i>O.R. 782, Tr. 272 ;</i> EUR. <i>Rhes. 449 (var</i>. θητέρᾳ<i>) ; ion</i>. τἠτέρῃ, PHŒN. COL. (ATH. <i>495</i> e) ; ARCHIL. (PLUT. <i>Demetr. 35). Plur</i>. οἱ ἕτεροι = ἅτεροι, ARSTT. <i>Pol. 1, 6, 4 ; neutre</i> τὰ ἕτερα = θάτερα, THC. <i>1, 87 ;</i> XÉN. <i>Hell. 3, 7, 4 ;</i> SOPH. <i>El. 345, Ph. 503 ;</i> PLAT. <i>Phil. 43</i> e, <i>Theæt. 187</i> b, <i>Prot. 315</i> a, <i>etc. — Postér. nom. sg</i>. θάτερος (<i>incorr. p</i>. ἅτερος) <i>formé d’après le neutre</i> θάτερον, LYC. <i>590, blâmé par</i> TH. MAG. (<i>cf</i>. LUC. <i>Pseud. 29). Crases avec</i> καί : χἄτερος, <i>inscr. att. dans</i> KV. <i>124 (v. Meisterh. p. 56, 4) ;</i> χἀτέρᾳ = καὶ ἑτέρᾳ, SOPH. <i>O.C. 1444 ;</i> χἀτέρους, EUR. <i>Suppl. 573 ; crase éol</i>. χἄτερα, THCR. <i>Idyl. 30, 25</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *sm-tero-, un des deux, <i>cf</i>. εἷς ; <i>suff. du comp</i>. -τερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετερος - ἕτερος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> comparé à  dénote un nombre qui distingue de différences qualitatives ;  ajoute ('un en outre'),  distingue ('un des deux') ; chaque  est un , mais tous les  ne sont pas un ;  dénote généralement une simple distinction entre des individus,  implique l'idée secondaire de différence de genre.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n99 fois dans 94 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (33)</li>\n<li>Jean (1)</li>\n<li>Actes (18)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (12)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (2)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2088":"<h1>heteros</h1>\n<p>Strong n° 2088 <i>Prononciation [het-er'-oce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>autrement, différemment, d'une autre manière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτέρως</b>, <i>adv. :</i><br><b>      1</b> de l’une <i>ou</i> de l’autre manière, <i>p. opp. à</i> ἀμφοτέρως, PLAT. <i>Theæt. 181</i> e, <i>Phædr. 235</i> a ;<br><b>      2</b> autrement, d’une autre manière, AR. <i>Pl. 371 ;</i> PLAT. <i>Leg. 891</i> d ; ἑτ. πως, PLAT. <i>Leg. 897</i> b, <i>etc</i>. de qqe autre manière ; autrement que, <i>avec le gén</i>. PLAT. <i>Pol. 295</i> d ; <i>ou avec</i> ἤπερ, EL. <i>N.A. 12, 28 ;</i> ὡς ἑτ. HPC. <i>800</i> d ; PLAT. <i>Soph. 266</i> a ; DÉM. <i>298, 22 ;</i> ARSTT. <i>Soph. el. 7 ;</i> JOS. <i>A.J. 7, 7, 2,</i> de qqe autre manière ;<br><b>      3</b> <i>particul. en mauv. part,</i> autrement qu’il ne convient, <i>càd</i>. mal, OD. <i>1, 234 (var</i>. ἑτέρωσε) ; <i>p. opp. à</i> καλῶς, DÉM. <i>254, 7</i>.<br><span><b>Étym</b>. ἕτερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετερως - ἑτέρως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2089":"<h1>eti</h1>\n<p>Strong n° 2089 <i>Prononciation [et'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>encore, cependant\n<ol type=\"a\">\n<li>du temps\n<ol>\n<li>d'une chose qui provient d'autrefois, ce qui est d'un état de choses différent de ce qui existe ou a existé</li>\n<li>d'une chose qui continue dans le présent\n<ol type=\"a\">\n<li>même, maintenant</li>\n</ol>\n</li>\n<li>avec le négatif\n<ol type=\"a\">\n<li>pas plus longtemps, ne plus</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>degré et accroissement\n<ol>\n<li>même, néanmoins</li>\n<li>en outre, plus de, plus loin, davantage</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔτι</b> <span>[ῐ]</span> <i>adv. :</i><br><b>   I</b> encore, <i>avec idée de temps :</i><br><b>      1</b> <i>au prés</i>. ἔτι μοι μένος ἐμπεδόν ἐστιν, IL. <i>5, 254,</i> j’ai encore un cœur ferme ; εἰ Ζεὺς ἔτι Ζεύς, SOPH. <i>O.C. 623,</i> si Zeus est encore Zeus ; νῦν ἔτι, ESCHL. <i>Sept. 708, Ag. 818 ;</i> SOPH. <i>Ph. 950,</i> encore maintenant ; ἔτι καὶ νῦν, IL. <i>1, 455 ;</i> ἔτι καὶ νυνί, PLAT. <i>Conv. 215</i> a, même encore à présent ; ἔτι δὲ καί, SOPH. <i>O.R. 1345,</i> maintenant enfin ; <i>avec une nég</i>. οὐκ ἔτι (<i>v</i>. οὐκέτι) IL. <i>2, 13 ;</i> OD. <i>9, 350 ; 11, 455 ; ou invers</i>. ἔτι οὐκ, SOPH. <i>O.R. 24, Tr. 161 ;</i> A. RH. <i>2, 28,</i> ne… plus ; οὐδέν εἰμ' ἔτι, SOPH. <i>El. 677, etc. ;</i> EUR. <i>Hel. 1194,</i> je ne suis plus rien, je suis perdu (<i>cf</i>. οὐκέτι) ; <i>qqf. ajouté à</i> οὐκέτι : οὐκέτι… ἔτι, PD. <i>N. 9, 47 ;</i> SOPH. <i>Ph. 1133,</i> ne… plus ;<br><b>      2</b> <i>au passé :</i> ἔτι καὶ δὴ ἐμάχοντο, HDT. <i>9, 102,</i> ils combattaient même encore en ce moment ; <i>avec une nég</i>. οὐκ ἔτι, THC. <i>7, 81 ;</i> LUC. <i>Pisc. 3,</i> ne… plus ; οὐδ' ἔτι δὴν ἦν, IL. <i>6, 139,</i> et il ne vécut plus longtemps ;<br><b>      3</b> <i>au fut</i>. encore dans la suite, IL. <i>1, 96, etc. ;</i> OD. <i>2, 230, etc. ; <i>ou</i> simpl</i>. un jour, dans l’avenir, <i>au sens du lat</i>. olim, SOPH. <i>Aj. 607 ;</i><br><b>   II</b> tout de suite, aussitôt : ἔτ' ἐκ βρέφεος, ANTH. <i>9, 567,</i> dès la plus tendre enfance (<i>litt</i>. tout de suite dès l’enfance) ; <i>cf</i>. JAMBL. <i>V. Pyth. 29 ; en ce sens, souv. après</i> ἐξ : ἐξ ἔτι πατρῶν, OD. <i>8, 245,</i> dès (le temps de) nos pères ; ἐξ ἔτι τοῦ ὅτε, IL. <i>9, 106,</i> depuis le temps que, <i>etc. ;</i> ἐξ ἔτι νεαροῦ, EL. <i>N.A. 5, 39,</i> dès le jeune âge ;<br><b>   III</b> <i>p. suite,</i> dès lors, alors : πικρὰν δοκῶ με πεῖραν τήνδε τολμήσειν ἔτι, SOPH. <i>El. 471,</i> je crois bien que l’expérience que j’ose tenter me deviendrait dès lors amère ; <i>cf</i>. SOPH. <i>El. 66, Tr. 257 ;</i><br><b>   IV</b> encore, en outre, de plus : ἕτερόν γ' ἔτι, OD. <i>14, 325, etc. ;</i> ἔτ' ἄλλος, HÉS. <i>O. 156 ;</i> ESCHL. <i>Ch. 114,</i> encore un autre ; ἔτι δέ, XÉN. <i>Cyr. 1, 2, 9, etc. ;</i> PLAT. <i>Phædr. 279</i> a ; καὶ ἔτι, ARR. (STOB. <i>Fl. 80, 14, vol. 3, p. 108, l. 14</i>) ; THÉMISTOCLE <i>Ep. 6, p. 22 ;</i> DYSC. <i>Synt. 123, 5, etc. ;</i> καὶ ἔτι γε, ARSTD. <i>t. 1, 18 ;</i> ἔτι καί, PLAT. <i>Soph. 239</i> d ; ARSTT. <i>Probl. 4, 17 ;</i> PAUS. <i>10, 3, 2 ;</i> GAL. <i>4, 250 ;</i> ἔτι δὲ καί, THC. <i>1, 80,</i> et en outre, et de plus ; <i>comme dernier terme d’une énumérat. :</i> πρῶτον μὲν…, ἔπειτα δὲ…, ἔτι δέ, XÉN. <i>An. 6, 4, 13,</i> d’abord…, et ensuite…, et en outre ; <i>avec un compar</i>. ESCHL. <i>Pr. 987 ;</i> SOPH. <i>O.R. 272, etc. ;</i> ἔτι μᾶλλον, IL. <i>14, 97, etc. ;</i> μᾶλλον ἔτι, OD. <i>18, 22 ;</i> ἔτι πλέον, HDT. <i>7, 6 ;</i> THC. <i>1, 80,</i> encore plus ; <i>avec un adv. au pos</i>. ἔτι ἄνω, XÉN. <i>An. 7, 5, 91,</i> encore plus haut ; ἔτι μάλα, AR. <i>Pax 53, 462 ; Ran. 864,</i> encore plus.<br><span><b><span class=\"arrow\"></span></b> <span>[ῑ]</span> <i>une fois à l’arsis,</i> IL. <i>6, 139, et devant</i> δήν <i>et</i> δηρόν (<i>v. ces mots). — Crase : att</i>. κἄτι, ESCHL. <i>Pr. 987, etc. ; ion</i>. κἤτι, CALL. <i>Ep. 55</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *h₁eti, (et) aussi ; <i>cf. lat</i>. et, <i>sscr</i>. áti.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετι - ἔτι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n119 fois dans 102 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (7)</li>\n<li>Luc (19)</li>\n<li>Jean (15)</li>\n<li>Actes (5)</li>\n<li>Romains (14)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (7)</li>\n<li>Philippiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (14)</li>\n<li>Apocalypse (22)</li>\n</li>\n</ul>\n</td></tr>\n</table>","G2090":"<h1>hetoimazo</h1>\n<p>Strong n° 2090 <i>Prononciation [het-oy-mad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre prêt, préparer\n<ol type=\"a\">\n<li>faire les préparations nécessaires, tenir chaque chose prête</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>désigne la coutume orientale d'envoyer des gens devant les rois en voyage pour évaluer les routes et les rendre praticables</li>\n<li>préparer les esprits des hommes pour leur donner une bonne perception du Messie et les rassurer sur les bénédictions</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτοιμάζω</b> <span>(<i>impf</i>. ἡτοίμαζον, <i>f</i>. ἑτοιμάσω, <i>ao</i>. ἡτοίμασα, <i>pf</i>. ἡτοίμακα ; <i>pf. pass</i>. ἡτοίμασμαι)</span> préparer, disposer, <i>acc</i>. IL. <i>1, 118 ;</i> HDT. <i>6, 95 ;</i> SOPH. <i>Tr. 362 ;</i> EUR. <i>Alc. 364, etc. ; avec un inf</i>. κάπρον ἑτ. ταμέειν, IL. <i>19, 197,</i> préparer un sanglier pour l’immoler ;<br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἡτοιμασάμην)</span><br><b>      1 <i>tr.</i></b> préparer pour soi, <i>acc</i>. THC. <i>1, 58 ; 4, 77 ;</i> XÉN. <i>Cyr. 3, 3, 5 ;</i> DÉM. <i>690, 8 ; d’où</i> préparer, <i>en gén., acc</i>. IL. <i>10, 571 ; 13, 184 ;</i><br><b>      2 <i>intr.</i></b> se tenir prêt, se préparer : πρός τι, POL. <i>3, 105, 11,</i> à qqe ch. ; <i>avec l’inf</i>. XÉN. <i>Ap. 8,</i> à faire qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. réc</i>. ἡτοίμακα, POL. <i>3, 72, 6. Ao. moy. 3 pl. ion</i>. ἑτοιμάσσαντο, OD. <i>13, 184 ; opt. 3 pl. épq</i>. ἑτοιμασσαίατο, IL. <i>10, 571</i>.<br><span><b>Étym</b>. ἕτοιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετοιμαζω - ἑτοιμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n40 fois dans 40 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (14)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G2091":"<h1>hetoimasia</h1>\n<p>Strong n° 2091 <i>Prononciation [het-oy-mas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action de préparation, le fait d'être prêt</li>\n<li>la condition d'une personne ou d'une chose qui est préparée, prête disponibilité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτοιμασία, ας (ἡ)</b> <span>[μᾰ]</span><br><b>      1</b> <i>intr</i>. préparation, apprêt, SPT. <i>Ps. 9, 41, etc. ;</i><br><b>      2</b> diligence, promptitude, JOS. <i>A.J. 10, 1, 2 ;</i> πρός τι, HPC. <i>24, 47,</i> en vue de qqe ch.<br><span><b>Étym</b>. ἑτοιμάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετοιμασια - ἑτοιμασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2092":"<h1>hetoimos</h1>\n<p>Strong n° 2092 <i>Prononciation [het-oy'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>préparer à être prêt\n<ol type=\"a\">\n<li>de choses\n<ol>\n<li>sous la main</li>\n<li>opportun, de saison</li>\n</ol>\n</li>\n<li>de personnes\n<ol>\n<li>prêtes\n<ol type=\"a\">\n<li>à faire quelque chose</li>\n<li>à recevoir une venue</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἕτοιμος</b> (<i>épq., lyr., ion. et anc. att</i>. ἑτοῖμος), <b>ος</b> <i>ou</i> <b>η, ον :<br>   I</b> <i>pass</i>. réel, effectif, <i>d’où :</i><br><b>      1</b> réalisé, IL. <i>9, 425 ;</i><br><b>      2</b> qui est sur le point d’être réalisé, imminent, PLUT. <i>M. 706</i> c ;<br><b>      3</b> qui peut-être réalisé, réalisable, sûr, certain, IL. <i>18, 96 ; p. suite,</i> qui est sous la main, dont on peut disposer, tout prêt, préparé : (κρέα) ἕτοιμα, HDT. <i>1, 190,</i> viandes toutes prêtes ; ἕτ. δαίς, THCR. <i>Idyl. 13, 63,</i> repas tout prêt ; ὡς ἑτοῖμα ἦν, THC. <i>2, 3,</i> quand tout fut prêt, <i>etc. ;</i> ἐν ἑτοίμῳ εἶναι, THCR. <i>Idyl. 22, 61,</i> être à la disposition de ; ἐν ἑτοίμῳ ἔχειν, POL. <i>2, 34, 2 ;</i> PLUT. <i>Sert. 11,</i> avoir à sa disposition ; ἕτοιμόν (ἐστι), cela est à portée, <i>càd</i>. est facile, PLAT. <i>Rsp. 567</i> a ; PAUS. <i>2, 23, 6 ;</i><br><b>   II</b> <i>act. :</i><br><b>      1</b> prêt à, disposé à : <i>avec un rég. de chose :</i> εἴς (<i>ion</i>. ἔς) τι, HDT. <i>8, 96 ;</i> DÉM. <i>1479, 24 ; 1481, 15 ;</i> πρός τι, XÉN. <i>Mem. 4, 5, 12,</i> prêt à qqe ch., à faire qqe ch. ; <i>avec un dat. de pers</i>. ἕ. τινι, PD. <i>N. 4, 74 ;</i> HDT. <i>1, 50, etc</i>. prêt à assister qqn, à lui venir en aide ; <i>avec un inf</i>. HDT. <i>1, 42, etc. ;</i> ESCHL. <i>Ag. 791 ;</i> SOPH. <i>El. 1079 ;</i> THC. <i>4, 61 ;</i> PLAT. <i>Conv. 207</i> b, prêt à faire qqe ch. ;<br><b>      2</b> <i>p. suite,</i> diligent, agile, alerte : ἐξ ἑτοίμου, ISOCR. <i>101</i> c, sans hésitation, immédiatement ; ἐξ ἐτ. ὑπακούειν, XÉN. <i>Œc. 14, 3,</i> obéir immédiatement ; ἐξ ἑτοιμοτάτου διώκειν, XÉN. <i>Cyr. 5, 3, 57,</i> poursuivre de toute la vitesse possible, avec la plus grande promptitude ;<br><b>      3</b> <i>p. ext</i>. prêt, décidé, résolu : γνώμη ἑτ. THC. <i>4, 123,</i> décision prise résolument ; τὸ ἕτ. ἔστιν, EUR. <i>Or. 1106,</i> j’y suis tout disposé ; τὸ ἕτ. τῆς γνώμης, PHILSTR. <i>706,</i> décision prise résolument.<br><span>•<i> Cp</i>. -ότερος, ESCHL. <i>Ch. 448 ;</i> THC. <i>4, 61 ;</i> ISOCR. <i>294</i> b. <i>• Sup</i>. -ότατος, XÉN. <i>Cyr. 5, 3, 57,</i> THCR. <i>Idyl. 13, 63 ;</i> ANTH. <i>10, 119 ; 11, 49</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἑτοίμη, IL. <i>9, 425 ;</i> EUR. <i>Her. 502 ;</i> PLAT. <i>Phædr. 25</i> a ; <i>fém. dor</i>. ἑτοίμα, SOPH. <i>El. 1079</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετοιμος - ἕτοιμος</font>\n<br><br>vient du vieux substantif 'heteos' (aptitude)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 17 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (3)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2093":"<h1>hetoimos</h1>\n<p>Strong n° 2093 <i>Prononciation [het'-oy-moce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>promptement, être prêt</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑτοίμως</b>, <i>adv. :</i><br><b>   I</b> en état de préparation : ἑτ. ἔχειν, DÉMAD. <i>179, 5,</i> être prêt ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> promptement, avec empressement, THC. <i>1, 80 ;</i> XÉN. <i>An. 2, 5, 2 ;</i><br><b>      2</b> évidemment, PLAT. <i>Hipp. ma. 300</i> c.<br><span>•<i> Cp</i>. -ότερον, IS. <i>47, 43 ;</i> PLUT. <i>M. 62</i> e ; <i>ou</i> -οτέρως, A. TR. <i>12, p. 237</i>. <i>• Sup</i>. -ότατα, PLAT. <i>Pol. 290</i> a ; GAL. <i>4, 79</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετοιμως - ἑτοίμως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2094":"<h1>etos</h1>\n<p>Strong n° 2094 <i>Prononciation [et'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>année, an</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἐτός</b>, <i>adv. seul. dans la locut</i>. οὐκ ἐτός, PLAT. <i>Rsp. 414</i> e, <i>568</i> a ; AR. <i>Pl. 1166, Av. 915, etc</i>. non sans raison ; <i>particul. dans les interr</i>. οὐκ ἐτὸς ἀρ' … ; <i>etc</i>. AR. <i>Pl. 404, etc</i>. alors c’était donc pour rien que, <i>etc</i>. ?.<br><span><b>Étym</b>. <i>cf</i>. ἐτώσιος.</span><br><br>\n➁ <b>ἔτος, εος-ους (τὸ)</b> an, année, IL. <i>11, 691, etc. ;</i> OD. <i>2, 89, etc. ;</i> HDT. <i>8, 65, etc. ;</i> PLAT. <i>Ap. 18</i> b, <i>etc. :</i> ἑκάστου ἔτους, PLAT. <i>Phæd. 58</i> b ; ἀν' ἕκαστον ἔτος, TH. <i>H.P. 4, 4, 4,</i> ἀνὰ πᾶν ἔ. ANTH. <i>9, 430 ;</i> κατὰ πᾶν ἔ. ARSTT. <i>Plant. 1, 4, 1 ; ou simpl</i>. κατὰ ἔτος, THC. <i>4, 53 ;</i> κατ' ἔτος, ANTH. <i>14, 42 ;</i> DS. <i>3, 2 ;</i> STR. <i>226,</i> chaque année ; ἔτος εἰς ἔτος, SOPH. <i>Ant. 340 ;</i> εἰς ἔτος ἐξ ἔτεος, THCR. <i>Idyl. 18, 15,</i> d’année en année ; <i>à l’acc</i>. ἔτος τόδ' ἤδη δέκατον… βόσκων, SOPH. <i>Ph. 312,</i> voici la dixième année que, <i>etc. ;</i> γεγονὼς ἔτη τρία ἀπολείποντα τῶν ἑκατόν, ISOCR. <i>283</i> c, âgé de 97 ans ; <i>avec le gén</i>. ἐπειδὰν ἐτῶν ᾖ τις τριάκοντα, PLAT. <i>Leg. 721</i> a, lorsque qqn est âgé de 30 ans ; <i>avec un n. de n. ordinal :</i> ἤδη γεγονὼς ἔτος πέμπτον καὶ ἑϐδομηκοστόν, DL. <i>4, 44,</i> âgé de 75 ans ; <i>sans verbe :</i> τοὺς ὑπὲρ τετταράκοντα ἔτη, XÉN. <i>An. 5, 3, 1,</i> ceux qui ont dépassé l’âge de trente ans ; οἱ μέχρι τριάκοντα ἐτῶν, XÉN. <i>An. 6, 4, 25,</i> ceux dont l’âge va jusqu’à trente ans.<br><span><b><span class=\"arrow\"></span></b> <i>On trouve dans des inscr. att. un ex. du dat. sg</i>. ἔτῃ = ἔτει, SD. <i>1059, 18 (321 avant J.C. ; v. Meisterh. p. 31, 10) ; et le dat. pl</i>. ἔτεσσι, CIA. <i>1, 273, h, 4 (pas av. 420 av. J.C.), ou</i> ἔτεσιν, <i>ibid. fr. f. 30, 36, 39 (v. Meisterh. p. 103, 51, 5</i>).<br><span><b>Étym</b>. <i>pour</i> ϝέτος, CIG. <i>11, 1569, etc. de indo-europ</i>. *uet-os-, an ; <i>cf. lat</i>. vetus, <i>sscr</i>. tri-vats-á- « de trois ans ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ετος - ἔτος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote une année en tant que cycle ou période de temps\n<br><br> – est une année considérée comme division ou portion de temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n49 fois dans 48 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (15)</li>\n<li>Jean (3)</li>\n<li>Actes (11)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (3)</li>\n<li>2 Pierre (2)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2095":"<h1>eu</h1>\n<p>Strong n° 2095 <i>Prononciation [yoo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être bien, aller bien, prospérer</li>\n<li>bien agir, faire bien</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὖ</b>, <i>épq</i>. <b>ἐΰ</b> <span>[ῡ <i>devant deux consonnes <i>ou</i> une consonne double</i>]</span>, <i>adv</i>., bien, <i>càd. ;</i><br><b>   I. 1</b> (<i>avec idée d’origine <i>ou</i> de condition</i>) noblement : ἄνδρες φύσει γεγονότες εὖ, HDT. <i>7, 134,</i> des hommes de bonne naissance, de noble origine ;<br><b>      2</b> bien, régulièrement, justement : <i>p. opp. à</i> κακῶς, THC. <i>4, 63 ; à</i> χεῖρον, THC. <i>2, 35 ;</i> εὖ καὶ ἐπισταμένως, IL. <i>10, 265,</i> bien et avec habileté ; νόμους… ἔχοντας εὖ, HDT. <i>3, 82,</i> des lois bien conçues ; <i>qqf. séparé du part. :</i> εὖ πρᾶγμα συντεθέν, DÉM. <i>275, 26,</i> affaire bien arrangée ; <i>abs</i>. εὖ κατὰ κόσμον, IL. <i>10, 472,</i> en bon ordre ; <i>subst</i>. τὸ εὖ, ESCHL. <i>Ag. 121 ;</i> SOPH. <i>Ph. 1140 ;</i> ARSTT. <i>Sens. 1, 8,</i> le bien, le bon droit, la bonne cause ;<br><b>      3</b> bien, avec bienveillance, avec bonté : εὖ ἔρδειν τινά, IL. <i>5, 650,</i> faire du bien à qqn ; εὖ εἰπεῖν τινα, OD. <i>1, 302,</i> dire du bien de qqn ;<br><b>      4</b> <i>p. suite, pour marquer une idée d’achèvement, de perfection, avec un verbe :</i> εὖ μήδεο, IL. <i>2, 360,</i> considère bien ; εὖ οἶδα, εὖ ἔγνωκα, ATT. je sais bien ; <i>en forme de parenthèse,</i> εὖ οἶδ' ὅτι, je sais bien : σὺ γάρ, εὖ οἶδ' ὅτι, οὐ πράγματ' ᾄσει, AR. <i>Pax 1296,</i> car pour toi, je le sais bien, tu ne crieras pas l’affaire sur les toits (<i>litt</i>. tu ne chanteras pas les affaires) ; <i>avec un adj. <i>ou</i> un adv</i>. εὖ πάντες, OD. <i>8, 37, 39,</i> tous sans exception ; εὖ πάντα, OD. <i>3, 72,</i> tout sans exception ; εὖ μάλα, OD. <i>4, 96 ;</i> HH. <i>Ap. 172 ;</i> PLAT. <i>Euthyphr. 4</i> a ; THCR. <i>Idyl. 5, 19 ;</i> εὖ καὶ μάλα, PLAT. <i>Conv. 194 ;</i> μάλ' εὖ, AR. <i>fr. 142 ;</i> PLAT. <i>Soph. 236</i> d, tout à fait ; κάρτα εὖ, HDT. <i>3, 150 ;</i> εὖ πάνυ, AR. <i>Pl. 198</i> πάνυ εὖ, PLAT. <i>Men. 80</i> a, tout à fait ; εὖ σαφῶς, ESCHL. <i>Pers. 784 ;</i> AR. <i>Pax 1302,</i> très évidemment ; <i>dans les réponses</i> εὖγε (<i>v</i>. εὖγε) ; εὖ κἀνδρικῶς, AR. <i>Eq. 379 ;</i> εὖ καὶ ἀνδρείως, PLAT. <i>Theæt. 157</i> d ; εὖ κἀνδρείως, AR. <i>Th. 656 ;</i> ἀνδρείως τε καὶ εὖ, PLAT. <i>Crat. 440</i> d, bien et virilement ; εὖ καὶ καλῶς, EL. <i>V.H. 2, 6 ;</i> εὖ τε καὶ καλῶς, PLAT. <i>Rsp. 503</i> d ; καλῶς τε καὶ εὖ, HDT. <i>1, 59 ;</i> PLAT. <i>Euthyd. 307</i> b ; EL. <i>N.A. 17, 16,</i> bel et bien ; <i>c. terme d’encouragement pour exciter des chiens :</i> εὖ κύνες, εὖ ὦ κύνες, XÉN. <i>Cyn. 6, 20,</i> bien les chiens ! allons ! bien les chiens ! ;<br><b>   II</b> heureusement : εὖ οἴκαδ' ἱκέσθαι, IL. <i>1, 18,</i> revenir heureusement chez soi ; εὖ ζῆν, ARSTT. <i>Pol. 7, 13,</i> vivre heureusement.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. ἐΰ, IL. <i>3, 235 ; 4, 408 ;</i> HÉS. <i>Th. 885</i>.<br><span><b>Étym</b>. <i>neutre de</i> ἐΰς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευ - εὖ</font>\n<br><br>vient du mot primaire 'eus' (bon)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2096":"<h1>Eua</h1>\n<p>Strong n° 2096 <i>Prononciation [yoo'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Eve = « vie »\n<ol><li>première femme des écritures, mère de la race humaine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Εὔα, ας (ἡ)</b> Ève, <i>n. de f. biblique,</i> SPT. <i>Gen. 3, 20 ; 4, 1 ;</i> NT. <i>2Cor. 11, 3 ; 1Tim. 2, 13</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ευα</font> &lt; חוה - <font face=\"Georgia\">Εὕα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2097":"<h1>euaggelizo</h1>\n<p>Strong n° 2097 <i>Prononciation [yoo-ang-ghel-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apporter de bonnes nouvelles, annoncer d'heureuses nouvelles\n<ol type=\"a\">\n<li>utilisé dans l'A.T. pour toute sorte de bonnes nouvelles\n<ol>\n<li>les joyeuses nouvelles de la bonté de Dieu, et surtout des bénédictions Messianiques</li>\n</ol>\n</li>\n<li>dans le N.T. c'est la bonne nouvelle de la venue du royaume de Dieu, et du salut obtenu à travers Christ, de qui dépend ce salut</li>\n<li>bonnes nouvelles apportées à quelqu'un, celui a qui sont annoncées les bonnes nouvelles</li>\n<li>proclamer, prêcher la bonne nouvelle\n<ol>\n<li>instruire les hommes au sujet de ce qui appartient au salut chrétien</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐαγγελίζω<br>   I</b> annoncer une bonne nouvelle, DC. <i>61, 13 ;</i><br><b>   II</b> <i>particul. t. eccl</i>. prêcher la bonne nouvelle, prêcher l’évangile, NT. <i>Luc. 4, 18 ; d’où au pass. :</i><br><b>      1</b> <i>avec un suj. de pers</i>. être évangélisé, recevoir la bonne nouvelle, NT. <i>Matth. 11, 5 ; Hebr. 4, 2 et 6 ;</i><br><b>      2</b> <i>en parl. de l’évangile,</i> être prêché, NT. <i>Luc. 16, 16 ; Gal. 1, 11 ;</i><br><b><i>Moy</i>. εὐαγγελίζομαι</b> <i>plus us</i>. <span>(<i>impf</i>. εὐηγγελιζόμην, <i>fut</i>. εὐαγγελιοῦμαι)</span> annoncer une bonne nouvelle : τί τινι, AR. <i>Eq. 643 ;</i> DÉM. <i>332, 9 ;</i> LYCURG. <i>150, 7 ;</i> τί τινα, ALCIPHR. <i>3, 12 ;</i> HLD. <i>2, 10,</i> annoncer qqe bonne nouvelle à qqn ; τινι ὅτι ; LUC. <i>Philops. 31,</i> annoncer à qqn la bonne nouvelle que, <i>etc. ; avec une prop. inf</i>. PLUT. <i>Mar. 22 ; particul. t. eccl</i>. prêcher la bonne nouvelle en annonçant : τὴν βασιλείαν τοῦ θεοῦ, NT. <i>Luc. 4, 43,</i> le royaume de Dieu ; <i>avec un acc. de pers</i>. prêcher l’évangile : τινα, NT. <i>Luc. 3, 18 ; Ap. 8, 25,</i> à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Pl.q.pf</i>. εὐηγγελίκειν, DC. <i>61, 13 ; pass. fut. part</i>. εὐαγγελιούμενος, LUC. <i>Ic. 34</i>.<br><span><b>Étym</b>. εὐαγγελία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαγγελιζω - εὐαγγελίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n60 fois dans 52 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (12)</li>\n<li>Actes (15)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (8)</li>\n<li>Ephésiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2098":"<h1>euaggelion</h1>\n<p>Strong n° 2098 <i>Prononciation [yoo-ang-ghel'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une récompense pour les bonnes nouvelles</li>\n<li>bonnes nouvelles\n<ol type=\"a\">\n<li>l'heureuse nouvelle du royaume de Dieu bientôt mis en place et aussi de Jésus le Messie, fondateur de ce royaume. Après la mort de Christ, le terme comprend aussi la prédication de Jésus Christ qui a souffert jusqu'à la mort sur la croix, pour procurer aux hommes le salut éternel dans le royaume de Dieu, qui est ressuscité des morts et qui est monté au ciel, où il est à la droite de Dieu, jusqu'à ce qu'il revienne en majesté pour l'accomplissement du royaume de Dieu</li>\n<li>la bonne nouvelle du salut à travers Christ</li>\n<li>la proclamation de la grâce de Dieu manifestée et garantie en Christ</li>\n<li>l'Evangile</li>\n<li>le rang messianique de Jésus étant prouvé par ses paroles, ses actions et sa mort, le récit des dires, des actions et de la mort de Jésus Christ fut appelé l'évangile ou bonne nouvelle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐαγγέλιον, ου (τὸ) :<br>      1</b> récompense, actions de grâces <i>ou</i> sacrifice offert pour une bonne nouvelle, OD. <i>14, 152, 166 ; d’ord. au plur</i>. ESCHN. <i>76, 23 ;</i> PLUT. <i>Sert. 11 ;</i> εὐαγγέλια θύειν, ISOCR. <i>142</i> a ; <i>cf</i>. XÉN. <i>Hell. 4, 3, 14,</i> offrir un sacrifice aux dieux pour une bonne nouvelle ; εὐ. θύειν ἑκατὸν βοῦς τῇ θεῷ, AR. <i>Eq. 656,</i> sacrifier cent bœufs à la déesse pour une bonne nouvelle ; εὐαγγέλια στεφανοῦν τινα, AR. <i>Eq. 647,</i> couronner qqn pour une bonne nouvelle ;<br><b>      2</b> <i>p. ext</i>. bonne nouvelle, CIC. <i>Att. 2, 3, 1 ; 13, 40, 1 ;</i> LUC. <i>As. 26 ;</i> APP. <i>Civ. 3, 93 ; 4, 20 et 143 ;</i><br><b>      3</b> <i>p. suite, au sens chrétien,</i> la bonne nouvelle, <i>càd</i>. la parole de J.C., NT. <i>Matth. 4, 23, etc. ; Marc. 1, 1, etc. ; Ap. 15, 7 ; 20, 4 ; d’où</i> évangile, CLÉM. <i>1, 1193</i> a, <i>1252</i> c.<br><span><b>Étym</b>. εὐάγγελος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαγγελιον - εὐαγγέλιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n76 fois dans 73 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (8)</li>\n<li>Actes (2)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (8)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (7)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (9)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (6)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (3)</li>\n<li>Philémon (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2099":"<h1>euaggelistes</h1>\n<p>Strong n° 2099 <i>Prononciation [yoo-ang-ghel-is-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un messager porteur de bonnes nouvelles</li>\n<li>nom donné dans le N.T à ceux qui annoncent le salut à travers Christ et qui ne sont pas les apôtres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>εὐαγγελιστής, οῦ (ὁ) :<br>      1</b> qui annonce de bonnes nouvelles, CLÉM. <i>1, 1184 Migne ;</i><br><b>      2</b> qui prêche la bonne nouvelle, évangéliste, NT. <i>Ap. 21, 8 ; Eph. 4, 11</i>.<br><span><b>Étym</b>. εὐαγγελίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ευαγγελιστης - εὐαγγελιστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Ephésiens (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>"};
